const BAYNA2_WORDS = [[10001,3,1,1,"اِعْتَنَى بِـ - يَعْتَنِي - اِعْتِنَاء","заботиться (о ком-л./чём-л.) • масдар: забота",["الأم تعتني بطفلها كثيرا",5,10,"Мать очень заботится о своём ребёнке."]],[10002,3,1,1,"العِنَايَة | عِنَايَات","забота, уход",["يجب على الطبيب العناية بالمريض جيدا.",15,22,"Врач должен хорошо заботиться о больном."]],[10003,3,1,1,"شَفَى - يَشْفِي - شِفَاء","исцелять, вылечивать • масдар: исцеление",["شفى الله قلبي عندما تناولت الدواء.",0,3,"Аллах исцелил моё сердце, когда я принял лекарство."]],[10004,3,1,1,"شِفَاء","исцеление, выздоровление",["فى العسل شفاء من الأمراض",9,13,"В мёде — исцеление от болезней."]],[10005,3,1,1,"مَرِيض | مَرْضَى","больной",["أحمد لديه زكام هو مريض.",18,22,"У Ахмада насморк, он болен."]],[10006,3,1,1,"أَلَم | آلَام","боль",["أشعر بألم في قلبي.",5,9,"Я чувствую боль в сердце."]],[10007,3,1,1,"المَعِدَة | مَعِدَات","желудок",["أكل محمد كثيرا فشعر بألم في معدته.",28,33,"Мухаммад много съел и почувствовал боль в желудке."]],[10008,3,1,1,"تَنَاوَلَ - يَتَنَاوَلُ - تَنَاوُل","брать; принимать (пищу, лекарство) • масдар: приём (пищи, лекарства)",["تناولت الكتاب/تناولت الدجاج والعصير.",0,6,"Я взял книгу. / Я поел курицу и выпил сок."]],[10009,3,1,1,"دَوَاء | أَدْوِيَة","лекарство",["العسل دواء لكل مرض.",6,10,"Мёд — лекарство от всякой болезни."]],[10010,3,1,1,"صَحَابِيّ | صَحَابَة","сподвижник Пророка ﷺ",["أبوبكر صحابي من كبار الصحابة.",7,12,"Абу Бакр — сподвижник, один из великих сподвижников."]],[10011,3,1,1,"عَالَجَ - يُعَالِجُ - مُعَالَجَة","лечить • масдар: лечение",["عالج الطبيب ألم المريض.",0,4,"Врач вылечил боль больного."]],[10012,3,1,1,"اِشْتَكَى مِنْ - يَشْتَكِي - اِشْتِكَاء","жаловаться (на кого-л./что-л.) • масдар: жалоба",["اشتكى الطالب من أستاذ المستوى الثالث.",0,5,"Студент пожаловался на преподавателя третьего уровня."]],[10013,3,1,1,"بَطْن | بُطُون، أَبْطُن","живот",["المعدة فى البطن./البطن سبب مرض الإنسان.",10,15,"Желудок находится в животе. / Живот — причина болезней человека."]],[10014,3,1,1,"أَمَرَ بِـ - يَأْمُرُ - أَمْر","приказывать, велеть • масдар: приказ, повеление",["أمر الله بالصلاة ونهى عن شرب الخمر",0,3,"Аллах повелел молитву и запретил пить вино."]],[10015,3,1,1,"سَقَى - يَسْقِي - سَقْي، سِقَايَة","поить; орошать • масдар: поение, орошение",["سقى الأستاذ الطالبَ اللغة العربية.",0,3,"Преподаватель «напоил» студента арабским языком."]],[10016,3,1,1,"مَحَلّ | مَحَلَّات","магазин, лавка; место",["هناك محل لبيع الملابس فى الحي العاشر.",5,8,"В Десятом районе есть магазин одежды."]],[10017,3,1,1,"بَيْع | بُيُوع","продажа",["أحل الله البيع والشراء.",9,14,"Аллах дозволил торговлю (продажу и покупку)."]],[10018,3,1,1,"مَرْكَزِيّ","центральный, главный",["المطعم المركزي فى العاصمة.",7,14,"Центральный ресторан находится в столице."]],[10019,3,1,1,"قَارُورَة | قَوَارِير","бутылка, флакон",["اشتريتُ قارورة ماء من المحل.",8,14,"Я купил бутылку воды в магазине."]],[10020,3,1,1,"أَ...؟","вопросительная частица «ли?, разве?» (= هل)",["أمريض أنت؟",0,0,"Ты болен?"]],[10021,3,1,1,"آلَام شَدِيدَة","сильные боли",["أشعر بآلام شديدة",5,16,"Я чувствую сильные боли."]],[10022,3,1,1,"لَمْ ... وَلَمْ ...","не … и не … (отрицание в прошедшем)",["لم أدرس ولم أكتب الواجب",0,0,"Я не учил и не написал домашнее задание."]],[10023,3,1,1,"عِنْدَمَا","когда (союз)",["عندما يتكلم الأستاذ، لا أتكلم.",0,5,"Когда говорит преподаватель, я не говорю."]],[10024,3,1,1,"سُبْحَانَ اللهِ!","Пречист Аллах! (возглас восхищения, удивления)",null],[10025,3,1,1,"السُّوق المَرْكَزِيّ","центральный рынок",["سأشتري العسل من السوق المركزي",16,29,"Я куплю мёд на центральном рынке."]],[10026,3,1,1,"عَنِيَ بِـ - يَعْنَى - عِنَايَة","уделять внимание, заботиться (о) • масдар: забота, внимание",null],[10027,3,1,1,"شَعَرَ بِـ - يَشْعُرُ - شُعُور","чувствовать • масдар: чувство, ощущение",null],[10028,3,1,1,"بَاعَ - يَبِيعُ - بَيْع","продавать • масдар: продажа",null],[10029,3,1,1,"اِشْتَرَى - يَشْتَرِي - شِرَاء، اِشْتِرَاء","покупать • масдар: покупка",null],[10030,3,1,1,"نَهَى عَنْ - يَنْهَى - نَهْي","запрещать • масдар: запрет",["نهى الإسلام عن شرب الخمر.",0,3,"Ислам запретил пить вино."]],[10031,3,1,2,"صَدِيق | أَصْدِقَاء","друг",["أبوبكر صديق النبي- صلى الله عليه وسلم",7,11,"Абу Бакр — друг Пророка ﷺ."]],[10032,3,1,2,"تَشَابَهَ مَعَ - يَتَشَابَهُ - تَشَابُه","походить друг на друга, быть похожим • масдар: сходство",["تشابه الطالب مع الأستاذ في الوزن",0,5,"Студент похож на преподавателя по весу."]],[10033,3,1,2,"حَيّ | أَحْيَاء","1) живой 2) район (города)",["1- كل حي سيموت. 2- أسكن في الحي العاشر.",6,8,"1) Всё живое умрёт. 2) Я живу в Десятом районе."]],[10034,3,1,2,"أَمْر | أُمُور، أَوَامِر","1) дело, вещь (мн. أمور) 2) приказ (мн. أوامر)",["1- الزواج أمر مهم. 2- أمر الله واجب على كل مسلم.",10,13,"1) Брак — важное дело. 2) Повеление Аллаха обязательно для каждого мусульманина."]],[10035,3,1,2,"نَحِيف | نِحَاف، نُحَفَاء","худой",["وزن محمد مئة كيل هو سمين جدا",0,0,"Вес Мухаммада сто кило, он очень толстый."]],[10036,3,1,2,"اِسْتَطَاعَ أَنْ - يَسْتَطِيعُ - اِسْتِطَاعَة","мочь, быть в состоянии • масдар: способность, возможность",["أنا أستطيع أكل دجاجة وأعجز عن أكل بقرة.",4,10,"Я могу съесть курицу, но не в силах съесть корову."]],[10037,3,1,2,"وَزْن | أَوْزَان","вес",["وزن أخي خمسون كيلا هو نحيف جدا.",0,3,"Вес моего брата — пятьдесят кило, он очень худой."]],[10038,3,1,2,"زَادَ - يَزِيدُ - زِيَادَة","увеличиваться, возрастать; увеличивать • масдар: увеличение",["لا أريد أن يزيد وزني.",11,15,"Я не хочу, чтобы мой вес увеличивался."]],[10039,3,1,2,"حَاوَلَ أَنْ - يُحَاوِلُ - مُحَاوَلَة","пытаться, стараться • масдар: попытка",["حاولت أن أكتب الواجب لكنني عجزت.",0,8,"Я пытался написать домашнее задание, но не смог."]],[10040,3,1,2,"نَجَحَ - يَنْجَحُ - نَجَاح","преуспеть, успешно сдать (экзамен) • масдар: успех",["نجحت فى المستوى الثاني وانتقلت إلى الثالث",0,4,"Я сдал второй уровень и перешёл на третий."]],[10041,3,1,2,"أَخَذَ فِي - يَأْخُذُ - أَخْذ","начать (делать что-л.); брать • масдар: взятие",["أمس أخذت في ممارسة الرياضة لينقص وزني.",4,11,"Вчера я начал заниматься спортом, чтобы похудеть."]],[10042,3,1,2,"المُرَبَّى","варенье, джем",["أحب تناول المربى فى الفطور.",10,16,"Я люблю есть варенье на завтрак."]],[10043,3,1,2,"مَارَسَ - يُمَارِسُ - مُمَارَسَة","заниматься, практиковать • масдар: практика, занятие",["ممارسة اللغة العربية مفيدة جدا.",0,6,"Практика арабского языка очень полезна."]],[10044,3,1,2,"ظَلَّ - يَظَلُّ - ظُلُول","оставаться; продолжать (делать что-л.) • масдар: пребывание",["ظل أحمد في بيته ثلاثة أيام لأنه مريض.",0,2,"Ахмад три дня оставался дома, потому что болен."]],[10045,3,1,2,"النَّشَوِيَّات","крахмалистые продукты, углеводы (картофель, хлеб, рис)",["لا تأكل كثيرا من النشويات",17,25,"Не ешь много крахмалистой пищи."]],[10046,3,1,2,"أَخَذَ فِي + اسْم / أَخَذَ + فِعْل مُضَارِع","начать делать что-л. (أخذ في + имя / أخذ + глагол наст. вр.)",["أخذ الطالب في الكلام /أخذ الطالب يتكلم",0,0,"Студент начал говорить."]],[10047,3,1,2,"وَرَغْمَ ذٰلِكَ","и несмотря на это",["أنا مريض و رغم ذلك ذهبت إلى الدرس",0,0,"Я болен, и несмотря на это пошёл на урок."]],[10048,3,1,2,"يَجِبُ أَنْ","нужно, необходимо, должен",["يجب أن تكتب الواجب",0,6,"Ты должен написать домашнее задание."]],[10049,3,1,2,"نَقَصَ - يَنْقُصُ - نَقْص، نُقْصَان","уменьшаться, убывать • масдар: уменьшение, недостаток",null],[10050,3,1,2,"وَصَلَ إِلَى - يَصِلُ - وُصُول","прибывать, доходить (до) • масдар: прибытие",null],[10051,3,1,2,"اِخْتَلَفَ - يَخْتَلِفُ - اِخْتِلَاف","отличаться, расходиться во мнениях • масдар: различие, разногласие",["ولا تختلفوا فتختلف قلوبكم.",4,11,"Не расходитесь, иначе разойдутся ваши сердца."]],[10052,3,1,3,"اِرْتَفَعَ - يَرْتَفِعُ - اِرْتِفَاع","подниматься, повышаться • масдар: подъём, повышение",["ارتفعت درجة حرارتي.",0,6,"У меня поднялась температура."]],[10053,3,1,3,"مُرْتَفِع","высокий, повышенный",["الضغط مرتفع جدا.",6,11,"Давление очень высокое."]],[10054,3,1,3,"اِعْتَقَدَ أَنَّ - يَعْتَقِدُ - اِعْتِقَاد","считать, полагать; верить • масдар: убеждение, вера",["لا أعتقد أنك مريض يا محمد.",3,12,"Не думаю, что ты болен, Мухаммад."]],[10055,3,1,3,"اِتَّبَعَ - يَتَّبِعُ - اِتِّبَاع","следовать (за кем-л.) • масдар: следование",["أنا أتبع الرسول- صلى الله عليه وسلم- فى كلامه وأفعاله",4,8,"Я следую Посланнику ﷺ в его словах и делах."]],[10056,3,1,3,"الحِمْيَة","диета",["أنا سمين جدا أحتاج للحمية.",19,25,"Я очень толстый, мне нужна диета."]],[10057,3,1,3,"دُهْن | دُهُون","жир",["لا تأكل الدهن لأنه ضار.",8,13,"Не ешь жир, потому что он вреден."]],[10058,3,1,3,"مَشْغُول | مَشْغُولُون","занятой",["أنا مشغول الآن لأنني في درس.",4,9,"Я сейчас занят, потому что у меня урок."]],[10059,3,1,3,"خَطِير","опасный; серьёзный",["الشارع فى أمريكا خطير فى الليل.",17,21,"Улицы в Америке опасны ночью."]],[10060,3,1,3,"دَائِمًا","всегда",["أنا أعمل دائما في النهار.",9,14,"Я всегда работаю днём."]],[10061,3,1,3,"لَا بُدَّ","обязательно, непременно",["لابد من الصلاة فى المسجد.",0,0,"Обязательно молиться в мечети."]],[10062,3,1,3,"وَحْدَهُ","он один, сам (в одиночку)",["سافر أخي إلى مصر وحده.",17,21,"Мой брат поехал в Египет один."]],[10063,3,1,3,"كَفَى - يَكْفِي - كِفَايَة","хватать, быть достаточным • масдар: достаточность",["بيضة واحدة لا تكفي أنا احتاج إلى ثلاث",14,18,"Одного яйца не хватает, мне нужно три."]],[10064,3,1,3,"عَادِيّ","обычный",["المطر فى الشتاء هذا أمر عادي",24,28,"Дождь зимой — обычное дело."]],[10065,3,1,3,"أَحْسَنَ - يُحْسِنُ - إِحْسَان","хорошо делать; делать добро • масдар: благодеяние; мастерство",["أحسن الطالب فى امتحان المستوى الثاني",0,4,"Студент хорошо сдал экзамен второго уровня."]],[10066,3,1,3,"مَاذَا حَدَثَ؟","Что случилось?",["في الشارع ازدحام. ماذا حدث؟",18,26,"На улице пробка. Что случилось?"]],[10067,3,1,3,"أَعْتَقِدُ أَنَّ","я думаю, что…",["أعتقد أنك مريض",0,9,"Думаю, ты болен."]],[10068,3,1,3,"حَالَتُكَ خَطِيرَة","твоё состояние тяжёлое",["حالتك خطيرة. اذهب إلى الطبيب الآن.",0,11,"Твоё состояние тяжёлое. Иди к врачу сейчас же."]],[10069,3,1,3,"لَا بُدَّ مِنْ","обязательно нужно…",["لابد من الصلاة",0,0,"Молитва обязательна."]],[10070,3,1,3,"لَا يَكْفِي","недостаточно",["الواجب وحده لا يكفي. لابد من ممارسة اللغة",12,19,"Одного домашнего задания недостаточно. Обязательно нужна языковая практика."]],[10071,3,1,3,"مَا شَاءَ اللهُ","машаАллах (как пожелал Аллах — выражение восхищения)",["أنت تمارس اللغة. ما شاء الله",17,28,"Ты практикуешь язык. МашаАллах!"]],[10072,3,1,3,"جَزَاكَ اللهُ خَيْرًا","да воздаст тебе Аллах благом (= спасибо)",["جزاك الله خيرا يا أستاذ على صبرك",0,14,"Да воздаст тебе Аллах благом, учитель, за твоё терпение!"]],[10073,3,1,3,"اِنْخَفَضَ - يَنْخَفِضُ - اِنْخِفَاض","понижаться, снижаться • масдар: понижение",null],[10074,3,1,3,"قَابَلَ - يُقَابِلُ - مُقَابَلَة","встречать(ся) с кем-л. • масдар: встреча; собеседование",null],[10075,3,1,3,"حَدَّثَ - يُحَدِّثُ - تَحْدِيث","рассказывать, разговаривать (с кем-л.) • масдар: рассказ, обновление",["حَدَّثنا الإمام حديثا عن النبي صلى الله عليه و سلم",0,8,"Имам рассказал нам хадис от Пророка ﷺ."]],[10076,3,1,4,"الحَاضِر | حَاضِرُون","1) настоящее (время) 2) присутствующий",["المعلم في الماضي أفضل من المعلم في الحاضر.",35,41,"Учитель в прошлом лучше, чем учитель в настоящем."]],[10077,3,1,4,"عَلَامَة | عَلَامَات","признак, знак",["الصلاة في المسجد علامة على الإيمان.",17,22,"Молитва в мечети — признак веры."]],[10078,3,1,4,"الشَّحْم | شُحُوم","жир, сало",["الشخص السمين يتناول كثيرا من الشحوم.",29,35,"Толстый человек ест много жира."]],[10079,3,1,4,"وَجَدَ - يَجِدُ - وُجُود","находить • масдар: нахождение; существование",["وجدت حقيبتي بعد أن فقدتها فى المطار.",0,4,"Я нашёл свою сумку после того, как потерял её в аэропорту."]],[10080,3,1,4,"فَضَّلَ عَلَى - يُفَضِّلُ - تَفْضِيل","предпочитать • масдар: предпочтение",["انا أفضل الشاي بعد الغداء.",4,8,"Я предпочитаю чай после обеда."]],[10081,3,1,4,"تَقَدَّمَ - يَتَقَدَّمُ - تَقَدُّم","продвигаться вперёд, делать успехи • масдар: прогресс, продвижение",["تقدمت فى دراسة اللغة العربية.",0,5,"Я продвинулся в изучении арабского языка."]],[10082,3,1,4,"ظَهَرَ - يَظْهَرُ - ظُهُور","появляться, показываться • масдар: появление",["الشمس تظهر في النهار وتختفي في الليل.",6,10,"Солнце появляется днём и исчезает ночью."]],[10083,3,1,4,"أَصَابَ - يُصِيبُ - إِصَابَة","поражать (о болезни); попадать • масдар: поражение; травма",["أصبتُ بزكام شديد في الليل.",0,0,"Ночью я заболел сильным насморком."]],[10084,3,1,4,"اِبْتَعَدَ عَنْ - يَبْتَعِدُ - اِبْتِعَاد","удаляться, держаться подальше (от) • масдар: удаление",["ابتعد عن الحرام.",0,8,"Держись подальше от запретного."]],[10085,3,1,4,"حَذَّرَ مِنْ - يُحَذِّرُ - تَحْذِير","предостерегать (от) • масдар: предостережение",["حذر النبي - صلى الله عليه وسلم- من النار.",0,0,"Пророк ﷺ предостерёг от Огня."]],[10086,3,1,4,"كَامِل | كَامِلُون","полный, целый",["صام ابني شهر رمضان كاملا.",19,24,"Мой сын постился весь месяц Рамадан."]],[10087,3,1,4,"الدَّسَم","жирность (молока), жир",["لا تشرب الحليب كامل الدسم.",20,25,"Не пей молоко полной жирности."]],[10088,3,1,4,"قَائِلِينَ","говоря, сказав (букв. «говорящие»)",null],[10089,3,1,4,"أَسْرَفَ فِي - يُسْرِفُ - إِسْرَاف","излишествовать, быть расточительным • масдар: расточительство, излишество",["الإسراف فى الوضوء ليس صحيحا.",0,7,"Излишество при омовении — неправильно."]],[10090,3,1,4,"مُسْرِف | مُسْرِفُون","расточительный",["إن الله لا يحب الإنسان المسرف.",23,29,"Аллах не любит расточительного человека."]],[10091,3,1,4,"ضَرَّ - يَضُرُّ - ضَرَر","вредить • масдар: вред",["التلفاز يضر العين",8,11,"Телевизор вредит глазам."]],[10092,3,1,4,"مَلَأَ - يَمْلَأُ - مَلْء","наполнять • масдар: наполнение",["ملأ محمد الكوب ماء",0,3,"Мухаммад наполнил стакан водой."]],[10093,3,1,4,"آدَمِيّ | آدَمِيُّون","человек (потомок Адама)",["أعطى الله الآدمي عقلا ليفكر به.",10,16,"Аллах дал человеку разум, чтобы он думал."]],[10094,3,1,4,"وِعَاء | أَوْعِيَة","сосуд, посуда, ёмкость",["وضع محمد الدجاجة فى الوعاء ليطبخها.",20,26,"Мухаммад положил курицу в посуду, чтобы приготовить её."]],[10095,3,1,4,"شَرّ | شُرُور","зло",["إن الله يحب الخير ويكره الشر.",24,28,"Аллах любит добро и ненавидит зло."]],[10096,3,1,4,"بِحَسْبِ","достаточно (для кого-л.)",["بحسب الإنسان أن يأكل ثلاث مرات في اليوم.",0,4,"Человеку достаточно есть три раза в день."]],[10097,3,1,4,"أُكْلَة | أُكُلَات","кусок, небольшая порция еды",["بحسب الإنسان أكلات.",13,18,"Человеку достаточно нескольких кусочков."]],[10098,3,1,4,"ثُلُث | أَثْلَاث","треть",["أعطيت ثلث نقودي للفقراء.",6,9,"Я отдал треть своих денег бедным."]],[10099,3,1,4,"نَفَس | أَنْفَاس","дыхание, вдох",["يجب أن تأخذ نفسا وأنت تأكل الطعام.",12,16,"Нужно делать вдохи, когда ешь."]],[10100,3,1,4,"الطَّعَام الأَبْيَض","«белая еда» (сахар, белая мука, соль и т. п.)",["ابتعد عن الطعام الأبيض",9,22,"Держись подальше от «белой еды»."]],[10101,3,1,4,"الطَّعَام الأَسْمَر","«тёмная еда» (цельнозерновые продукты)",["تناول الطعام الأسمر",6,19,"Ешь цельнозерновую пищу."]],[10102,3,1,4,"كَامِل الدَّسَم","полной жирности (о молоке)",["الحليب كامل الدسم ضار",7,17,"Молоко полной жирности вредно."]],[10103,3,1,4,"لَا تَأْكُلْ ...، كُلْ ...","не ешь…, ешь…",["لا تأكل الخنزير، كل الدجاج",0,7,"Не ешь свинину, ешь курицу."]],[10104,3,1,4,"اِبْن آدَم","сын Адама, человек",["كل ابن آدم يخطئ",3,10,"Каждый сын Адама ошибается."]],[10105,3,1,4,"يُقِمْنَ صُلْبَهُ","поддерживают его спину (т. е. дают силы)",["ثلاث تمرات يقمن صلب الإنسان",0,0,"Три финика поддерживают силы человека."]],[10106,3,1,4,"لَا مَحَالَةَ","неизбежно, непременно",["لا محالة من يوم القيامة",0,8,"Судный день неизбежен."]],[10107,3,1,4,"أَقَامَ - يُقِيمُ - إِقَامَة","проживать, останавливаться • масдар: проживание",["أقمت في فندق مكة المكرمة",0,0,"Я жил в гостинице «Мекка аль-Мукаррама»."]],[10108,3,2,1,"رَوَّحَ عَنْ - يُرَوِّحُ - تَرْوِيح","развлекаться, отдыхать (душой) • масдар: отдых, развлечение",["يروح محمد عن نفسه فى العطلة.",0,4,"Мухаммад отдыхает (развлекается) на каникулах."]],[10109,3,2,1,"التَّرْوِيح","отдых, развлечение, досуг",["الترويح مفيد للطالب",0,7,"Отдых полезен для студента."]],[10110,3,2,1,"أُغْمِيَ عَلَى - يُغْمَى - إِغْمَاء","упасть в обморок (страд.: «на него нашёл обморок») • масдар: обморок",["أُغمي عليّ لأن الجو كان حارا.",0,10,"Я потерял сознание, потому что было жарко."]],[10111,3,2,1,"عَجِيب","удивительный, странный",["المطر في الصيف أمر عجيب.",19,23,"Дождь летом — удивительное дело."]],[10112,3,2,1,"غَيَّرَ - يُغَيِّرُ - تَغْيِير","менять, изменять • масдар: изменение",["وقع العصير على قميصي فبدلته.",0,0,"Сок пролился на мою рубашку, и я её сменил."]],[10113,3,2,1,"أُسْلُوب | أَسَالِيب","стиль, способ, метод",["أسلوب الأستاذ جميل جدا.",0,5,"Стиль преподавателя очень красивый."]],[10114,3,2,1,"قَصَدَ - يَقْصِدُ - قَصْد","иметь в виду, подразумевать; направляться • масдар: намерение, цель",["ماذا تقصد بهذا الكلام؟",5,9,"Что ты имеешь в виду этими словами?"]],[10115,3,2,1,"صَدَقَ - يَصْدُقُ - صِدْق","говорить правду • масдар: правдивость",["صدق الله العظيم",0,3,"Правду сказал Аллах Великий."]],[10116,3,2,1,"بَلَد | بِلَاد، بُلْدَان","страна",["انا أحب بلدي كثيرا.",8,12,"Я очень люблю свою страну."]],[10117,3,2,1,"طَيِّبَة | طَيِّبَات","хороший, благой",["دراسة اللغة العربية في مصر طيبة.",27,31,"Изучать арабский язык в Египте — хорошо."]],[10118,3,2,1,"نَوْع | أَنْوَاع","вид, сорт, тип",["اشتريت نوعا غاليا من العسل",7,11,"Я купил дорогой сорт мёда."]],[10119,3,2,1,"نَشِيط | نُشَطَاء","активный, бодрый",["فى الصباح أكون نشيطا.",15,20,"Утром я бодр."]],[10120,3,2,1,"نَشَاط | أَنْشِطَة","деятельность, активность, занятие",["سأمارس نشاطا مفيدا فى عطلة الأسبوع.",7,12,"На выходных я займусь чем-нибудь полезным."]],[10121,3,2,1,"عَنَاء","усталость, тяжёлый труд",["أشعر بعد العمل بالعناء",15,22,"После работы я чувствую усталость."]],[10122,3,2,1,"العَامِل | عَامِلُون، عُمَّال","рабочий, работник",["الأستاذ عامل فى المركز.",8,12,"Преподаватель — работник центра."]],[10123,3,2,1,"مُفِيد | مُفِيدُون","полезный",["القراءة هواية مفيدة",14,19,"Чтение — полезное хобби."]],[10124,3,2,1,"عَقْل | عُقُول","разум, ум",["أعطى الله الإنسان العقل ليفكر به",18,23,"Аллах дал человеку разум, чтобы он думал."]],[10125,3,2,1,"جِسْم | أَجْسَام، جُسُوم","тело",["جسم المريض ضعيف.",0,3,"Тело больного слабое."]],[10126,3,2,1,"هَدَف | أَهْدَاف","цель",["هدفي أن أدخل الجنة.",0,4,"Моя цель — войти в Рай."]],[10127,3,2,1,"قَضَى - يَقْضِي - قَضَاء","проводить (время); исполнять, выносить решение • масдар: проведение; суд, исполнение",["أقضي وقت الاستراحة في الفصل.",0,4,"Я провожу перерыв в классе."]],[10128,3,2,1,"حَدِيقَة | حَدَائِق","сад, парк",["امام بيتي حديقة جميلة",10,15,"Перед моим домом красивый сад."]],[10129,3,2,1,"لُعْبَة | أَلْعَاب","игра; игрушка",["على حاسوبي العاب كثيرة وجميلة",11,16,"На моём компьютере много красивых игр."]],[10130,3,2,1,"مَتْحَف | مَتَاحِف","музей",["في القاهرة متاحف كثيرة",11,16,"В Каире много музеев."]],[10131,3,2,1,"فَائِدَة | فَوَائِد","польза",["للقراءة فوائد كثيرة.",8,13,"У чтения много пользы."]],[10132,3,2,1,"مُتْعَة | مُتَع","удовольствие, наслаждение",["على شاطئ البحر أشعر بالمتعة",20,27,"На берегу моря я испытываю удовольствие."]],[10133,3,2,1,"شِعْر | أَشْعَار","поэзия, стихи",["أحب أن أسمع الشعر العربي",12,17,"Я люблю слушать арабскую поэзию."]],[10134,3,2,1,"شَاعِر | شُعَرَاء","поэт",["حسان بن ثابت شاعر الرسول- صلى الله عليه وسلم",13,17,"Хассан ибн Сабит — поэт Посланника ﷺ."]],[10135,3,2,1,"دَعَا إِلَى - يَدْعُو - دَعْوَة","призывать (к) • масдар: призыв",["الإسلام يدعو إلى الجهاد",8,12,"Ислам призывает к джихаду."]],[10136,3,2,1,"القُوَّة","сила",["انا أشعر بالقوة بعد ممارسة الرياضة",9,15,"Я чувствую силу после занятий спортом."]],[10137,3,2,1,"رَمَى - يَرْمِي - رَمْي، رِمَايَة","бросать, метать; стрелять (из лука) • масдар: бросок; стрельба",["تعلم الرماية مفيد للمجاهد.",5,12,"Обучение стрельбе полезно для воина."]],[10138,3,2,1,"الخَيْل | خُيُول","лошади, конница",["أحب ركوب الخيل في القرية",9,14,"Я люблю ездить верхом на лошадях в деревне."]],[10139,3,2,1,"الحَمْدُ لِلّٰهِ عَلَى سَلَامَتِكَ","хвала Аллаху, что ты цел (поздравление с выздоровлением, возвращением)",["الحمدلله على سلامتك يا أبي؟",0,0,"Хвала Аллаху, что ты цел, папа!"]],[10140,3,2,1,"أُغْمِيَ عَلَيَّ","я потерял сознание",["أُغمي على أبي، لأنه مريض بالسكري.",0,9,"Мой отец потерял сознание, потому что болен диабетом."]],[10141,3,2,1,"الأَمْرُ عَجِيب","дело удивительное",["الأمر عجيب جدا",0,10,"Дело очень удивительное."]],[10142,3,2,1,"يَا لَهُ مِنْ","какой же он…! (восклицание, м. р.)",["ياله من طالب مجتهد!",0,0,"Какой же он прилежный студент!"]],[10143,3,2,1,"يَا لَهَا مِنْ","какая же она…! (восклицание, ж. р.)",["يا لها من بنت جميلة!",0,9,"Какая же она красивая девушка!"]],[10144,3,2,1,"قَتْل الوَقْت","убивать время",["الطالب يقتل الوقت بألعاب الحاسوب",0,0,"Студент убивает время компьютерными играми."]],[10145,3,2,1,"قَضَاء الوَقْت","проведение времени",["قضاء الوقت في الحديقة مع الأسرة مفيد",0,10,"Проводить время в парке с семьёй полезно."]],[10146,3,2,1,"إِنَّمَا","только, лишь",["إنما الخالق الله",0,4,"Творец — только Аллах."]],[10147,3,2,1,"لِلتَّرْوِيحِ صُوَر","у отдыха есть (разные) формы",["للترويح صور كثيرة في بلدي",0,11,"В моей стране много видов отдыха."]],[10148,3,2,1,"إِقَامَة المُخَيَّمَات","разбивать лагеря, устраивать кемпинг",["يحب العرب إقامة المخيمات",10,24,"Арабы любят устраивать походные лагеря."]],[10149,3,2,1,"زِيَارَة المَتَاحِف","посещение музеев",["يفضل أخي زيارة المتاحف",9,22,"Мой брат предпочитает посещать музеи."]],[10150,3,2,1,"رُكُوب الخَيْل","верховая езда",["هوايتي ركوب الخيل",7,17,"Моё хобби — верховая езда."]],[10151,3,2,1,"اِحْتَاجَ إِلَى - يَحْتَاجُ - اِحْتِيَاج","нуждаться (в) • масдар: потребность",null],[10152,3,2,1,"أَفَاقَ - يُفِيقُ - إِفَاقَة","приходить в себя, очнуться • масдар: пробуждение, приход в сознание",null],[10153,3,2,1,"نَصَحَ لِـ - يَنْصَحُ - نُصْح، نَصِيحَة","советовать • масдар: совет",null],[10154,3,2,1,"صَادَ - يَصِيدُ - صَيْد","охотиться, ловить (рыбу) • масдар: охота, ловля",null],[10155,3,2,1,"عَلَّمَ - يُعَلِّمُ - تَعْلِيم","учить, обучать • масдар: обучение",null],[10156,3,2,1,"رَكِبَ - يَرْكَبُ - رُكُوب","ехать (верхом, на транспорте), садиться • масдар: езда",null],[10157,3,2,1,"نَشِطَ - يَنْشَطُ - نَشَاط","оживляться, активизироваться • масдар: активность",["ينشط النمل في عمله في غير فصل الشتاء",0,4,"Муравьи активно трудятся во все сезоны, кроме зимы."]],[10158,3,2,2,"العُطْلَة | عُطَل، عُطُلَات","каникулы, отпуск, выходной",["يوم الجمعة عطلة من الدراسة",11,15,"Пятница — выходной от учёбы."]],[10159,3,2,2,"فُرْصَة | فُرَص","возможность, удобный случай",["شهر رمضان فرصة طيبة للعبادة",10,14,"Месяц Рамадан — хорошая возможность для поклонения."]],[10160,3,2,2,"نَادَى - يُنَادِي - نِدَاء، مُنَادَاة","звать, окликать • масдар: зов, обращение",["نادى الأستاذ الطالب بصوت مرتفع",0,4,"Преподаватель позвал студента громким голосом."]],[10161,3,2,2,"نَاقَشَ - يُنَاقِشُ - مُنَاقَشَة","обсуждать, дискутировать • масдар: обсуждение, дискуссия",["يجب على الأب ان يناقش أولاده",16,21,"Отец должен обсуждать (дела) со своими детьми."]],[10162,3,2,2,"حَضَرَ - يَحْضُرُ - حُضُور","приходить, присутствовать • масдар: присутствие",["حضر الطالب مبكرا",0,3,"Студент пришёл рано."]],[10163,3,2,2,"أَرَى","я считаю; я вижу",["أرى أن مصر دولة جميلة. / لا أرى جيدا في الليل.",0,3,"Я считаю, что Египет — красивая страна. / Ночью я плохо вижу."]],[10164,3,2,2,"مَصِيف | مَصَايِف","летний курорт (на море)",["الإسكندرية مصيف لأهل مصر",11,15,"Александрия — летний курорт для жителей Египта."]],[10165,3,2,2,"مَشْتًى | مَشَاتٍ","зимний курорт, место для зимовки",["الأقصر مشتى لأهل مصر",7,11,"Луксор — зимний курорт для жителей Египта."]],[10166,3,2,2,"شَاهَدَ - يُشَاهِدُ - مُشَاهَدَة","смотреть, наблюдать • масдар: просмотр, наблюдение",["شاهد محمد التلفاز",0,4,"Мухаммад посмотрел телевизор."]],[10167,3,2,2,"بَرْنَامَج | بَرَامِج","программа",["برنامج مركز كلمة مفيد جدا",0,6,"Программа центра «Калима» очень полезная."]],[10168,3,2,2,"سَبَحَ - يَسْبَحُ - سِبَاحَة","плавать • масдар: плавание",["أحب السباحة في فصل الصيف",4,11,"Я люблю плавать летом."]],[10169,3,2,2,"سَعِيدَة | سَعِيدَات","счастливая, радостная",["أمي سعيدة لأنني نجحت فى الامتحان",4,9,"Моя мама счастлива, потому что я сдал экзамен."]],[10170,3,2,2,"العُطْلَةُ عَلَى الأَبْوَاب","каникулы на пороге (совсем скоро)",["الإمتحان على الأبواب",0,0,"Экзамен на носу."]],[10171,3,2,2,"فُرْصَة طَيِّبَة","хорошая возможность",["العطلة فرصة طيبة للترويح",7,16,"Каникулы — хорошая возможность отдохнуть."]],[10172,3,2,2,"فِكْرَة طَيِّبَة","хорошая идея",["يالها من فكرة طيبة",9,18,"Какая хорошая идея!"]],[10173,3,2,2,"أَرَى أَنْ… / أَرَى + مَصْدَر","я считаю, что… (أرى أن + глагол / أرى + масдар)",["أرى أن أقابلك غدا. / أرى مقابلتك غدا.",0,0,"Я считаю нужным встретиться с тобой завтра."]],[10174,3,2,2,"لَا مَانِعَ مِنْ","нет препятствий для…, можно",["لا مانع من الكلام بالروسية لكن في الخارج",0,10,"Можно говорить по-русски, но вне (класса)."]],[10175,3,2,2,"عُطْلَة سَعِيدَة","счастливых каникул!",["عطلة سعيدة يا طلاب",0,10,"Счастливых каникул, студенты!"]],[10176,3,2,2,"أَحْضَرَ - يُحْضِرُ - إِحْضَار","приносить, приводить • масдар: доставка, приведение",null],[10177,3,2,3,"خَيَّمَ - يُخَيِّمُ - تَخْيِيم","разбивать лагерь, жить в палатках • масдар: кемпинг, жизнь в палатках",["احب التخييم على شاطئ البحر",4,11,"Я люблю ходить в походы с палатками на берег моря."]],[10178,3,2,3,"مُخَيَّم | مُخَيَّمَات","лагерь (палаточный)",["أقام مركز كلمة في مخيم كبير",18,22,"Центр «Калима» устроил большой лагерь."]],[10179,3,2,3,"لَيْلَة | لَيَالٍ","ночь",["نمت الليلة جيدا",4,10,"Этой ночью я хорошо спал."]],[10180,3,2,3,"عِدَّة","несколько",["سأقيم عدة أيام في المدينة",6,9,"Я пробуду несколько дней в Медине."]],[10181,3,2,3,"البَرّ | بُرُور","суша; пустыня, загород",["سأذهب في العطلة إلى البر",20,24,"На каникулах я поеду за город (в пустыню)."]],[10182,3,2,3,"الغَابَة | غَابَات","лес",["قريتي قريبة من الغابة",15,21,"Моя деревня рядом с лесом."]],[10183,3,2,3,"جَبَل | جِبَال","гора",["وقف المسلمون على جبل عرفات",17,20,"Мусульмане стояли на горе Арафат."]],[10184,3,2,3,"حَيْثُ","где (относит.), там где",["أسكن حيث مركز كلمة",5,8,"Я живу там, где центр «Калима»."]],[10185,3,2,3,"نَقِيّ | أَنْقِيَاء","чистый",["قلب المؤمن نقي مثل الماء",11,14,"Сердце верующего чистое, как вода."]],[10186,3,2,3,"نَصَبَ - يَنْصِبُ - نَصْب","ставить, устанавливать (палатку) • масдар: установка",["نصب محمد خيمة على شاطئ النهر",0,3,"Мухаммад поставил палатку на берегу реки."]],[10187,3,2,3,"وَسِيلَة | وَسَائِل","средство, способ",["القلم وسيلة الكتابة",6,11,"Ручка — средство письма."]],[10188,3,2,3,"فَرِيق | فِرَق، أَفْرِقَاء","команда, группа",["فريق كرة القدم نشيط جدا",0,4,"Футбольная команда очень активная."]],[10189,3,2,3,"أَعَدَّ - يُعِدُّ - إِعْدَاد","готовить, подготавливать • масдар: подготовка",["أعدَّ محمد حقيبته للسفر",0,5,"Мухаммад собрал свою сумку в дорогу."]],[10190,3,2,3,"إِنَاء | آنِيَة، أَوَانٍ","сосуд, посуда",["أحضر صديقي إناء اللحم",11,15,"Мой друг принёс посуду с мясом."]],[10191,3,2,3,"حَمَلَ - يَحْمِلُ - حَمْل","нести, носить • масдар: ношение; беременность",["احمل حقيبتك يا رجل",0,4,"Неси свою сумку, мужик!"]],[10192,3,2,3,"قَدْ يَكُونُ","может быть, возможно",["قد يكون صديقي مريضا",0,7,"Возможно, мой друг болен."]],[10193,3,2,3,"عِدَّة أَسَابِيع","несколько недель",["العطلة عدة أسابيع فقط",7,17,"Каникулы — всего несколько недель."]],[10194,3,2,3,"الهَوَاء النَّقِيّ","чистый воздух",["الهواء نقى في مصر",0,10,"В Египте чистый воздух."]],[10195,3,2,3,"وَسَائِل التَّرْوِيح","средства отдыха, развлечения",["لابد من وسائل الترويح في البر",8,21,"На природе обязательно нужны средства для отдыха."]],[10196,3,2,3,"اِصْطَادَ - يَصْطَادُ - اِصْطِيَاد","охотиться, ловить • масдар: охота",null],[10197,3,2,3,"صَوَّرَ - يُصَوِّرُ - تَصْوِير","фотографировать; изображать • масдар: фотографирование",null],[10198,3,3,1,"زَوَاج","брак, женитьба",["أريد الزواج من امرأة مسلمة",5,11,"Я хочу жениться на мусульманке."]],[10199,3,3,1,"مُتَزَوِّج | مُتَزَوِّجُون","женатый, замужняя",["أخي متزوج قبل ست سنوات",4,9,"Мой брат женат уже шесть лет."]],[10200,3,3,1,"عَلَيْكَ بِـ","держись (за)…, тебе следует…",["عليك بتناول الفطور في الصباح",0,4,"Тебе следует завтракать по утрам."]],[10201,3,3,1,"ذَات | ذَوَات","обладательница, имеющая (ж. р.)",["أختي ذات علم",5,8,"Моя сестра — обладательница знаний."]],[10202,3,3,1,"ذُو | ذَوُو","обладатель, имеющий (м. р.)",["أبي ذو مال كثير",4,6,"У моего отца много денег."]],[10203,3,3,1,"دِين | أَدْيَان","религия",["دين الإسلام دين كامل",0,3,"Ислам — совершенная религия."]],[10204,3,3,1,"قَلِقَ - يَقْلَقُ - قَلَق","беспокоиться • масдар: беспокойство, тревога",["قبل الامتحان أكون قلقا",18,22,"Перед экзаменом я волнуюсь."]],[10205,3,3,1,"وَلَد | أَوْلَاد","мальчик, ребёнок, сын",["لدي ولد وثلاث بنات",4,7,"У меня один сын и три дочери."]],[10206,3,3,1,"فَتَاة | فَتَيَات","девушка",["لدي ولد وثلاث فتيات",14,19,"У меня один сын и три дочери (девушки)."]],[10207,3,3,1,"عَرَفَ - يَعْرِفُ - مَعْرِفَة","знать • масдар: знание, познание",["أنا لا أعرف اللغة الروسية",7,11,"Я не знаю русского языка."]],[10208,3,3,1,"فَقِير | فُقَرَاء","бедный",["كان ابن مسعود رجلا فقيرا",19,24,"Ибн Масуд был бедным человеком."]],[10209,3,3,1,"مَال | أَمْوَال","деньги, имущество",["المال ليس سببا للسعادة",0,5,"Деньги — не причина счастья."]],[10210,3,3,1,"جَمَال","красота",["الجمال نعمة من نعم الله.",0,6,"Красота — одна из милостей Аллаха."]],[10211,3,3,1,"الحَسَب | أَحْسَاب","знатность, благородство происхождения",["كان رسول الله ذا حسب ونسب.",17,20,"Посланник Аллаха был знатного рода и происхождения."]],[10212,3,3,1,"النَّسَب | أَنْسَاب","родословная, происхождение",["كان رسول الله ذا حسب ونسب.",21,25,"Посланник Аллаха был знатного рода и происхождения."]],[10213,3,3,1,"حَقَّقَ - يُحَقِّقُ - تَحْقِيق","осуществлять, достигать • масдар: осуществление; расследование",["النقود لاتحقق السعادة",0,0,"Деньги не приносят счастья."]],[10214,3,3,1,"السَّعَادَة","счастье",["المسلم يشعر بالسعادة دائما",12,20,"Мусульманин всегда чувствует счастье."]],[10215,3,3,1,"قَوْل | أَقْوَال","слово, высказывание",["قول الله حق لا كذب فيه",0,3,"Слово Аллаха — истина, в нём нет лжи."]],[10216,3,3,1,"ظَفِرَ بِـ - يَظْفَرُ - ظَفَر","добиться, получить, одержать победу • масдар: успех, победа",["ظفر بفرصة للجهاد في سبيل الله.",0,3,"Он получил возможность сражаться на пути Аллаха."]],[10217,3,3,1,"عَلَيْكَ بِـ","придерживайся…!",["عليك بالصدق",0,4,"Придерживайся правдивости!"]],[10218,3,3,1,"إِيَّاكَ وَ","остерегайся…!",["إياك و الكذب",0,4,"Остерегайся лжи!"]],[10219,3,3,1,"ذَات الدِّين","религиозная (женщина)",["سأتزوج بذات الدين",7,17,"Я женюсь на религиозной."]],[10220,3,3,1,"لَا مَالَ لَهَا","у неё нет денег",["فاطمة فقيرة لا مال لها",12,22,"Фатима бедна, у неё нет денег."]],[10221,3,3,1,"الحَسَب وَالنَّسَب","знатность и родословная",["الحسب و النسب مهمان لطالب الدنيا",0,0,"Знатность и происхождение важны для ищущего мирского."]],[10222,3,3,1,"يُحَقِّقُ السَّعَادَة","приносит счастье",["اتباع السنة يحقق السعادة",12,24,"Следование Сунне приносит счастье."]],[10223,3,3,1,"تَرِبَتْ يَدَاكَ","«да покроются прахом твои руки» (выражение побуждения, из хадиса)",["تربت يداك يا أخي",0,9,"Да покроются прахом твои руки, брат мой!"]],[10224,3,3,1,"تَزَوَّجَ مِنْ/بِـ - يَتَزَوَّجُ - تَزَوُّج","жениться (на), выйти замуж • масдар: женитьба",null],[10225,3,3,1,"سَعِدَ - يَسْعَدُ - سَعَادَة","быть счастливым • масдар: счастье",null],[10226,3,3,2,"خَيْر","добро, благо",["في ممارسة اللغة خير كثير",16,19,"В языковой практике много пользы."]],[10227,3,3,2,"أَحْيَانًا","иногда",["ألعب الكرة أحيانا",11,17,"Иногда я играю в мяч."]],[10228,3,3,2,"حَقِيقَة | حَقَائِق","истина, правда, факт",["طواف الأرض حول الشمس حقيقة علمية",21,26,"Вращение Земли вокруг Солнца — научный факт."]],[10229,3,3,2,"خِلَاف | خِلَافَات","разногласие, спор",["لا خلاف بين الطلاب في الجنسية",3,7,"Между студентами нет разногласий из-за национальности."]],[10230,3,3,2,"عَجَزَ عَنْ - يَعْجِزُ - عَجْز","быть не в силах, не мочь (сделать) • масдар: бессилие, неспособность",["يعجز أبي عن المشي",0,4,"Мой отец не в состоянии ходить."]],[10231,3,3,2,"حَلّ | حُلُول","решение (проблемы)",["هل لديك حل لهذه المشكلة؟",8,10,"У тебя есть решение этой проблемы?"]],[10232,3,3,2,"شَابّ | شَبَاب","юноша, молодой человек",["أخي شاب من شباب الإسلام",4,7,"Мой брат — один из молодых людей ислама."]],[10233,3,3,2,"بِلَا","без",["كتبت الإمتحان بلا مشكلات",14,17,"Я написал экзамен без проблем."]],[10234,3,3,2,"ثَارَ عَلَى - يَثُورُ - ثَوْرَة","восставать (против); вспыхивать (гневом) • масдар: революция, восстание",["ثار المصريون على رئيسهم",0,0,"Египтяне восстали против своего президента."]],[10235,3,3,2,"رِحْلَة | رِحْلَات","путешествие, поездка",["هناك رحلة إلى القرية لمن يريد",5,9,"Есть поездка в деревню для желающих."]],[10236,3,3,2,"السَّبِيل | سُبُل","путь, дорога",["أدرس في سبيل الله",8,12,"Я учусь на пути Аллаха."]],[10237,3,3,2,"النَّجَاح","успех",["الدراسة سبيل النجاح",13,19,"Учёба — путь к успеху."]],[10238,3,3,2,"شَخْصِيَّة | شَخْصِيَّات","личность, характер",["الأستاذ لديه شخصية قوية في الدرس",13,18,"У преподавателя на уроке сильный характер."]],[10239,3,3,2,"مَرْحَلَة | مَرَاحِل","этап, стадия",["عمر الإنسان ثلاث مراحل",17,22,"Жизнь человека состоит из трёх этапов."]],[10240,3,3,2,"الشَّكْوَى | شَكَاوَى","жалоба",["الشكوى أمر عادي في الزواج",0,6,"Жалобы — обычное дело в браке."]],[10241,3,3,2,"وَقْت | أَوْقَات","время",["أعمل طول الوقت",9,14,"Я работаю всё время."]],[10242,3,3,2,"صَحِيفَة | صُحُف","газета",["أحب قراءة الصحف",10,15,"Я люблю читать газеты."]],[10243,3,3,2,"مَعَ ذٰلِكَ","тем не менее, при этом",["أنا مشغول ومع ذلك أمارس الرياضة",10,17,"Я занят и тем не менее занимаюсь спортом."]],[10244,3,3,2,"عَلَيْنَا أَنْ","мы должны…",["علينا أن نعاهد اليهود",0,8,"Мы должны заключить договор с иудеями."]],[10245,3,3,2,"رِحْلَة طَوِيلَة","долгий путь",["بناء الإسلام رحلة طويلة",13,23,"Строительство ислама — долгий путь."]],[10246,3,3,2,"السَّبِيل إِلَى","путь к…",["الجهاد هو السبيل لبناء الإسلام",0,0,"Джихад — путь к построению ислама."]],[10247,3,3,2,"مِنْ وَقْتٍ لِآخَر","время от времени",["أمارس الرياضة من وقت لأخر",14,25,"Время от времени я занимаюсь спортом."]],[10248,3,3,2,"مَرْحَلَة الطُّفُولَة","детство (этап детства)",["أشعر بمتعة عندما أذكر مرحلة الطفولة",22,35,"Я испытываю удовольствие, когда вспоминаю детство."]],[10249,3,3,2,"تَسْتَمْتِعُ بِـ","наслаждаться (чем-л.)",["أستمتع بمشاهدة التلفاز",0,0,"Я наслаждаюсь просмотром телевизора."]],[10250,3,3,2,"طُول الوَقْت","всё время",["زوجتى طول الوقت في المطبخ",6,15,"Моя жена всё время на кухне."]],[10251,3,3,2,"عَادَ إِلَى - يَعُودُ - عَوْدَة","возвращаться (к, в) • масдар: возвращение",null],[10252,3,3,2,"اِسْتَمْتَعَ بِـ - يَسْتَمْتِعُ - اِسْتِمْتَاع","наслаждаться (чем-л.) • масдар: наслаждение",null],[10253,3,3,2,"شَكَا مِنْ - يَشْكُو - شَكْوَى","жаловаться (на) • масдар: жалоба",["يشكو معظم الفقراء من قِلّة الخدمات",0,4,"Большинство бедных жалуется на нехватку услуг."]],[10254,3,3,3,"سَهِرَ - يَسْهَرُ - سَهَر","не спать ночью, бодрствовать допоздна • масдар: бдение, ночные посиделки",["يسهر الشباب في مصر طول الليل",0,4,"Молодёжь в Египте не спит всю ночь."]],[10255,3,3,3,"عَاشَ - يَعِيشُ - عَيْش، مَعِيشَة","жить • масдар: жизнь, проживание",["أعيش في مدينة نصر",0,4,"Я живу в Мадинат Наср."]],[10256,3,3,3,"أَدْرِي","я знаю",["لا أدرى معنى هذه الكلمة",3,7,"Я не знаю значения этого слова."]],[10257,3,3,3,"مُؤَدَّبَة | مُؤَدَّبَات","воспитанная, вежливая",["ابنتى مؤدبة",6,11,"Моя дочь воспитанная."]],[10258,3,3,3,"مُطِيعَة | مُطِيعَات","послушная",["زوجتى مطيعة",6,11,"Моя жена послушная."]],[10259,3,3,3,"عَنِيدَة | عَنِيدَات","упрямая",["زوجة صديقي عنيدة",11,16,"Жена моего друга упрямая."]],[10260,3,3,3,"مُهْمِلَة | مُهْمِلَات","небрежная, невнимательная",["زوجتي مهملة",6,11,"Моя жена небрежная."]],[10261,3,3,3,"اِهْتَمَّ بِـ - يَهْتَمُّ - اِهْتِمَام","заботиться (о), интересоваться (чем-л.) • масдар: забота, интерес",["الطالب يهتم بواجبه",7,11,"Студент внимательно относится к своему домашнему заданию."]],[10262,3,3,3,"يَتْرُكُ زَوْجَتَهُ","бросает (оставляет) свою жену (разводится)",["ترك صديقي زوجته",0,0,"Мой друг бросил свою жену."]],[10263,3,3,3,"مَاذَا هُنَاكَ؟","Что там такое? В чём дело?",["ماذا هناك؟",0,9,"Что случилось?"]],[10264,3,3,3,"لَا أَدْرِي","не знаю",["لا أدري",0,7,"Не знаю."]],[10265,3,3,3,"بِإِذْنِ اللهِ","с позволения Аллаха (если Аллах позволит)",["سأنجح بإذن الله",6,15,"Я сдам, с позволения Аллаха."]],[10266,3,3,3,"دَرَى - يَدْرِي - دِرَايَة","знать, ведать • масдар: знание, осведомлённость",null],[10267,3,3,3,"أَطَاعَ - يُطِيعُ - إِطَاعَة","слушаться, повиноваться • масдар: повиновение",null],[10268,3,3,3,"تَغَيَّرَ - يَتَغَيَّرُ - تَغَيُّر","меняться, изменяться • масдар: изменение",null],[10269,3,3,3,"أَهْمَلَ - يُهْمِلُ - إِهْمَال","пренебрегать • масдар: небрежность",["من أهمل في حق ربه عاش حزينا",3,7,"Кто пренебрёг правом своего Господа, живёт в печали."]],[10270,3,3,4,"نِظَام | نُظُم، أَنْظِمَة","система, порядок",["نظام المركز طيب.",0,4,"Распорядок центра хороший."]],[10271,3,3,4,"اِخْتِفَاء","исчезновение",["اختفاء الشمس في الليل",0,6,"Исчезновение солнца ночью."]],[10272,3,3,4,"مُجْتَمَع | مُجْتَمَعَات","общество",["أحب الحياة في المجتمع المصري",14,21,"Я люблю жизнь в египетском обществе."]],[10273,3,3,4,"ضَمَّ - يَضُمُّ - ضَمّ","включать, объединять, присоединять • масдар: присоединение",["يضم الفصل طلابا",0,3,"Класс включает студентов."]],[10274,3,3,4,"فَرْد | أَفْرَاد","человек, индивид, член (семьи)",["كم فردا في أسرتك؟",3,7,"Сколько человек в твоей семье?"]],[10275,3,3,4,"ضَعُفَ - يَضْعُفُ - ضَعْف","слабеть • масдар: слабость",["أشعر بضعف",5,9,"Я чувствую слабость."]],[10276,3,3,4,"العَلَاقَة | عَلَاقَات","связь, отношения",["علاقتي بأسرتي ضعيفة",0,6,"Мои отношения с семьёй слабые."]],[10277,3,3,4,"مُعْظَم","большинство",["معظم الطلاب من القوقاز",0,4,"Большинство студентов — с Кавказа."]],[10278,3,3,4,"الصَّبَاح","утро",["أتناول الفطور في الصباح",17,23,"Я завтракаю утром."]],[10279,3,3,4,"وَحْدَهَا","она одна, только она",["لا يجوز السفر للمرأة وحدها",21,26,"Женщине не дозволено путешествовать одной."]],[10280,3,3,4,"الضَّرُورَة","необходимость, крайняя нужда",["آكل الخنزير عند الضرورة فقط",16,23,"Я ем свинину только по крайней необходимости."]],[10281,3,3,4,"نَاحِيَة | نَوَاحٍ","сторона, направление",["المسجد من هذه الناحية",14,21,"Мечеть — с этой стороны."]],[10282,3,3,4,"غَادَرَ - يُغَادِرُ - مُغَادَرَة","покидать, уходить • масдар: уход, отъезд",["غادر الأستاذ الصف",0,4,"Преподаватель вышел из класса."]],[10283,3,3,4,"مُتْعَبَة | مُتْعَبَات","уставшая",["زوجتي متعبة",6,11,"Моя жена устала."]],[10284,3,3,4,"نَظَافَة","чистота",["أنا أعتني بالنظافة",10,18,"Я забочусь о чистоте."]],[10285,3,3,4,"إِعْدَاد","подготовка",["قبل الجهاد لابد من الإعداد",19,26,"Перед джихадом обязательна подготовка."]],[10286,3,3,4,"حَدِيث | أَحَادِيث","1) разговор, беседа 2) новый, современный 3) хадис (слова Пророка)",["هل تقوم بالحديث مع أبنائك",8,15,"Ты разговариваешь со своими детьми?"]],[10287,3,3,4,"مِنْ نَاحِيَةٍ أُخْرَى","с другой стороны",["أعمل و من ناحية أخرى أدرس",7,20,"Я работаю и, с другой стороны, учусь."]],[10288,3,3,4,"مُعْظَم الوَقْت","большую часть времени",["أدرس معظم الوقت",5,15,"Я учусь большую часть времени."]],[10289,3,3,4,"تَقُومُ بِعَمَلِ البَيْت","выполнять (делать) работу по дому",["أقوم بالواجب بعد العشاء",0,0,"Я делаю домашнее задание после ужина."]],[10290,3,3,4,"أُمُور الأَوْلَاد","дела детей",["أعتني بأمور الأولاد.",6,19,"Я забочусь о делах детей."]],[10291,3,3,4,"اِخْتَفَى - يَخْتَفِي - اِخْتِفَاء","исчезать, прятаться • масдар: исчезновение",null],[10292,3,3,4,"رَجَعَ إِلَى - يَرْجِعُ - رُجُوع","возвращаться • масдар: возвращение",null],[10293,3,3,4,"قَامَ - يَقُومُ - قِيَام","вставать; выполнять (بـ) • масдар: вставание; выполнение",null],[10294,3,3,4,"نَظَّفَ - يُنَظِّفُ - تَنْظِيف","чистить, убирать • масдар: уборка, чистка",null],[10295,3,4,1,"عَاصِمَة | عَوَاصِم","столица",["عاصمة روسيا موسكو",0,5,"Столица России — Москва."]],[10296,3,4,1,"رَحَلَ إِلَى - يَرْحَلُ - رَحِيل، رِحْلَة","уезжать, переезжать • масдар: отъезд; путешествие",["أريد أن أرحل إلى السعودية",8,12,"Я хочу уехать в Саудовскую Аравию."]],[10297,3,4,1,"كُلِّيَّة | كُلِّيَّات","факультет, колледж",["أدرس في كلية الهندسة",8,12,"Я учусь на инженерном факультете."]],[10298,3,4,1,"مَزْرَعَة | مَزَارِع","ферма",["أزرع الطماطم في مزرعة عمي",16,21,"Я выращиваю помидоры на ферме дяди."]],[10299,3,4,1,"خَائِف | خَائِفُون","испуганный, боящийся",["الأم خائفة على أولادها",5,10,"Мать боится за своих детей."]],[10300,3,4,1,"حَادِث، حَادِثَة | حَوَادِث","происшествие, авария",["مات أخي في حادث سيارة",11,15,"Мой брат погиб в автомобильной аварии."]],[10301,3,4,1,"مُلَوَّث","загрязнённый",["الهواء ملوث في مصر",7,11,"Воздух в Египте загрязнён."]],[10302,3,4,1,"التَّلَوُّث","загрязнение",["التلوث في مصر كثير",0,6,"Загрязнения в Египте много."]],[10303,3,4,1,"ضَوْضَاء","шум",["في القاهرة الضوضاء شديدة",11,18,"В Каире сильный шум."]],[10304,3,4,1,"اِزْدِحَام","давка, пробка, скопление",["في الشارع ازدحام شديد",10,16,"На улице сильная пробка."]],[10305,3,4,1,"جَار | جِيرَان","сосед",["جاري طبيب",0,4,"Мой сосед — врач."]],[10306,3,4,1,"حَقّ | حُقُوق","1) истина, правда 2) право",["يوم القيامة حق",12,14,"Судный день — истина."]],[10307,3,4,1,"جَزَى - يَجْزِي - جَزَاء","воздавать • масдар: воздаяние",["جزاك الله خيرا",0,0,"Да воздаст тебе Аллах благом!"]],[10308,3,4,1,"مِلْيُون | مَلَايِين","миллион",["في مصر 90 مليون ساكن",10,15,"В Египте 90 миллионов жителей."]],[10309,3,4,1,"وَاجَهَ - يُوَاجِهُ - مُوَاجَهَة","встречать лицом к лицу, сталкиваться • масдар: столкновение, противостояние",["واجهت مشكلة في الامتحان",0,5,"Я столкнулся с проблемой на экзамене."]],[10310,3,4,1,"سَاكِن | سُكَّان","житель",["كم ساكنا في بلدك",3,8,"Сколько жителей в твоей стране?"]],[10311,3,4,1,"الجَرِيمَة | جَرَائِم","преступление",["الجرائم في أمريكا كثيرة",0,7,"В Америке много преступлений."]],[10312,3,4,1,"مَصْنَع | مَصَانِع","завод, фабрика",["في الصين مصانع كثيرة",9,14,"В Китае много заводов."]],[10313,3,4,1,"مَكْتَبَة | مَكْتَبَات","библиотека; книжный магазин",["في المكتبة كتب كثيرة",3,10,"В библиотеке много книг."]],[10314,3,4,1,"مَكَان | أَمَاكِن","место",["الشاطئ مكان طيب للترويح",7,11,"Пляж — хорошее место для отдыха."]],[10315,3,4,1,"اِزْدَادَ - يَزْدَادُ - اِزْدِيَاد","увеличиваться, возрастать • масдар: рост, увеличение",["يزداد طلاب المركز كل يوم",0,5,"Студентов в центре с каждым днём всё больше."]],[10316,3,4,1,"الرِّيف | أَرْيَاف","сельская местность, деревня",["تعيش أسرتي في الريف",14,19,"Моя семья живёт в сельской местности."]],[10317,3,4,1,"هَاجَرَ - يُهَاجِرُ - هِجْرَة، مُهَاجَرَة","переселяться, эмигрировать • масдар: переселение, эмиграция",["هاجر النبي إلى المدينة",0,4,"Пророк переселился в Медину."]],[10318,3,4,1,"الرَّعْي","выпас (скота)",["مهنة موسى رعي الغنم",10,13,"Ремесло Мусы — выпас овец."]],[10319,3,4,1,"رَاعٍ | رُعَاة","пастух",["كان النبي راعيا",0,0,"Пророк был пастухом."]],[10320,3,4,1,"أَدْرَكَ - يُدْرِكُ - إِدْرَاك","постигать, понимать; достигать • масдар: постижение, понимание",["أدركت أنَّ بوتين يحارب الإسلام",0,5,"Я понял, что Путин воюет против ислама."]],[10321,3,4,1,"بَنَى - يَبْنِي - بِنَاء","строить • масдар: строительство",["يبني المهندس بيوتا جميلة",0,4,"Инженер строит красивые дома."]],[10322,3,4,1,"القَرْن | قُرُون","век, столетие",["خير القرون قرن النبي",11,14,"Лучший из веков — век Пророка."]],[10323,3,4,1,"نَحْوَ | أَنْحَاء","около, примерно",["في مصر نحو 90 مليونًا.",7,10,"В Египте около 90 миллионов."]],[10324,3,4,1,"النِّسْبَة | نِسَب","процент, доля, соотношение",["نسبة المسلمين في مصر 90 %",0,4,"Доля мусульман в Египте — 90 %."]],[10325,3,4,1,"بَلَغَ - يَبْلُغُ - بُلُوغ","достигать • масдар: достижение; совершеннолетие",["متى سنبلغ نهاية المركز",4,9,"Когда мы дойдём до конца центра?"]],[10326,3,4,1,"مِلْيَار | مِلْيَارَات","миллиард",["في العالم مليار ونصف المليار مسلم",10,15,"В мире полтора миллиарда мусульман."]],[10327,3,4,1,"هٰذَا حَقّ","это правда",["هذا حق.",0,6,"Это правда."]],[10328,3,4,1,"بِالرَّغْمِ مِنْ","несмотря на",["حضرت بالرغم من مرضي",5,14,"Я пришёл, несмотря на болезнь."]],[10329,3,4,1,"تَرَكَ - يَتْرُكُ - تَرْك","оставлять, бросать • масдар: оставление",null],[10330,3,4,1,"مَاتَ - يَمُوتُ - مَوْت","умирать • масдар: смерть",null],[10331,3,4,1,"لَوَّثَ - يُلَوِّثُ - تَلْوِيث","загрязнять • масдар: загрязнение",null],[10332,3,4,1,"اِزْدَحَمَ - يَزْدَحِمُ - اِزْدِحَام","толпиться, быть переполненным • масдар: давка, пробка",null],[10333,3,4,1,"زَرَعَ - يَزْرَعُ - زَرْع، زِرَاعَة","сеять, выращивать • масдар: посев, земледелие",null],[10334,3,4,1,"رَعَى - يَرْعَى - رَعْي، رِعَايَة","пасти; опекать • масдар: выпас; забота",null],[10335,3,4,2,"الطَّرِيق | طُرُق","дорога, путь",["هذا هو الطريق إلى المسجد",7,13,"Вот дорога к мечети."]],[10336,3,4,2,"سَاقَ - يَسُوقُ - سَوْق، سِيَاقَة","водить, вести (машину), гнать • масдар: вождение",["هل تستطيع أن تسوق السيارة؟",13,17,"Ты умеешь водить машину?"]],[10337,3,4,2,"سَائِق | سَائِقُون","водитель",["سائق الحافلة في مصر مجنون.",0,4,"Водители автобусов в Египте — сумасшедшие."]],[10338,3,4,2,"مَرَّ بِـ - يَمُرُّ - مُرُور","проходить (мимо), проезжать • масдар: прохождение; движение",["أمرَّ كل يوم برجل المرور",0,5,"Каждый день я прохожу мимо регулировщика."]],[10339,3,4,2,"وَقَعَ - يَقَعُ - وُقُوع","находиться, располагаться; падать; случаться • масдар: падение; происшествие",["أين يقع المركز",4,7,"Где находится центр?"]],[10340,3,4,2,"اِتَّجَهَ إِلَى - يَتَّجِهُ - اِتِّجَاه","направляться (к) • масдар: направление",["في الصلاة نتجه إلى القبلة",10,14,"В молитве мы обращаемся к кибле."]],[10341,3,4,2,"اِتِّجَاه | اِتِّجَاهَات","направление",["اتجاه القبلة إلى اليمين قليلا",0,5,"Направление на киблу — немного направо."]],[10342,3,4,2,"إِشَارَة | إِشَارَات","знак, сигнал",["ما رأيت في مصر إشارات ضوئية",15,21,"Я не видел в Египте светофоров."]],[10343,3,4,2,"اِنْعَطَفَ - يَنْعَطِفُ - اِنْعِطَاف","поворачивать • масдар: поворот",["انعطف يمينا",0,5,"Поверни направо."]],[10344,3,4,2,"يَسَار","лево, левая сторона",["انعطف يسارًا",6,12,"Поверни налево."]],[10345,3,4,2,"دَوَّار | دَوَّارَات","круговой перекрёсток, кольцо",["سيجد المركز بعد الدوار الأول.",16,22,"Он найдёт центр после первого кольца."]],[10346,3,4,2,"صَيْدَلِيَّة | صَيْدَلِيَّات","аптека",["نشتري الدواء من الصيدلية",16,24,"Мы покупаем лекарства в аптеке."]],[10347,3,4,2,"الزَّاوِيَة | زَوَايَا","угол",["في المثلث ثلاث زوايا",15,20,"В треугольнике три угла."]],[10348,3,4,2,"اِسْتَمَرَّ فِي - يَسْتَمِرُّ - اِسْتِمْرَار","продолжать(ся) • масдар: продолжение",["سأستمر في طريق طلب العلم",0,9,"Я буду продолжать путь поиска знаний."]],[10349,3,4,2,"مُقَابِل","напротив",["المركز مقابل المسجد",7,12,"Центр — напротив мечети."]],[10350,3,4,2,"الكُبْرَى | كُبْرَيَات، كُبَر","большая, крупная (ж. р. от أكبر), великая",["أمريكا من الدول الكبرى",16,22,"Америка — одна из крупных держав."]],[10351,3,4,2,"مَقَرّ | مَقَرَّات، مَقَارّ","резиденция, штаб-квартира, местонахождение",["أين مقر المركز؟",4,7,"Где находится центр (его здание)?"]],[10352,3,4,2,"مَصْرِف | مَصَارِف","банк",["أغير النقود من المصرف",15,21,"Я меняю деньги в банке."]],[10353,3,4,2,"كَثُرَ - يَكْثُرُ - كَثْرَة","становиться многочисленным, умножаться • масдар: обилие",["تكثر الجرائم في الدول",0,4,"В странах становится всё больше преступлений."]],[10354,3,4,2,"عِمَارَة | عِمَارَات","многоэтажный дом, здание",["تكثر العمارات العالية في دبيّ",5,13,"В Дубае много высоких зданий."]],[10355,3,4,2,"عَالِيَة","высокая",["أخذ الطالب درجة عالية",16,21,"Студент получил высокую оценку."]],[10356,3,4,2,"أَنْشَأَ - يُنْشِئُ - إِنْشَاء","основывать, создавать • масдар: основание, создание",["أنشأ الأساتذة مركز كلمة",0,4,"Преподаватели основали центр «Калима»."]],[10357,3,4,2,"تَلَوُّث","загрязнение",["يكثر التلوث في المدن",5,11,"В городах много загрязнения."]],[10358,3,4,2,"زِلْزَال | زَلَازِل","землетрясение",["تكثر الزلازل في اليابان",5,12,"В Японии много землетрясений."]],[10359,3,4,2,"نَهْر | أَنْهَار","река",["نهر النيل من أنهار الجنة",0,3,"Нил — одна из рек Рая."]],[10360,3,4,2,"أَثَر | آثَار","след; памятник старины (мн. древности)",["في المتحف المصري آثار فرعون.",17,21,"В Египетском музее — древности фараонов."]],[10361,3,4,2,"اِشْتَهَرَ بِـ - يَشْتَهِرُ - اِشْتِهَار","прославиться, быть известным (чем-л.) • масдар: известность",["تشتهر مصر بالفول",0,5,"Египет славится бобами (фулем)."]],[10362,3,4,2,"مِئْذَنَة | مَآذِن","минарет",["المئذنة عالية جدا",0,7,"Минарет очень высокий."]],[10363,3,4,2,"وِلَايَة | وِلَايَات","провинция; штат",["مصر كانت ولاية من ولايات الخلافة",9,14,"Египет был одной из провинций халифата."]],[10364,3,4,2,"مُتَّحِدَة | مُتَّحِدَات","объединённая, единая",["كانت الأمة الإسلامية متحدة",21,26,"Исламская умма была единой."]],[10365,3,4,2,"أُمَّة | أُمَم","народ, нация, община (умма)",["أحب أمة النبي",4,7,"Я люблю общину Пророка."]],[10366,3,4,2,"نَاطِحَة سَحَاب | نَاطِحَات سَحَاب","небоскрёб",["في دبيّ ناطحات سحاب كثيرة",8,19,"В Дубае много небоскрёбов."]],[10367,3,4,2,"جَرِيمَة | جَرَائِم","преступление",["تقل الجريمة في دولة الشريعة",4,11,"Преступлений мало в государстве шариата."]],[10368,3,4,2,"مُجْرِم | مُجْرِمُون","преступник",["تترك الشرطة المجرمين في مصر",12,20,"Полиция в Египте оставляет преступников (на свободе)."]],[10369,3,4,2,"مُخَدِّرَات","наркотики",["المجرم يتناول كثيراً من المخدرات",24,32,"Преступник употребляет много наркотиков."]],[10370,3,4,2,"اِلْتَحَقَ بِـ - يَلْتَحِقُ - اِلْتِحَاق","поступать, присоединяться (к) • масдар: поступление",["التحقت بمعهد لدراسة الثقافة الإسلامية - التحقت بشركة للعمل في مجال الحاسوب",0,6,"Я поступил в институт изучать исламскую культуру. / Я устроился в компанию работать в сфере компьютеров."]],[10371,3,4,2,"قَدَّمَ لِـ - يُقَدِّمُ - تَقْدِيم","преподносить, представлять, подавать • масдар: подношение, представление",["قدمت لأبي دليلاً على صحة كلامي.",0,4,"Я представил отцу доказательство правоты своих слов."]],[10372,3,4,2,"قَبِلَ - يَقْبَلُ - قَبُول","принимать, соглашаться • масдар: принятие",["قبِل الله دعائي و رزقني زوجة صالحةٍ.",0,4,"Аллах принял мою мольбу и даровал мне праведную жену."]],[10373,3,4,2,"تَقْدِير | تَقْدِيرَات، تَقَادِير","оценка (отметка)",["كان تقديري ممتازا في المرحلة الثانوية.",4,10,"Моя оценка в средней школе была «отлично»."]],[10374,3,4,2,"رَغِبَ فِي - يَرْغَبُ - رَغْبَة","желать, стремиться (к) • масдар: желание",["علّمني أبي أن أرغب في الحلال وأرغب عن الحرام.",14,18,"Отец научил меня стремиться к дозволенному и отвращаться от запретного."]],[10375,3,4,2,"حَصَلَ عَلَى - يَحْصُلُ - حُصُول","получать, добиваться • масдар: получение",["قَدمت إلى مصر لأحصل على هدفي.",14,19,"Я приехал в Египет, чтобы добиться своей цели."]],[10376,3,4,2,"صَحِيح | أَصِحَّاء، صِحَاح","1) верный, правильный, достоверный 2) здоровый",["قرأت تفسيرا لحديث صحيح. اللهم اجعلنى صحيحا طول حياتي.",18,22,"Я прочитал толкование достоверного хадиса. / О Аллах, сделай меня здоровым всю мою жизнь."]],[10377,3,4,2,"قِسْم | أَقْسَام","отдел, отделение, кафедра; часть",["أفضل الالتحاق بقسم الشريعة.",14,18,"Я предпочитаю поступить на отделение шариата."]],[10378,3,4,2,"عَمِيد | عُمَدَاء","декан",["أرجو أن يقبل العميد أوراقي.",13,19,"Надеюсь, декан примет мои документы."]],[10379,3,4,2,"وَافَقَ عَلَى - يُوَافِقُ - مُوَافَقَة","соглашаться (с, на) • масдар: согласие",["لن أوافق أحدا على شر أبداً.",3,8,"Я никогда ни с кем не соглашусь на зло."]],[10380,3,4,2,"وَفَّقَهُ اللهُ","Аллах даровал ему успех (помог ему)",["اللهم وفقني في الدعوة إلى دينك.",0,0,"О Аллах, даруй мне успех в призыве к Твоей религии."]],[10381,3,4,2,"لَوْ سَمَحْتَ","пожалуйста, если позволите",["لو سمحت. أين يقع المركز؟",0,7,"Простите, где находится центр?"]],[10382,3,4,2,"إِشَارَة ضَوْئِيَّة","светофор",["لم أر في مصر إشارة ضوئية",13,24,"Я не видел в Египте светофоров."]],[10383,3,4,2,"الاِتِّجَاهَات الأَرْبَعَة","четыре стороны света (север, юг, восток, запад)",null],[10384,3,4,2,"الطَّرِيق نَفْسُهُ","тот же путь",["ارجع في الطريق نفسه",8,19,"Вернись той же дорогой."]],[10385,3,4,2,"شُكْرًا","спасибо",["شكرا يا أستاذ",0,4,"Спасибо, учитель."]],[10386,3,4,2,"اِشْتَهَرَ بِـ","прославиться, быть известным (чем-л.)",["تشتهر دمشق بالياسمين.",0,0,"Дамаск славится жасмином."]],[10387,3,4,2,"نَاطِحَات السَّحَاب","небоскрёбы",["في ماليزيا ناطحات السحاب",11,24,"В Малайзии есть небоскрёбы."]],[10388,3,4,2,"الوِلَايَات المُتَّحِدَة الأَمْرِيكِيَّة","Соединённые Штаты Америки (США)",["عاصمة الولايات المتحدة الأمريكية واشنطن.",6,32,"Столица США — Вашингтон."]],[10389,3,4,2,"الأُمَم المُتَّحِدَة","Организация Объединённых Наций (ООН)",["مقر الأمم المتحدة في نيويورك.",4,17,"Штаб-квартира ООН находится в Нью-Йорке."]],[10390,3,4,2,"العُلُوم الطَّبِيعِيَّة","естественные науки (физика, биология, геология)",["دراسة العلوم الطبيعية تساعد على فهم الدين.",6,21,"Изучение естественных наук помогает понимать религию."]],[10391,3,4,2,"لَا عَجَبَ فِي","неудивительно, что…",["لا عجب أن الله قدير على كل شئ.",0,0,"Неудивительно, что Аллах властен над всякой вещью."]],[10392,3,4,2,"وَفَّقَكَ اللهُ","да поможет тебе Аллах (да дарует успех)",["ادع لنا بالتوفيق حتى يوفقنا الله.",0,0,"Помолись за нас об успехе, чтобы Аллах помог нам."]],[10393,3,4,2,"وَفَّقَ - يُوَفِّقُ - تَوْفِيق","даровать успех, помогать (о Аллахе) • масдар: успех, удача",null],[10394,3,5,1,"اِخْتِلَاف | اِخْتِلَافَات","разногласие, различие",["الاختلاف في الرأي بين المسلمين وسيلة لنشر الفتنة.",0,8,"Разногласия во мнениях между мусульманами — средство распространения смуты."]],[10395,3,5,1,"غَنِيّ | أَغْنِيَاء","богатый",["الغني من ارتفعت نفسه عن الحرام ولو كثر.",0,5,"Богат тот, чья душа выше запретного, даже если его (запретного) много."]],[10396,3,5,1,"وَطَن | أَوْطَان","родина",["لوطني عليّ حق الاهتمام به.",0,5,"Я обязан заботиться о своей родине."]],[10397,3,5,1,"مُوَاطِن | مُوَاطِنُون","гражданин",["فرص المواطن الأوربي كثيرة في.........",4,11,"У европейского гражданина много возможностей в …"]],[10398,3,5,1,"اِنْتَشَرَ فِي - يَنْتَشِرُ - اِنْتِشَار","распространяться • масдар: распространение",["انتشر الخلاف بين مسلمي العالم.",0,5,"Разногласия распространились среди мусульман мира."]],[10399,3,5,1,"القَوْل | أَقْوَال","слово, высказывание",["القول قول من لديه خبره في الحياة.",0,5,"Слово — за тем, у кого есть жизненный опыт."]],[10400,3,5,1,"التَّعَب","усталость",["ما شعرت بتعب في العبادة قط.",8,12,"Я никогда не чувствовал усталости в поклонении."]],[10401,3,5,1,"سَارَ - يَسِيرُ - سَيْر","идти, двигаться • масдар: ходьба, движение",["و من لم يسر في طريق العلماء، فلن يحصل على علم.",0,0,"Кто не пойдёт по пути учёных, тот не получит знаний."]],[10402,3,5,1,"دَوْلِيَّة","международная",["الشركات الدولية أفضل من المحلية.",8,15,"Международные компании лучше местных."]],[10403,3,5,1,"أَجْر | أُجُور","плата, зарплата; награда (от Аллаха)",["عملت الخير و كان أجري على الله.",17,21,"Я сделал добро, и моя награда — у Аллаха."]],[10404,3,5,1,"الشَّهَادَة / الإِجَازَة | شَهَادَات","диплом, свидетельство; иджаза (разрешение)",["حصلت على شهادة في علم الصرف.",0,0,"Я получил диплом по морфологии."]],[10405,3,5,1,"فِي الغَالِب","в основном, чаще всего",["في الغالب أذهب للمركز سيرا على قدمي.",0,9,"Чаще всего я хожу в центр пешком."]],[10406,3,5,1,"أَمَّا اليَوْمَ","что же до сегодняшнего дня…",["كنت مهملاً في طفولتي أما اليوم فأنا أتبع النظام.",21,30,"В детстве я был небрежным, а сегодня я соблюдаю порядок."]],[10407,3,5,1,"سَيْرًا عَلَى الأَقْدَام","пешком",["أرغب في الاعتماد ولو ذهبت سيرا على الأقدام.",26,42,"Я хочу полагаться на себя, даже если придётся идти пешком."]],[10408,3,5,1,"عَنْ طَرِيقِ","посредством, через",["أصبحت ممتازا عن طريق مصاحبة المُهتَميِّن المجتهدين",13,20,"Я стал отличником благодаря общению с внимательными и прилежными."]],[10409,3,5,1,"الشَّبَكَة الدَّوْلِيَّة","Интернет (всемирная сеть)",["الشبكة الدولية وسيلة لجمع المال.",0,14,"Интернет — средство заработка денег."]],[10410,3,5,1,"اِخْتَلَفَ الأَمْرُ","дело изменилось, ситуация стала иной",["اختلف أمر التربية بين الريف و القرية.",0,9,"Воспитание в сельской местности и в деревне различается."]],[10411,3,5,1,"شَاعَ - يَشِيعُ - شُيُوع","распространяться (о вести, явлении) • масдар: распространение",null],[10412,3,5,1,"تَعَلَّمَ - يَتَعَلَّمُ - تَعَلُّم","учиться, изучать • масдар: обучение, изучение",null],[10413,3,5,1,"طَلَبَ - يَطْلُبُ - طَلَب","просить, требовать; искать • масдар: просьба, требование",null],[10414,3,5,1,"فَكَّرَ فِي - يُفَكِّرُ - تَفْكِير","думать (о) • масдар: мышление, размышление",null],[10415,3,5,2,"حَضَارَة | حَضَارَات","цивилизация",["تأثرت حضارات العرب بالحضارة الإسلامية.",19,27,"Арабские цивилизации испытали влияние исламской цивилизации."]],[10416,3,5,2,"عَظِيمَة | عَظِيمَات، عَظَائِم","великая",["السيدة خديجة كانت امرأة عظيمة.",24,29,"Госпожа Хадиджа была великой женщиной."]],[10417,3,5,2,"الصَّيْدَلَة","фармакология, фармация",["علم الصيدلة لاحياة بدونه.",4,11,"Без фармакологии невозможна жизнь."]],[10418,3,5,2,"الرِّيَاضِيَّات","математика",["بدون الرياضيات ما وصلنا القمر.",5,14,"Без математики мы бы не долетели до Луны."]],[10419,3,5,2,"الجُغْرَافِيَا","география",["أرجو أن أكون عالماًفي الجغرافيا.",22,31,"Надеюсь стать учёным в географии."]],[10420,3,5,2,"الفَلَك | أَفْلَاك","астрономия; небесная орбита",["لم أرغب يوما عن دراسة الفلك.",22,27,"Я никогда не отказывался от изучения астрономии."]],[10421,3,5,2,"تَأَثَّرَ بِـ - يَتَأَثَّرُ - تَأَثُّر","испытывать влияние (кого-л.) • масдар: влияние (на себя)",["و ما تأثرت بأحد إلا الرسول صلى الله عليه وسلم",5,10,"Ни на кого я не равнялся, кроме Посланника ﷺ."]],[10422,3,5,2,"أَثَّرَ فِي - يُؤَثِّرُ - تَأْثِير","влиять (на) • масдар: влияние",["لا بد أن يؤثر العلماء في طالبي العلم.",9,13,"Учёные обязательно должны влиять на ищущих знания."]],[10423,3,5,2,"اِتَّصَلَ بِـ - يَتَّصِلُ - اِتِّصَال","связываться (с), соединяться • масдар: связь, контакт",["الصلاة اتصال بيني و بين ربي.",7,12,"Молитва — связь между мной и моим Господом."]],[10424,3,5,2,"أَخَذَ عَنْهُ العِلْمَ","перенять у него знания, учиться у него",["دعوت لكل من اخذت العلم عنهم.",0,0,"Я молился за всех, у кого учился."]],[10425,3,5,2,"تَرْجَمَ - يُتَرْجِمُ - تَرْجَمَة","переводить • масдар: перевод",["درست جيدا لأكون مترجماًلعلوم الدين.",0,0,"Я хорошо учился, чтобы стать переводчиком религиозных наук."]],[10426,3,5,2,"فَرِيضَة | فَرَائِض","обязанность (религиозная), фард",["طلب العلم فريضة على كل مسلم.",10,15,"Поиск знаний — обязанность каждого мусульманина."]],[10427,3,5,2,"جَمِيع","все, всё",["طلبت من الجميع أن يدعوا لي عند مرضي.",8,14,"Я попросил всех молиться за меня, когда я болел."]],[10428,3,5,2,"العُلُوم الإِنْسَانِيَّة","гуманитарные науки (история, психология, социология, философия)",["ما أكثر احتياجنا للعلوم الإنسانية.",17,33,"Как сильно мы нуждаемся в гуманитарных науках!"]],[10429,3,5,2,"مَرَّة أُخْرَى","ещё раз, снова",["أ أهملت واجباتك مرة أخرى؟!",16,24,"Ты снова пренебрёг своими заданиями?!"]],[10430,3,5,2,"هَا هِيَ","вот она (указательная частица)",["و هاهي الدنيا تنشر فتنها للجميع.",0,0,"И вот мир распространяет свои соблазны на всех."]],[10431,3,5,2,"طُولَ حَيَاتِهِ","всю (свою) жизнь",["أكرم الله أبَوَيّ طول حياتهما.",0,0,"Да почтит Аллах моих родителей всю их жизнь."]],[10432,3,5,3,"مُخْتَلِفَة","разная, различная",["الأفكار مختلفة بين الغرب و الشرق.",8,14,"Взгляды на Западе и Востоке различны."]],[10433,3,5,3,"خِلَالَ","в течение, во время; среди",["سأسبح خلال صفحات الكتاب.",6,10,"Я «поплаваю» по страницам книги."]],[10434,3,5,3,"أَنْهَى - يُنْهِي - إِنْهَاء","заканчивать, завершать • масдар: завершение",["لابد أن تنهي وسوسة الشيطان بالذكر.",8,12,"Нужно прекращать шайтанское наущение поминанием Аллаха."]],[10435,3,5,3,"تَكَوَّنَ مِنْ - يَتَكَوَّنُ - تَكَوُّن","состоять (из) • масдар: образование, формирование",["تتكون الكلمة من حروف و الجملة من كلمات.",0,5,"Слово состоит из букв, а предложение — из слов."]],[10436,3,5,3,"عَادَةً","обычно",["عادة ما أوفر النقود في المصرف.",0,4,"Обычно я храню деньги в банке."]],[10437,3,5,3,"عُمْر | أَعْمَار","возраст; жизнь",["عمري يتراوح بين الشيوخ و الشباب.",0,4,"Мой возраст — между стариками и молодыми."]],[10438,3,5,3,"تَرَاوَحَ بَيْنَ - يَتَرَاوَحُ - تَرَاوُح","колебаться (в пределах), варьироваться (между) • масдар: колебание",["تتراوح درجة الحرارة بين ثلاثين و خمسة و ثلاثين.",0,6,"Температура колеблется между тридцатью и тридцатью пятью."]],[10439,3,5,3,"العُلْيَا","высшая, верхняя",["أرجو أن أصل إلى الدرجات العليا في العلم.",24,30,"Надеюсь достичь высших степеней в знаниях."]],[10440,3,5,3,"أَشْرَفَ عَلَى - يُشْرِفُ - إِشْرَاف","руководить, курировать, надзирать • масдар: руководство, надзор",["أشرفت على عمال الشركة بعناية.",0,9,"Я внимательно руководил рабочими компании."]],[10441,3,5,3,"وَفَّرَ - يُوَفِّرُ - تَوْفِير","обеспечивать; экономить, копить • масдар: обеспечение; экономия",["سأوفر طاقتي لقيام الليل.",0,5,"Я сберегу силы для ночной молитвы."]],[10442,3,5,3,"أَهْلِيّ","частный; народный, семейный",["يوم القيامة لن ينفعنا أهلنا و أصدقاؤنا.",0,0,"В Судный день нам не помогут ни родные, ни друзья."]],[10443,3,5,3,"جَمْعِيَّة | جَمْعِيَّات","общество, ассоциация, организация",["البقاء في جمعية الخير أفضل أوقات حياتي.",10,15,"Пребывание в благотворительном обществе — лучшее время моей жизни."]],[10444,3,5,3,"تَقْدِير طَيِّب","хорошая оценка",["لكل مجتهد تقدير طيب.",10,19,"Каждому прилежному — хорошая оценка."]],[10445,3,5,3,"الدِّرَاسَات العُلْيَا","аспирантура, высшее образование (магистратура и докторантура)",["الدراسات العليا هي بداية العلم.",0,15,"Высшее образование — это начало науки."]],[10446,3,5,3,"التَّعْلِيم الحُكُومِيّ","государственное образование",["قضيت وقتي في مدارس التعليم الحكوميّ.",19,35,"Я провёл время в государственных школах."]],[10447,3,6,1,"مِهْنَة | مِهَن","профессия, ремесло",["مهنتى الأساسية هي الدعوة للإسلام.",0,5,"Моя основная профессия — призыв к исламу."]],[10448,3,6,1,"بَحَثَ عَنْ - يَبْحَثُ - بَحْث","искать • масдар: поиск; исследование",["بحثت عن كل سبل النجاح في الدنيا.",0,7,"Я искал все пути к успеху в этом мире."]],[10449,3,6,1,"لَعَلَّ","может быть, возможно; надеюсь",["لعل الله يرحمنا",0,3,"Может быть, Аллах помилует нас."]],[10450,3,6,1,"المُقَابَلَة | مُقَابَلَات","встреча, собеседование, интервью",["سيأتي يوم المقابلة بيني و بين ربي.",10,18,"Придёт день встречи между мной и моим Господом."]],[10451,3,6,1,"مُتَفَائِل | مُتَفَائِلُون","оптимист, оптимистичный",["أنا متفائل لأنني أتوكل على الله.",4,10,"Я оптимист, потому что уповаю на Аллаха."]],[10452,3,6,1,"خِبْرَة | خِبْرَات","опыт",["جدي شيخ ذو خبرة طويلة في الحياة.",11,15,"Мой дед — старик с большим жизненным опытом."]],[10453,3,6,1,"مُنَاسِب","подходящий",["العاقل من يقول كلاماًمناسباًفي أوقات مناسبة.",37,43,"Разумный — тот, кто говорит уместные слова в подходящее время."]],[10454,3,6,1,"تَخَرَّجَ فِي - يَتَخَرَّجُ - تَخَرُّج","окончить (учебное заведение) • масдар: окончание, выпуск",["كلية اللغات صعبة لعلي أتخرج فيها.",22,27,"Факультет языков трудный, может, мне удастся его окончить."]],[10455,3,6,1,"مُنْذُ","с (какого-л. времени), с тех пор как",["حفظت كتاب الله منذ أن كنت طفلاً.",15,18,"Я выучил Книгу Аллаха с тех пор, как был ребёнком."]],[10456,3,6,1,"البَطَالَة","безработица",["عمت البطالة البرّ و البَحر.",4,11,"Безработица охватила и сушу, и море."]],[10457,3,6,1,"عَمَّ - يَعُمُّ - عُمُوم","охватывать, распространяться • масдар: распространение, всеобщность",["سيعم الإسلام العالم بقلمي و فكري.",0,4,"Ислам распространится по миру моим пером и мыслью."]],[10458,3,6,1,"عَامّ","общий, всеобщий",["الأمر بالمعروف قول عام لكل كبير وصغير.",19,22,"Повеление одобряемого — общий призыв для каждого, большого и малого."]],[10459,3,6,1,"عَاطِل | عَاطِلُون","безработный",["جاري عاطل عن العمل.",5,9,"Мой сосед безработный."]],[10460,3,6,1,"كُنْ مُتَفَائِلًا","будь оптимистом",["من يبتسم في وجهي يجعلني متفائلاً.",0,0,"Кто улыбается мне, делает меня оптимистом."]],[10461,3,6,1,"تَفَاءَلَ - يَتَفَاءَلُ - تَفَاؤُل","быть оптимистом, надеяться на лучшее • масдар: оптимизм",null],[10462,3,6,1,"أَرَادَ - يُرِيدُ - إِرَادَة","хотеть • масдар: воля, желание",null],[10463,3,6,2,"فِرْقَة | فِرَق","группа, отряд; труппа",["كن مصاحبا لفرقة الأتقياء.",10,15,"Будь в компании богобоязненных."]],[10464,3,6,2,"صَحَّ - يَصِحُّ - صِحَّة","быть правильным, верным; быть здоровым • масдар: правильность; здоровье",["المنافق مخطئ ولو صح قوله.",17,19,"Лицемер ошибается, даже если его слова верны."]],[10465,3,6,2,"المُجْتَمَع | مُجْتَمَعَات","общество",["مجتمعنا انتقل من الصلاح إلى الفساد.",0,7,"Наше общество перешло от праведности к испорченности."]],[10466,3,6,2,"رَبَّى - يُرَبِّي - تَرْبِيَة","воспитывать, растить • масдар: воспитание",["أُرَبّي أولادي على الإسلام.",0,7,"Я воспитываю своих детей по исламу."]],[10467,3,6,2,"اِقْتِصَاد","экономика",["وفّرنا الكهرباء لنرفع الإقتصاد.",22,30,"Мы экономили электричество, чтобы поднять экономику."]],[10468,3,6,2,"وَظِيفَة | وَظَائِف","должность, работа; функция",["وظيفة المسلم الأساسية هي العبادة.",0,5,"Основная обязанность мусульманина — поклонение."]],[10469,3,6,2,"أَسَاسِيَّة","основная, базовая",["التعليم في مرحلة الطفولة شئ أساسي.",0,0,"Образование в детстве — основополагающая вещь."]],[10470,3,6,2,"أَدَارَ - يُدِيرُ - إِدَارَة","управлять, руководить; поворачивать • масдар: управление, администрация",["أدرت بيتي على سنة الرسول صلى الله عليه وسلم",0,0,"Я управлял своим домом по Сунне Посланника ﷺ."]],[10471,3,6,2,"مُدِير | مُدِيرُون","директор, управляющий",["المدير هو الأكثر خبرة بين الموظفين.",0,6,"Директор — самый опытный среди сотрудников."]],[10472,3,6,2,"الرَّاتِب | رَوَاتِب","зарплата, оклад",["الراتب رزق لا بد أن نشكر الله عليه.",0,6,"Зарплата — удел, за который нужно благодарить Аллаха."]],[10473,3,6,2,"الخَادِمَة | خَادِمَات","служанка, домработница",["لم أطلب خادمة لبيتي قط.",8,13,"Я никогда не нанимал домработницу."]],[10474,3,6,2,"أَفْسَدَ - يُفْسِدُ - إِفْسَاد","портить • масдар: порча",["عندما أفسدت ديني أفسد الله قلبي.",6,11,"Когда я испортил свою религию, Аллах испортил моё сердце."]],[10475,3,6,2,"أَدَّى إِلَى - يُؤَدِّي - تَأْدِيَة","вести (к), приводить (к) • масдар: приведение; исполнение",["الاختلاط بين الرجال و النساء يؤدي إلى تفكك الأسرة.",29,33,"Смешение мужчин и женщин ведёт к распаду семьи."]],[10476,3,6,2,"تَفَكَّكَ - يَتَفَكَّكُ - تَفَكُّك","распадаться, разваливаться • масдар: распад",["تفكك هاتفي أمس عندما كنت في العمل.",0,4,"Вчера, когда я был на работе, мой телефон развалился."]],[10477,3,6,2,"ضَاعَ - يَضِيعُ - ضَيَاع","теряться, пропадать • масдар: потеря, гибель",["ضاع هدفي بعد تركي العلم/يضيع الشباب بمصاحبة الفاسدين.",0,3,"Моя цель потерялась, когда я бросил учёбу. / Молодёжь пропадает, дружа с испорченными."]],[10478,3,6,2,"مَجَال | مَجَالَات","сфера, область",["أصبح مجال التعليم فاسدا في مصر.",5,9,"Сфера образования в Египте испортилась."]],[10479,3,6,2,"حَفِظَ - يَحْفَظُ - حِفْظ","хранить, беречь; заучивать наизусть • масдар: хранение; заучивание",["حفظت أخي في غيابه خوفا من الله.",0,4,"Я оберегал своего брата в его отсутствие из страха перед Аллахом."]],[10480,3,6,2,"أَبْعَدَ عَنْ - يُبْعِدُ - إِبْعَاد","отдалять (от) • масдар: отдаление",["الكذب يبعد عن الإيمان و يقرب من النِّفَاق.",6,10,"Ложь отдаляет от веры и приближает к лицемерию."]],[10481,3,6,2,"خَالَطَ - يُخَالِطُ - مُخَالَطَة","смешиваться, общаться (с) • масдар: общение, смешение",["لا تخالط الحسنات بالسيئات.",3,8,"Не смешивай добрые дела с дурными."]],[10482,3,6,2,"مُرَبِّيَة | مُرَبِّيَات","воспитательница, няня",["المربية الصالحة تهتم بأخلاق الإسلام.",0,7,"Хорошая воспитательница заботится об исламской нравственности."]],[10483,3,6,2,"هَلْ ... أَمْ لَا؟","… или нет?",["هل يستغرق البحث وقتا أم لا يستغرق؟",0,0,"Займёт поиск время или нет?"]],[10484,3,6,2,"لَا يَصِحُّ","не подобает, нельзя",["لا يصح أن تتبع الغرب في كل شئ",0,6,"Нельзя во всём следовать Западу."]],[10485,3,6,2,"لَهَا أَنْ","ей можно, ей позволено",["زوجتي ليس لها أن تخرج من البيت وحدها.",10,16,"Моей жене нельзя выходить из дома одной."]],[10486,3,6,2,"مُخَالَطَة الرِّجَال","смешение с мужчинами",["مخالطة الرجال مع النساء تفسد الأخلاق",0,13,"Смешение мужчин с женщинами портит нравы."]],[10487,3,6,2,"مُجْتَمَع نِسَائِيّ","женский коллектив",["حفظ المرأة العاملة يكون بعملها في مجتمع نسائي",34,45,"Работающая женщина защищена, работая в женском коллективе."]],[10488,3,6,2,"غَسَلَ - يَغْسِلُ - غَسْل","мыть, стирать • масдар: мытьё, стирка",null],[10489,3,6,2,"أَصْلَحَ - يُصْلِحُ - إِصْلَاح","исправлять, чинить, улучшать • масдар: исправление, реформа",null],[10490,3,6,2,"فَكَّكَ - يُفَكِّكُ - تَفْكِيك","разбирать, расчленять • масдар: разборка, расчленение",null],[10491,3,6,2,"نَاسَبَ - يُنَاسِبُ - مُنَاسَبَة","подходить, соответствовать • масдар: соответствие; повод, случай",null],[10492,3,6,3,"اِغْتَرَبَ - يَغْتَرِبُ - اِغْتِرَاب","уезжать на чужбину, эмигрировать • масдар: жизнь на чужбине, эмиграция",["اغترب معظم شباب الدول العربية",0,5,"Большинство молодёжи арабских стран уехало на чужбину."]],[10493,3,6,3,"ذَلُول","покорный, лёгкий, удобный",["جزاك الله خيرا أستاذي جعلت الدرس ذلولاً",33,39,"Да воздаст тебе Аллах благом, учитель, ты сделал урок лёгким."]],[10494,3,6,3,"مَنْكِب | مَنَاكِب","плечо; склон, сторона",["سرت في مناكب الأرض بحثا عن الرزق.",7,12,"Я ходил по просторам земли в поисках удела."]],[10495,3,6,3,"رِزْق | أَرْزَاق","удел, пропитание (дарованное Аллахом)",["اللهم ارزقنا رزقا واسعا من حيث لا ندري.",13,17,"О Аллах, даруй нам обильный удел, откуда мы не ожидаем."]],[10496,3,6,3,"النُّشُور","воскрешение (после смерти)",["يوم النشور قادم بلا شك.",4,10,"День воскрешения наступит несомненно."]],[10497,3,6,3,"صَحِبَ - يَصْحَبُ - صُحْبَة","сопровождать, дружить • масдар: общение, дружба",["إذا صحبت الأخيار كنت سعيدا.",4,8,"Если будешь дружить с лучшими, будешь счастлив."]],[10498,3,6,3,"حَافَظَ عَلَى - يُحَافِظُ - مُحَافَظَة","сохранять, беречь, соблюдать • масдар: сохранение, соблюдение",["حافظ على صلاتك تكن سعيدا.",0,8,"Соблюдай свою молитву — будешь счастлив."]],[10499,3,6,3,"رَجَا - يَرْجُو - رَجَاء","надеяться, просить • масдар: надежда, просьба",["أرجو أن تدعو إلى الله بصِدق.",0,4,"Надеюсь, ты будешь призывать к Аллаху искренне."]],[10500,3,6,3,"سَالِم | سَالِمُون","невредимый, здоровый",["اللهم اجعلنى سالما في جسمي.",13,18,"О Аллах, сделай меня здоровым телом."]],[10501,3,6,3,"غَانِم | غَانِمُون","получивший добычу, выигравший",["عدت من السوق غانما بعد البيع.",13,18,"Я вернулся с рынка с прибылью после продажи."]],[10502,3,6,3,"الحَيَاةُ سَهْلَة","жизнь лёгкая",["ظننت أن حياة الاغتراب ستكون سهلة.",0,0,"Я думал, что жизнь на чужбине будет лёгкой."]],[10503,3,6,3,"أَرْجُو أَنْ","надеюсь, что…",["أرجو من الله أن يغفر لي.",0,0,"Надеюсь, что Аллах простит меня."]],[10504,3,6,3,"بِالطَّبْعِ","конечно",["هل سيشيع الإسلام من جديد؟ - بالطبع وسيرتفع اسمه.",28,34,"Распространится ли ислам заново? — Конечно, и его имя возвысится."]],[10505,3,6,3,"وَإِلَّا مَا","а иначе не…",["تعال بسرعة و إلا ما أعطيتك الهدية.",0,0,"Иди быстрее, а не то я не дам тебе подарок."]],[10506,3,6,3,"سَالِمًا غَانِمًا","целым и с прибылью (невредимым и с добычей)",["لن يكون الكاذب سالما ولا غانما.",0,0,"Лжец не будет ни невредим, ни в выигрыше."]],[10507,3,6,3,"بَارَكَ اللهُ فِيكَ","да благословит тебя Аллах",["أقلت لأخيك بارك الله فيك؟",11,24,"Ты сказал своему брату: «Да благословит тебя Аллах»?"]],[10508,3,6,3,"نَشَرَ - يَنْشُرُ - نَشْر","распространять; публиковать • масдар: публикация, распространение",null],[10509,3,6,3,"غَنِمَ - يَغْنَمُ - غُنْم، غَنِيمَة","получать добычу, выигрывать • масдар: добыча, трофей",null],[10510,3,6,3,"سَلَّمَ إِلَى - يُسَلِّمُ - تَسْلِيم","вручать, передавать • масдар: вручение, передача",["سلم السارق نفسه إلى الضابط.",0,0,"Вор сдался офицеру."]],[10511,3,6,4,"مَسْأَلَة | مَسَائِل، مَسْأَلَات","1) вопрос, проблема 2) попрошайничество",["لا تصح المسألة لغير الله.",7,14,"Просить (подаяние) можно только у Аллаха."]],[10512,3,6,4,"نِعْمَة | نِعَم","милость, благо",["فهم الدين نعمة من أفضل نعم الله.",10,14,"Понимание религии — одна из лучших милостей Аллаха."]],[10513,3,6,4,"فَقَدَ - يَفْقِدُ - فَقْد","терять • масдар: потеря, утрата",["من فقد دينه فقد فقد آخرته و دنياه.",3,6,"Кто потерял свою религию, тот потерял и вечную жизнь, и этот мир."]],[10514,3,6,4,"اِعْتَمَدَ عَلَى - يَعْتَمِدُ - اِعْتِمَاد","полагаться, опираться (на) • масдар: опора, зависимость",["الشيخ يعتمد على العصا عندما يمشي /أبي يعتمد على النظارة في القراءة",6,11,"Старик опирается на палку при ходьбе. / Отец пользуется очками при чтении."]],[10515,3,6,4,"تَسَوَّلَ - يَتَسَوَّلُ - تَسَوُّل","попрошайничать • масдар: попрошайничество",["من يتسول يجهل أهمية العمل.",3,8,"Кто попрошайничает, тот не знает важности труда."]],[10516,3,6,4,"قَطُّ","никогда (в прошлом: ما + прош. + قطّ)",["ما أكلت حراماًقط و الحمدلله.",0,0,"Я никогда не ел запретного, хвала Аллаху."]],[10517,3,6,4,"أَبَدًا","никогда (в будущем)",["لن أهمل دروسي أبدا بإذن الله.",14,18,"Я никогда не буду пренебрегать уроками, с позволения Аллаха."]],[10518,3,6,4,"غَدَا إِلَى - يَغْدُو - غُدُوّ","отправиться рано утром (к) • масдар: утренний выход",["غدوت إلى الطبيب إليه أشكو فأخبرني بأن الجهل دائي",0,4,"Я пошёл к врачу пожаловаться, и он сказал мне, что невежество — моя болезнь."]],[10519,3,6,4,"حَطَبَة | حَطَب","полено, хворостина",["امرأة أبي لهب احتطبت ووضعت الحطب في طريق الرسول ﷺ.",27,32,"Жена Абу Лахаба собирала хворост и клала его на пути Посланника ﷺ."]],[10520,3,6,4,"اِحْتَطَبَ - يَحْتَطِبُ - اِحْتِطَاب","собирать хворост, дрова • масдар: сбор дров",["احتطب سكان أوربا في الشتاء.",0,5,"Жители Европы собирали дрова зимой."]],[10521,3,6,4,"أَعْرَابِيّ | أَعْرَاب","бедуин, кочевник",["كان الأعراب شديدي الجهل.",4,11,"Бедуины были крайне невежественны."]],[10522,3,6,4,"قَصْعَة | قِصَاع","большое блюдо, миска",["أضع الطعام في القصعة لتأكل الحيوانات.",14,20,"Я кладу еду в миску, чтобы ели животные."]],[10523,3,6,4,"تَطَهَّرَ - يَتَطَهَّرُ - تَطَهُّر","очищаться • масдар: очищение",["تطهرت من الذنوب بالاستغفار.",0,5,"Я очистился от грехов, прося прощения."]],[10524,3,6,4,"حِلْس | أَحْلَاس، حُلُوس","подстилка, коврик",["تركت الحلس في غرفة الجلوس.",5,10,"Я оставил коврик в гостиной."]],[10525,3,6,4,"أَمْسَكَ - يُمْسِكُ - إِمْسَاك","держать, хватать; воздерживаться • масдар: удержание; воздержание",["أمسكت يد أبي حتى نمر الشارع.",0,5,"Я держал папу за руку, пока мы переходили улицу."]],[10526,3,6,4,"دِرْهَم | دَرَاهِم","дирхам (монета)",["ليس الفقير من لا درهم له، الفقير من لا حسنات له.",17,21,"Беден не тот, у кого нет дирхама, беден тот, у кого нет добрых дел."]],[10527,3,6,4,"دَفَعَ إِلَى - يَدْفَعُ - دَفْع","платить, давать; толкать • масдар: оплата; толчок",["دفعت إلى العامل أجره كما طلب.",0,8,"Я заплатил рабочему, как он просил."]],[10528,3,6,4,"قَدُوم | قُدُم","топор, тесло",["عملي في المزرعة يعتمد على القدوم.",26,32,"Моя работа на ферме зависит от топора."]],[10529,3,6,4,"عُود | أَعْوَاد","палка, прут; древесина",["أصابني عود في قدمي عند لعبي في المزرعة.",7,10,"Мне в ногу попала палка, когда я играл на ферме."]],[10530,3,6,4,"اِنْتِهَاء","окончание, завершение",["لن نشعر بمتعةِ العمل إلا بعد انتهائه.",0,0,"Мы не почувствуем удовольствия от работы, пока она не закончится."]],[10531,3,6,4,"المُدَّة | مُدَد","срок, период",["سأصبح غنيا بعد مدة قصيرة من العمل.",15,18,"Я разбогатею через короткое время работы."]],[10532,3,6,4,"مَنَعَ - يَمْنَعُ - مَنْع","запрещать, препятствовать • масдар: запрет",["منعت نفسي النوم حتى أحصل على الدرجة النهائية.",0,4,"Я лишил себя сна, чтобы получить высший балл."]],[10533,3,6,4,"عَمَلٌ خَيْرٌ مِنْ مَسْأَلَة","труд лучше попрошайничества",["لا تطلب نقوداً من الناس فإنَّ العمل خير من مسألة الناس.",30,48,"Не проси денег у людей, ведь труд лучше попрошайничества."]],[10534,3,6,4,"مَا + مَاضٍ + قَطُّ","никогда не (в прошлом)",["ما كذبت قط",0,0,"Я никогда не лгал."]],[10535,3,6,4,"يَسْأَلُ النَّاسَ","просит у людей (подаяния)",["الفقير يسأل الناس",7,17,"Бедный просит у людей."]],[10536,3,6,4,"لَا شَيْءَ غَيْرُ هٰذَا","ничего кроме этого",["أكلت اللحم فقط، و لا شئ غير هذا",0,0,"Я ел только мясо, и ничего кроме этого."]],[10537,3,6,4,"بَيْنَ يَدَيْهِ","перед ним",["وضعت الطعام بين يديه.",12,20,"Я поставил еду перед ним."]],[10538,3,6,4,"أَلَيْسَ ...؟","разве не…?",["أليس العمل أفضل من مسألة الناس؟",0,4,"Разве работа не лучше попрошайничества?"]],[10539,3,6,4,"تَصَدَّقَ - يَتَصَدَّقُ - تَصَدُّق","подавать милостыню • масдар: раздача милостыни",null],[10540,3,6,4,"اِنْتَهَى مِنْ - يَنْتَهِي - اِنْتِهَاء","заканчивать, завершать (что-л.) • масдар: окончание",null],[10541,3,6,4,"آتَى - يُؤْتِي - إِيتَاء","давать, выплачивать • масдар: выплата",["آتِ المال للفقراء والمتسولين.",0,0,"Давай деньги бедным и просящим."]],[10542,3,7,1,"مَعْهَد | مَعَاهِد","институт",["الدراسة في المعهد هي دراسة متوسطة",11,17,"Учёба в институте — среднее образование."]],[10543,3,7,1,"قَاعِدَة | قَوَاعِد","правила, основы (ед. قاعدة)",["معرفة قواعد العلوم يجعل فهما سهلاً",6,11,"Знание правил наук облегчает понимание."]],[10544,3,7,1,"تَرْجَمَة | تَرَاجِم، تَرْجَمَات","перевод",["علم الترجمة ساعد في نقل العلم",4,11,"Наука перевода помогла передаче знаний."]],[10545,3,7,1,"مُخْتَبَر | مُخْتَبَرَات","лаборатория",["لايد من المختبر عند دراسة الكيمياء",8,15,"При изучении химии обязательно нужна лаборатория."]],[10546,3,7,1,"إِذَاعَة | إِذَاعَات","радиовещание, радиостанция",["أستمع إلى إذاعة الأخبار في المذياع",10,15,"Я слушаю радио новостей по радиоприёмнику."]],[10547,3,7,1,"نَطَقَ - يَنْطِقُ - نُطْق","произносить, говорить • масдар: произношение",["اللهم ارزقنى نطقا سليما للقرآن",13,17,"О Аллах, даруй мне правильное произношение Корана."]],[10548,3,7,1,"تَدْرِيب | تَدْرِيبَات","тренировка, упражнение",["سأذهب لتدريب الكرة متأخرا اليوم",6,12,"Сегодня я пойду на тренировку по футболу поздно."]],[10549,3,7,1,"أَوَّل مَرَّة","первый раз",["عندما سافرت لمصر كانت أول مرة أركب فيها الطائرة",22,29,"Когда я поехал в Египет, я впервые летел на самолёте."]],[10550,3,7,1,"نَصِيحَة مُفِيدَة","полезный совет",["اتباع الرسول نصيحة مفيدة",13,24,"Следование Посланнику — полезный совет."]],[10551,3,7,1,"إِذَنْ سَـ","значит, тогда (в будущем)",["أتقى الله إذن سيجعل لي حلولاً لمشكلاتي",10,13,"Я буду бояться Аллаха — тогда Он даст мне решения моих проблем."]],[10552,3,7,1,"مُخْتَبَر اللُّغَة","лингафонный кабинет",["يجب الاهتمام بمختبر اللغة في المدارس",13,25,"Нужно уделять внимание лингафонным кабинетам в школах."]],[10553,3,7,2,"نَشَأَ - يَنْشَأُ - نُشُوء، نَشْأَة","возникать, вырастать • масдар: возникновение, рост",["نشأ الجهل بين الناس بعد ترك الدين",0,3,"Невежество возникло среди людей после того, как они оставили религию."]],[10554,3,7,2,"جَزِيرَة | جُزُر، جَزَائِر","остров",["أتمنى أن أعيش في جزيرة",17,22,"Хотел бы я жить на острове."]],[10555,3,7,2,"قَبِيلَة | قَبَائِل","племя",["نظام الحياة في القبيلة يختلف عن الأسر الصغيرة",15,22,"Уклад жизни в племени отличается от маленьких семей."]],[10556,3,7,2,"مُتَفَرِّقَة","разрозненная, отдельная",["أحفظ آيات متفرقة من القرآن",10,16,"Я знаю наизусть отдельные аяты из Корана."]],[10557,3,7,2,"لَهْجَة | لَهَجَات","диалект",["شيوع اللجهات يؤدي إلى تفرق الأمم",0,0,"Распространение диалектов ведёт к разобщению народов."]],[10558,3,7,2,"مُشْتَرَك","общий; участник, абонент",["أنا مشترك في الشبكة الدولية",4,9,"Я подключён к Интернету."]],[10559,3,7,2,"الشِّعْر | أَشْعَار","поэзия, стихи",["قراءة الشعر تجعل النطق صحيحا",6,11,"Чтение стихов делает произношение правильным."]],[10560,3,7,2,"الشَّاعِر | شُعَرَاء","поэт",["لم يكن الرسول- ص- شاعرا",18,23,"Посланник ﷺ не был поэтом."]],[10561,3,7,2,"الخَطَابَة","ораторское искусство",["سألنحق بجامعة الأزهر لدراسة الخطابة",28,35,"Я поступлю в университет аль-Азхар изучать ораторское искусство."]],[10562,3,7,2,"الخَطِيب | خُطَبَاء","оратор, проповедник (хатыб)",["يجب على الخطيب أن يدرس العربية جيدا",8,14,"Проповедник должен хорошо изучить арабский язык."]],[10563,3,7,2,"عَقَلَ - يَعْقِلُ - عَقْل","понимать, постигать разумом • масдар: разум",["هل تعقلون ما أقول؟",3,9,"Понимаете ли вы, что я говорю?"]],[10564,3,7,2,"لَفْظ | أَلْفَاظ","слово, выражение",["إذا فهمت ألفاظ القرآن عقلت تفسيره",9,14,"Если ты поймёшь слова Корана, ты постигнешь его толкование."]],[10565,3,7,2,"التَّفْسِير","толкование (Корана), тафсир",["بدون التفسير لن نفهم القرآن",5,12,"Без тафсира мы не поймём Коран."]],[10566,3,7,2,"الفِقْه","фикх (исламское право)",["عليك بدراسة الفقه",12,17,"Тебе следует изучать фикх."]],[10567,3,7,2,"شَعْب | شُعُوب","народ",["عند اجتماع شعوب المسلمين سيتحقق الفوز",11,15,"Когда объединятся мусульманские народы, будет победа."]],[10568,3,7,2,"الأُرْدِيَّة","урду (язык Пакистана)",["ما درست اللغة الأردية قط",14,21,"Я никогда не изучал язык урду."]],[10569,3,7,2,"السَّوَاحِلِيَّة","суахили (язык Кении)",["اللغة السواحلية عجيبة جدا",6,15,"Язык суахили очень удивительный."]],[10570,3,7,2,"أَقْرَضَ - يُقْرِضُ - إِقْرَاض","давать взаймы, одалживать • масдар: предоставление займа",["أقرضت صديقي السيارة ليسافر بها",0,5,"Я одолжил другу машину, чтобы он поехал на ней."]],[10571,3,7,2,"اِقْتَرَضَ مِنْ - يَقْتَرِضُ - اِقْتِرَاض","брать взаймы, занимать • масдар: заём",["اقترضت من المصرف لشراء سيارة",0,9,"Я взял кредит в банке, чтобы купить машину."]],[10572,3,7,2,"الحَرْف العَرَبِيّ","арабская буква, арабское письмо",["الكتابة بالحرف العربي ممتعة.",8,21,"Писать арабскими буквами интересно."]],[10573,3,7,2,"أَلْفَاظ عَرَبِيَّة","арабские слова",["يتكلم كثير من الشعوب بألفاظ عربية",21,33,"Многие народы говорят, используя арабские слова."]],[10574,3,7,2,"أَنْزَلَ - يُنْزِلُ - إِنْزَال","ниспосылать, спускать • масдар: ниспослание",null],[10575,3,7,2,"فَسَّرَ - يُفَسِّرُ - تَفْسِير","толковать, объяснять • масдар: толкование, объяснение",null],[10576,3,7,2,"تَفَرَّقَ - يَتَفَرَّقُ - تَفَرُّق","расходиться, разъединяться • масдар: разобщённость",["تفرق العرب بعد أن كانوا يدا واحدة. التفرق في الأفكار يؤدي إلى التفرق في الأعمال.",0,4,"Арабы разобщились после того, как были единой рукой. / Разобщённость во взглядах ведёт к разобщённости в делах."]],[10577,3,7,2,"اِشْتَرَكَ فِي - يَشْتَرِكُ - اِشْتِرَاك","участвовать • масдар: участие",["اشترك الأساتذة في إنشاء المركز",0,5,"Преподаватели участвовали в создании центра."]],[10578,3,7,3,"إِمَام | أَئِمَّة","имам, руководитель",["خطبة إمام المسجد فصيحة جدًا",5,9,"Проповедь имама мечети очень красноречива."]],[10579,3,7,3,"الشَّرِيعَة | شَرَائِع","шариат",["شريعة الإسلام هي الأفضل دائمًا",0,5,"Шариат ислама всегда лучший."]],[10580,3,7,3,"تَخَصَّصَ فِي - يَتَخَصَّصُ - تَخَصُّص","специализироваться • масдар: специализация",["خصصت حياتي للدعوة في سبيل الله",0,0,"Я посвятил свою жизнь призыву на пути Аллаха."]],[10581,3,7,3,"عَفْوًا","извините; пожалуйста (в ответ)",["حاول ألا تخطئ حتى لا تقول عفوا",26,30,"Старайся не ошибаться, чтобы не говорить «извините»."]],[10582,3,7,3,"نِدَاء | نِدَاءَات","зов, призыв, воззвание",["سمع موسى عليه السلام نداء الله - عز وجل – على جبل الطور",21,25,"Муса (мир ему) услышал зов Аллаха на горе Тур."]],[10583,3,7,3,"أَخِير","последний",["لا أحب الصلاة في الصف الأخير",22,28,"Я не люблю молиться в последнем ряду."]],[10584,3,7,3,"أَمَان","безопасность",["نعمة الأمان من أعظم نعم الله علينا",5,11,"Благо безопасности — одна из величайших милостей Аллаха нам."]],[10585,3,7,3,"عَفْوًا","извините, (но)…",["عفوا، لن أطيع احدا يعصى الله.",0,4,"Извините, я не стану слушаться того, кто ослушивается Аллаха."]],[10586,3,7,3,"فِي أَمَانِ اللهِ","под защитой Аллаха (до свидания)",["أفضل هجرة ما كانت في أمان الله.",18,30,"Лучшее переселение — под защитой Аллаха."]],[10587,3,7,3,"سَافَرَ إِلَى - يُسَافِرُ - سَفَر، مُسَافَرَة","путешествовать, ездить • масдар: путешествие",null],[10588,3,7,4,"عَالَمِيَّة | عَالَمِيَّات","всемирная, мировая, международная",["شركة مصر للطيران عالمية.",17,23,"Компания «ЕгиптЭйр» — международная."]],[10589,3,7,4,"عَصْر | عُصُور","эпоха, век",["أرجو أن نعود إلى عصر قوتنا ثانية.",17,20,"Надеюсь, мы снова вернёмся в эпоху нашей силы."]],[10590,3,7,4,"اِزْدَهَرَ - يَزْدَهِرُ - اِزْدِهَار","процветать • масдар: процветание, расцвет",["ازدهر العلم في رأسي/ازدهرت الحديقة في فصل الربيع",0,5,"Знания расцвели в моей голове. / Сад расцвёл весной."]],[10591,3,7,4,"أَلَّفَ - يُؤَلِّفُ - تَأْلِيف","сочинять, составлять (книгу); объединять • масдар: сочинение, составление",["ألفت كتبا في علوم كثيرة / اللهم ألف بين قلوب المسلمين",0,4,"Я написал книги по многим наукам. / О Аллах, объедини сердца мусульман."]],[10592,3,7,4,"مُؤَلِّف | مُؤَلِّفُون","автор, составитель",["سيف المؤلف هو القلم.",4,10,"Меч автора — перо."]],[10593,3,7,4,"أَسَاس | أُسُس","основа, фундамент",["الصلاة أساس قبول الأعمال.",7,11,"Молитва — основа принятия дел."]],[10594,3,7,4,"الغَرْبِيَّة","западная",["الحضارة الغربية أفسدت عقول الشباب.",8,15,"Западная цивилизация испортила умы молодёжи."]],[10595,3,7,4,"هَجَرَ - يَهْجُرُ - هَجْر","покидать, оставлять • масдар: оставление, разлука",["من يهجر القرآن يكون مغتربا.",3,7,"Кто покидает Коран, становится чужим."]],[10596,3,7,4,"اِسْتَعْمَلَ - يَسْتَعْمِلُ - اِسْتِعْمَال","использовать, применять • масдар: использование",["أستعمل السواك قبل كل صلاة.",0,6,"Я пользуюсь сивяком перед каждой молитвой."]],[10597,3,7,4,"اِسْتِعْمَار","колонизация, колониализм",["استعمار الفكر أخطر من غيره.",0,7,"Колонизация мысли опаснее других (видов)."]],[10598,3,7,4,"حَارَبَ - يُحَارِبُ - مُحَارَبَة، حَرْب","воевать, бороться (с) • масдар: война, борьба",["ساحارب بسيفي وقلمي و لساني حتى ينتشر هذا الدين.",0,6,"Я буду бороться мечом, пером и языком, пока эта религия не распространится."]],[10599,3,7,4,"شَجَّعَ عَلَى - يُشَجِّعُ - تَشْجِيع","поощрять, ободрять (к) • масдар: поощрение",["شجع التلفاز الأطفال على مخالفة الآباء.",0,0,"Телевизор подтолкнул детей к непослушанию родителям."]],[10600,3,7,4,"بَعُدَ عَنْ - يَبْعُدُ - بُعْد","быть далёким, удаляться (от) • масдар: отдалённость",["بَعُدَ الشيطانُ عني عند ذكر الله.",0,6,"Шайтан удалился от меня при поминании Аллаха."]],[10601,3,7,4,"صُعُوبَة | صُعُوبَات","трудность",["واجهت صعوبة عند دراسة اللغة لأول مرة.",6,11,"Я столкнулся с трудностями, впервые изучая язык."]],[10602,3,7,4,"تَحَقَّقَ - يَتَحَقَّقُ - تَحَقُّق","осуществляться, сбываться; проверять • масдар: осуществление; проверка",["يتحقق الإيمان بقراءة القرآن.",0,5,"Вера осуществляется чтением Корана."]],[10603,3,7,4,"التَّامّ","полный, совершенный",["لن يتحقق العلم التام إلا بالاجتهاد.",15,20,"Полного знания не достичь без усердия."]],[10604,3,7,4,"قَوِيَ - يَقْوَى - قُوَّة","окрепнуть, стать сильным • масдар: сила",["قويت قدم الطفل ويقدر على المشي.",0,4,"Нога ребёнка окрепла, и он может ходить."]],[10605,3,7,4,"الحَدِيثَة","современная, новая",["الهواتف الحديثة حققت سهولة الإتصال.",8,15,"Современные телефоны облегчили связь."]],[10606,3,7,4,"إِحْدَى","одна (из)",["سأحصل على إحدى الفرصتين، الحج و العمرة.",10,14,"Я получу одну из двух возможностей — хадж или умру."]],[10607,3,7,4,"رَسْمِيَّة","официальная",["أبحث عن الأوراق الرسمية حتى أحصل على جواز السفر.",16,23,"Я ищу официальные документы, чтобы получить паспорт."]],[10608,3,7,4,"هَيْئَة | هَيْئَات","организация, учреждение; вид, облик",["اتجهت إلى هيئة علماء الأزهر الشهر الماضي.",10,14,"В прошлом месяце я обратился в Совет учёных аль-Азхара."]],[10609,3,7,4,"عِبَادَة | عِبَادَات","поклонение, богослужение",["التفكير في المخلوقات من العبادة.",24,31,"Размышление о творениях — часть поклонения."]],[10610,3,7,4,"لُغَة عَالَمِيَّة","мировой язык",["الإنجلزية هي اللغة العالمية في الحاضر.",13,27,"Английский — мировой язык в настоящее время."]],[10611,3,7,4,"العَصْر العَبَّاسِيّ","эпоха Аббасидов",["ازدهرت الأخلاق الطيبة في العصر العباسي.",25,38,"Благой нрав процветал в эпоху Аббасидов."]],[10612,3,7,4,"لَهْجَة مِصْرِيَّة","египетский диалект",["اللهجة المصرية أفسدت اللغة الفصيحة.",0,14,"Египетский диалект испортил литературный язык."]],[10613,3,7,4,"وَسَائِل الاِتِّصَال","средства связи, коммуникации",["أصبحت وسائل الاتصال سهلة في الحاضر.",6,19,"Средства связи сейчас стали доступными."]],[10614,3,7,4,"لُغَة رَسْمِيَّة","официальный язык",["اللغة الرسمية في الشركة هي الإنجليزية.",0,13,"Официальный язык в компании — английский."]],[10615,3,7,4,"هَيْئَة الأُمَم المُتَّحِدَة","Организация Объединённых Наций",["تعمل هيئة الأمم المتحدة على حل مشكلات الدول.",5,23,"ООН работает над решением проблем государств."]],[10616,3,7,4,"صَعُبَ - يَصْعُبُ - صُعُوبَة","быть трудным • масдар: трудность",null],[10617,3,8,1,"جَائِزَة | جَوَائِز","премия, награда, приз",["الجنة هي الجائزة الكبرى",9,16,"Рай — величайшая награда."]],[10618,3,8,1,"فَرْحَة","радость",["كانت فرحتى عظيمة بعد حفظ القرآن",5,10,"Моя радость была огромной, когда я выучил Коран."]],[10619,3,8,1,"السِّيرَة | سِيَر","жизнеописание, биография (сира)",["تعلمت الصبرمن قراءة سِيرُ الصحابة",20,25,"Я научился терпению, читая жизнеописания сподвижников."]],[10620,3,8,1,"مُسَابَقَة | مُسَابَقَات","соревнование, конкурс",["الدنيا مسابقة في فعل الخير",7,13,"Этот мир — соревнование в добрых делах."]],[10621,3,8,1,"مُنَافَسَة | مُنَافَسَات","соперничество, конкуренция",["المنافسة الحقيقية هي التي تحب فيها الخير لغيرك",0,8,"Настоящая конкуренция — та, где ты желаешь добра другому."]],[10622,3,8,1,"أَسْعَد","самый счастливый, счастливее",["الشخص الأسعد هو الذي يطيع والديه",6,12,"Самый счастливый человек — тот, кто слушается родителей."]],[10623,3,8,1,"رَفَعَ - يَرْفَعُ - رَفْع","поднимать, возвышать • масдар: поднятие",["سأرفع قول لا إله إلا الله في كل العالم",0,5,"Я подниму слова «Нет божества, кроме Аллаха» по всему миру."]],[10624,3,8,1,"العَفْو","прощение, помилование",["أرجو العفو من ربي على ما فعلت من خطأ",5,10,"Надеюсь на прощение Господа за ошибки, что я совершил."]],[10625,3,8,1,"وَفَّقَكَ","(Аллах) даровал тебе успех",["أسأل الله أن يوفقني للفهم الصحيح",0,0,"Прошу Аллаха даровать мне правильное понимание."]],[10626,3,8,1,"السِّيرَة النَّبَوِيَّة","жизнеописание Пророка (сира)",["اشتركت في مسابقة السيرة النبوية",17,31,"Я участвовал в конкурсе по сире Пророка."]],[10627,3,8,1,"المَعْلُومَات العَامَّة","общие знания, эрудиция",["الحصول على الثقافة يكون بمعرفة المعلومات العامة",31,47,"Культура приобретается знанием общих сведений."]],[10628,3,8,1,"جَوَائِز المُسَابَقَة","призы конкурса",["نال أخى أغلب جوائز المسابقة",13,27,"Мой брат получил большую часть призов конкурса."]],[10629,3,8,1,"هٰذَا أَسْعَدُ يَوْمٍ فِي حَيَاتِي","это самый счастливый день в моей жизни",["يوم الوقوف بعرفة كان أسعد يوم في حياتي",0,0,"День стояния на Арафате был самым счастливым днём в моей жизни."]],[10630,3,8,1,"لَقَدْ رَفَعْتَ رَأْسَنَا","ты заставил нас гордиться (букв. поднял нам голову)",["سأرفع رأس أبي يوم القيامة عندما أحفظ القرآن",0,0,"Я заставлю отца гордиться мной в Судный день, когда выучу Коран."]],[10631,3,8,1,"عَفَا اللهُ عَنْكَ","да простит тебя Аллах",["عفا الله عن جدي، كان رجلا يحب الخير",0,0,"Да простит Аллах моего деда, он был человеком, любившим добро."]],[10632,3,8,1,"فَرِحَ - يَفْرَحُ - فَرَح","радоваться • масдар: радость",null],[10633,3,8,1,"نَافَسَ - يُنَافِسُ - مُنَافَسَة","соперничать, конкурировать • масдар: конкуренция",null],[10634,3,8,1,"سَابَقَ - يُسَابِقُ - مُسَابَقَة","состязаться • масдар: соревнование, конкурс",null],[10635,3,8,1,"عَفَا عَنْ - يَعْفُو - عَفْو","прощать • масдар: прощение",null],[10636,3,8,1,"خَطَبَ - يَخْطُبُ - خِطْبَة","1) произносить проповедь 2) свататься • масдар: сватовство",["خطب الخطيب خطبة مؤثرة خطب سعيد سعاد",0,3,"Проповедник произнёс трогательную проповедь. / Саид посватался к Суад."]],[10637,3,8,2,"مَنَحَ - يَمْنَحُ - مَنْح","давать, присуждать, предоставлять • масдар: предоставление",["سأمنحك فرصة حتى تنتهي من عملك",0,6,"Я дам тебе возможность закончить свою работу."]],[10638,3,8,2,"أَبْدَعَ - يُبْدِعُ - إِبْدَاع","творить, создавать новое • масдар: творчество",["أبدع علماء الغرب فتقدموا علينا",0,4,"Западные учёные создавали новое и опередили нас."]],[10639,3,8,2,"مُبْدِع | مُبْدِعُون","творческий, креативный; творец",["الإنسان المبدع ينال أهدافه بسرعة",8,14,"Креативный человек быстро достигает своих целей."]],[10640,3,8,2,"مُكَافَأَة | مُكَافَآت","вознаграждение, премия (денежная)",["الجنة هي المكافأة الكبرى",9,17,"Рай — величайшая награда."]],[10641,3,8,2,"قِيمَة | قِيَم","ценность, стоимость",["قيمة الإنسان في إيمان قلبه",0,4,"Ценность человека — в вере его сердца."]],[10642,3,8,2,"دِرْع | دُرُوع","1) доспех, кольчуга 2) памятный щит (к награде)",["منحت المجاهد درعًا من حديد. / نلت درعًا ذهبيًا بعد الفوز في المسابقة.",13,18,"Я подарил воину железный доспех. / Я получил золотой щит после победы в конкурсе."]],[10643,3,8,2,"لَجْنَة | لِجَان","комиссия, комитет",["لدينا لجنة لتأليف الكتب في المركز",6,10,"В центре у нас есть комиссия по составлению книг."]],[10644,3,8,2,"مَشْهُورَة","знаменитая, известная",["الأهرامات من الآثار المصرية المشهورة",28,36,"Пирамиды — одни из известных египетских древностей."]],[10645,3,8,2,"مُؤَسَّسَة | مُؤَسَّسَات","учреждение, организация, фонд",["أفضل المؤسسات هي التي تساعد الناس",5,13,"Лучшие организации — те, что помогают людям."]],[10646,3,8,2,"مَمْلَكَة | مَمَالِك","королевство",["بلدي كانت مملكة قبل أن يحكمها رئيس",10,15,"Моя страна была королевством до того, как ею стал править президент."]],[10647,3,8,2,"مَلِك | مُلُوك","король, царь",["الله هو الملك وليس بعده شئ",8,13,"Аллах — Царь, и после Него нет ничего."]],[10648,3,8,2,"مُكَافَأَة مَالِيَّة","денежное вознаграждение",["نلت من أبي مكافأة مالية كبيرة",11,23,"Я получил от отца большое денежное вознаграждение."]],[10649,3,8,2,"جَوَائِز تَقْدِيرِيَّة","почётные премии (для известных учёных)",["مُنِحَ عمي جائزة تقديرية في مجال العلوم",0,0,"Моему дяде присудили почётную премию в области наук."]],[10650,3,8,2,"جَوَائِز تَشْجِيعِيَّة","поощрительные премии (для молодых учёных)",["ألّفت قصة و نلت جائزة تشجيعية",0,0,"Я написал рассказ и получил поощрительную премию."]],[10651,3,8,2,"أَنْحَاء العَالَم","все уголки мира, по всему миру",["نتابع الأخبار في جميع أنحاء العالم",22,34,"Мы следим за новостями во всех уголках мира."]],[10652,3,8,2,"مُؤَسَّسَة خَيْرِيَّة","благотворительная организация",["كنت مشتركا في مؤسسة خيرية",14,25,"Я участвовал в благотворительной организации."]],[10653,3,8,2,"اِنْقَسَمَ إِلَى - يَنْقَسِمُ - اِنْقِسَام","делиться (на) • масдар: деление, раскол",null],[10654,3,8,2,"خَدَمَ - يَخْدُمُ - خِدْمَة","служить, обслуживать • масдар: служба, услуга",null],[10655,3,8,2,"كَوَّنَ - يُكَوِّنُ - تَكْوِين","составлять, образовывать • масдар: образование, формирование",null],[10656,3,8,2,"وَضَعَ - يَضَعُ - وَضْع","класть, ставить • масдар: положение, ситуация",null],[10657,3,8,3,"المِثَالِيّ","образцовый, идеальный",["حصلت أمي على جائزة الأم المثالية",24,32,"Моя мама получила премию «Образцовая мать»."]],[10658,3,8,3,"اِجْتَمَعَ - يَجْتَمِعُ - اِجْتِمَاع","собираться, встречаться • масдар: собрание, встреча",["لا يجتمع العرب في الحاضر على كلمة واحدة",3,8,"Арабы сейчас не могут объединиться на одном слове."]],[10659,3,8,3,"حَسَن","хороший, прекрасный",["الخُلق الحسن يرفع درجات صاحبه",7,12,"Хороший нрав возвышает степени его обладателя."]],[10660,3,8,3,"خُلُق | أَخْلَاق","нрав, характер (мн. нравственность)",["لن أصاحب ذا الخلق الخبيث",12,17,"Я не буду дружить с человеком дурного нрава."]],[10661,3,8,3,"مَظْهَر | مَظَاهِر","внешний вид, облик",["نظف جوهرك قبل مظهرك",14,19,"Очисти свою сущность прежде внешности."]],[10662,3,8,3,"مَحْبُوب","любимый",["النصيحة الطيبة من الأمور المحبوبة عندي",25,33,"Добрый совет — одна из любимых мной вещей."]],[10663,3,8,3,"زَمِيل | زُمَلَاء","коллега, однокашник",["لم أغضب من زميلي قط",11,16,"Я никогда не сердился на своего однокашника."]],[10664,3,8,3,"شَارَكَ فِي - يُشَارِكُ - مُشَارَكَة","участвовать (в) • масдар: участие",["أنا أشارك في مسابقة القرآن الكريم",4,9,"Я участвую в конкурсе по благородному Корану."]],[10665,3,8,3,"أَعْلَنَ - يُعْلِنُ - إِعْلَان","объявлять • масдар: объявление, реклама",["أعلنت لاصدقائي موعد زواجي",0,5,"Я объявил друзьям дату своей свадьбы."]],[10666,3,8,3,"مَبْلَغ | مَبَالِغ","сумма (денег)",["سأقترض مبلغا من المصرف الوطني",7,12,"Я займу сумму в Национальном банке."]],[10667,3,8,3,"حَفْل | حَفَلَات","праздник, торжество, вечеринка",["ذهبت إلى حفل زواج صديقي.",9,12,"Я пошёл на свадьбу друга."]],[10668,3,8,3,"الطَّالِب المِثَالِيّ","образцовый студент",["يجب أن يكون الطالب المسلم مثاليًا",0,0,"Студент-мусульманин должен быть образцовым."]],[10669,3,8,3,"حَسَن الأَخْلَاق","добронравный, с хорошим характером",["من صفات الرسول –ص- أنه كان حسن الأخلاق",27,38,"Одно из качеств Посланника ﷺ — он был добронравным."]],[10670,3,8,3,"مُسَابَقَات ثَقَافِيَّة","культурные (интеллектуальные) конкурсы",["سأشترك في جميع المسابقات الثقافية في المدرسة",15,33,"Я буду участвовать во всех интеллектуальных конкурсах в школе."]],[10671,3,8,3,"الأَنْشِطَة الرِّيَاضِيَّة","спортивные мероприятия",["لا أعتمد على الأنشطة الرياضية حتى أنال الجائزة",13,29,"Я не полагаюсь на спорт, чтобы получить приз."]],[10672,3,8,4,"الخَيْرِيَّة","благотворительная",["الأعمال الخيرية لا تعتمد على سن خاص.",8,15,"Благотворительные дела не зависят от особого возраста."]],[10673,3,8,4,"فَائِز | فَائِزُون","победитель, лауреат",["حاول أن تكون فائزا في الدنيا و الآخرة",13,18,"Старайся быть победителем в этом мире и в вечном."]],[10674,3,8,4,"نَالَ - يَنَالُ - نَيْل","получать, добиваться • масдар: получение, достижение",["ما نلت جائزة قط، ولكن مُنحْتُ شهادة",0,0,"Я никогда не получал премию, но мне вручили грамоту."]],[10675,3,8,4,"أَشْهَر","самый известный",["لا تعمل الخير حتى تكون الأشهر بين الناس",23,29,"Не делай добро, чтобы стать самым известным среди людей."]],[10676,3,8,4,"مَشْهُور","знаменитый, известный",["مبدع الحاسوب هو رجل مشهور",20,25,"Создатель компьютера — знаменитый человек."]],[10677,3,8,4,"مَوْلُود | مَوَالِيد","рождённый; новорождённый",["أنا مولود في بلد العلم و العلماء",4,9,"Я рождён в стране знаний и учёных."]],[10678,3,8,4,"جَائِزَة عَالَمِيَّة","международная премия",["جائزة أوسكار جائزة عالمية",13,25,"«Оскар» — международная премия."]],[10679,3,8,4,"مِيدَالِيَّة ذَهَبِيَّة","золотая медаль",["أتمنى نيل ميدالية ذهبية في أي مجال",10,23,"Мечтаю получить золотую медаль в любой области."]],[10680,3,8,4,"فَازَ بِـ/فِي - يَفُوزُ - فَوْز","побеждать, выигрывать • масдар: победа, выигрыш",null],[10681,3,9,1,"عَالَم | عَوَالِم، عَالَمُون","мир, вселенная",["تقدم العالم بالتكنولوجيا الحديثة.",5,11,"Мир продвинулся вперёд благодаря современным технологиям."]],[10682,3,9,1,"شَبَكَة | شِبَاك، شَبَكَات","1) сеть (рыболовная) 2) сеть (компьютерная, дорожная)",["لا تتبع الشيطان فيصطادك في شباكه. / رأس الإنسان شبكة لجمع المعلومات.",48,52,"Не следуй за шайтаном, иначе он поймает тебя в свои сети. / Голова человека — сеть для сбора информации."]],[10683,3,9,1,"أَطْوَل","самый длинный, длиннее",["قرأت أطول سورة في القرآن.",5,9,"Я прочитал самую длинную суру в Коране."]],[10684,3,9,1,"شَاشَة | شَاشَات","экран",["عليّ أن أنظف شاشة هاتفي",13,17,"Мне нужно почистить экран телефона."]],[10685,3,9,1,"عُنْوَان | عَنَاوِين","адрес; заголовок",["النظافة عنوان المؤمن في الحياة.",8,13,"Чистота — визитная карточка верующего в жизни."]],[10686,3,9,1,"صَاحِب | أَصْحَاب","друг, товарищ; владелец",["الصاحب الصالح يعين صاحبه على طاعة الله",0,6,"Праведный друг помогает другу в покорности Аллаху."]],[10687,3,9,1,"بَعَثَ - يَبْعَثُ - بَعْث","посылать, отправлять; воскрешать • масдар: отправка; воскрешение",["بعث الله الرسول بدين الحق",0,3,"Аллах послал Посланника с истинной религией."]],[10688,3,9,1,"رِسَالَة | رَسَائِل، رِسَالَات","письмо, послание",["الإسلام رسالة علينا أن ننشرها للعالم",8,13,"Ислам — послание, которое мы должны распространить в мире."]],[10689,3,9,1,"رَبَطَ - يَرْبِطُ - رَبْط","связывать, привязывать • масдар: связывание",["اللهم اربط قلبي بك في كل حال",6,10,"О Аллах, привяжи моё сердце к Тебе в любом состоянии."]],[10690,3,9,1,"مَعْلُومَة | مَعْلُومَات","сведение, информация (мн. информация)",["ناقشت صديقي في تلك المعلومة العجيبة",19,27,"Я обсудил с другом эту удивительную информацию."]],[10691,3,9,1,"أَكْثَر مِنْ","больше чем…",["أنا أكثر مالاً و علمًا",0,0,"У меня больше денег и знаний."]],[10692,3,9,1,"البَرِيد الإِلِكْتُرُونِيّ","электронная почта",["في الحاضر، لا أحد يجهل البريد الإلكتروني.",23,40,"Сейчас никто не обходится без электронной почты."]],[10693,3,9,1,"يَا لَكُمْ مِنْ","какие же вы…! (восклицание, мн. ч.)",["يا لكم من طلاب مجتهدين!",0,9,"Какие же вы прилежные студенты!"]],[10694,3,9,1,"رَأَى - يَرَى - رُؤْيَة","видеть • масдар: видение, зрение",null],[10695,3,9,1,"تَحَدَّثَ مَعَ/عَنْ - يَتَحَدَّثُ - تَحَدُّث","разговаривать (с, о) • масдар: разговор, беседа",null],[10696,3,9,2,"اِتِّصَال | اِتِّصَالَات","связь, контакт",["تحقق الاتصال التام بين جميع دول العالم هذه الأيام",5,12,"Сегодня осуществлена полная связь между всеми странами мира."]],[10697,3,9,2,"قَارَّة | قَارَّات","континент, материк",["إفريقيا من أقدم القارات في العالم",16,23,"Африка — один из древнейших континентов мира."]],[10698,3,9,2,"وَاسِع","широкий, обширный",["هذا شيخ واسع العلم / الثوب واسع جدًا",8,12,"Это шейх с обширными знаниями. / Одежда очень широкая."]],[10699,3,9,2,"صَارَ - يَصِيرُ - صَيْرُورَة","становиться • масдар: становление",["صرنا لا نهتم بأمر ديننا والله المستعان",0,0,"Мы стали не интересоваться делами нашей религии, и помощь — у Аллаха."]],[10700,3,9,2,"بَطِيئَة","медленная",["الحاسوب سرعته بطيئة جدا",14,19,"Скорость компьютера очень низкая."]],[10701,3,9,2,"حَاجَة | حَاجَات","нужда, потребность",["لا حاجة لي في الدنيا و ما فيها",3,7,"Мне не нужен этот мир и то, что в нём."]],[10702,3,9,2,"ظَهْر | ظُهُور","спина",["أحمل همّ الدين على ظهري.",19,23,"Я несу заботу о религии на своей спине."]],[10703,3,9,2,"رَأْس | رُؤُوس","голова",["رأسي به من الأمور ما يكفيه",0,4,"В моей голове столько дел, что ей хватит."]],[10704,3,9,2,"بَغْل | بِغَال","мул",["كنا نستعمل البغال في الأرياف.",11,17,"Мы использовали мулов в сельской местности."]],[10705,3,9,2,"مُدَّة | مُدَد","срок, период",["مدة الحياة قصيرة.",0,3,"Срок жизни краток."]],[10706,3,9,2,"عَرَبَة | عَرَبَات","повозка, тележка; вагон",["سأشتري الموز من العربة",16,22,"Я куплю бананы у тележки."]],[10707,3,9,2,"عَجَلَة | عَجَلَات","колесо",["هذه العجلة فاسدة لا تستخدمها",4,10,"Это колесо неисправно, не используй его."]],[10708,3,9,2,"دُونَ","без",["رأس بدون علم، هو حياة بدون هدف",4,8,"Голова без знания — жизнь без цели."]],[10709,3,9,2,"مُحَرِّك | مُحَرِّكَات","двигатель, мотор",["المعدة هي محرك جسم الإنسان",10,14,"Желудок — двигатель тела человека."]],[10710,3,9,2,"مَرْكَب | مَرَاكِب","лодка, судно",["اتجهت إلى المركب للصيد من البحر",10,16,"Я направился к лодке ловить рыбу в море."]],[10711,3,9,2,"مَرْكَبَة | مَرْكَبَات","транспортное средство",["الحافلة هي إحدى المركبات الكبيرة",16,24,"Автобус — одно из больших транспортных средств."]],[10712,3,9,2,"عَمَّا","о том, что (عن + ما)",["أخبرني عما حدث أساعدك",7,10,"Расскажи мне о том, что случилось, — я помогу тебе."]],[10713,3,9,2,"أَرْسَلَ - يُرْسِلُ - إِرْسَال","посылать, отправлять • масдар: отправка",["أرسلت صديقي للسوق المركزي",0,5,"Я отправил друга на центральный рынок."]],[10714,3,9,2,"عَدَّاء | عَدَّاؤُون","бегун, скороход",["كنت عداءً في يوم من الأيام",4,9,"Когда-то я был бегуном."]],[10715,3,9,2,"حِين | أَحْيَان","время, момент; когда",["لا أشعر بشئ حين النوم",12,15,"Я ничего не чувствую во время сна."]],[10716,3,9,2,"قَدِيمًا وَحَدِيثًا","в старину и в наши дни",["الحق واحد قديماًو حديثا",0,0,"Истина одна — и в древности, и в наши дни."]],[10717,3,9,2,"مَشْيًا عَلَى الأَقْدَام","пешком",["مررت بالحديقة مشيا على قدمي",0,0,"Я прошёл мимо парка пешком."]],[10718,3,9,2,"بَعْدَ مُدَّة","через некоторое время",["أهملت حياتي و بعد مدة أصبحت فاشلاً",14,21,"Я запустил свою жизнь и через некоторое время стал неудачником."]],[10719,3,9,2,"المَرَاكِب الشِّرَاعِيَّة","парусные суда",["المراكب الشراعية إحدى وسائل النقل",0,16,"Парусники — одно из средств передвижения."]],[10720,3,9,2,"أَوَّلًا بِأَوَّل","своевременно, по мере поступления",["لابد من معرفة الأخبار أولاً بأول",22,32,"Нужно узнавать новости своевременно."]],[10721,3,9,2,"نَقَلَ - يَنْقُلُ - نَقْل","перевозить, переносить; передавать • масдар: перевозка, транспорт",null],[10722,3,9,2,"صَنَعَ - يَصْنَعُ - صُنْع، صِنَاعَة","делать, производить • масдар: производство, промышленность",null],[10723,3,9,2,"عَدَا - يَعْدُو - عَدْو","бежать • масдар: бег",null],[10724,3,9,3,"نَدْوَة | نَدَوَات","семинар, круглый стол, симпозиум",["ما أجمل الندوات الثقافية!",8,15,"Как прекрасны культурные семинары!"]],[10725,3,9,3,"العَوْلَمَة","глобализация",["العولمة كالقدوم الذي يقطع ثقافة الأُمّة",0,7,"Глобализация — как топор, срубающий культуру нации."]],[10726,3,9,3,"مُتَحَدِّث | مُتَحَدِّثُون","выступающий, оратор, собеседник",["كم من متحدث بلا علم هذه الأيام",6,11,"Как много нынче говорящих без знания!"]],[10727,3,9,3,"حُجَّة | حُجَج","довод, аргумент, доказательство",["الرأي بدون الحجة لا فائدة فيه",11,16,"Мнение без довода бесполезно."]],[10728,3,9,3,"تَنْمِيَة","развитие",["تحتاج إلى تنمية القرى الفقيرة",10,15,"Нужно развивать бедные деревни."]],[10729,3,9,3,"هَيْمَنَة","господство, гегемония",["اللهم لا تجعل للشيطان علىّ هيمنة",27,32,"О Аллах, не дай шайтану господства надо мной."]],[10730,3,9,3,"دَارَ - يَدُورُ - دَوَرَان","вращаться; происходить (о беседе) • масдар: вращение",["دار رأسي عند سماع الخبر السيئ",0,3,"У меня закружилась голова, когда я услышал плохую новость."]],[10731,3,9,3,"نِقَاش","дискуссия, обсуждение",["لا نقاش إلا مع ذوي الخبرة",3,7,"Обсуждение — только с опытными."]],[10732,3,9,3,"حَاضِر | حُضُور، حَاضِرُون","присутствующий; настоящее время",["ليُعْلِم الحاضر الغائب عن موعد الامتحان",9,15,"Пусть присутствующий сообщит отсутствующему о времени экзамена."]],[10733,3,9,3,"فَرَضَ - يَفْرِضُ - فَرْض","предписывать, обязывать; навязывать • масдар: обязанность, предписание",["فرض علىّ أن أطيع والديّ",0,3,"Мне вменено в обязанность слушаться родителей."]],[10734,3,9,3,"اِتَّفَقَ مَعَ - يَتَّفِقُ - اِتِّفَاق","соглашаться, договариваться (с) • масдар: соглашение, согласие",["لن أتفق مع المشركين أبدًا",3,10,"Я никогда не соглашусь с многобожниками."]],[10735,3,9,3,"دَارَ نِقَاشٌ سَاخِن","разгорелась жаркая дискуссия",["عند الاجتماع دار نقاش ساخن بين الموظفين",13,26,"На собрании между сотрудниками разгорелась жаркая дискуссия."]],[10736,3,9,3,"نَمَّى - يُنَمِّي - تَنْمِيَة","развивать, растить • масдар: развитие",null],[10737,3,9,3,"هَيْمَنَ عَلَى - يُهَيْمِنُ - هَيْمَنَة","господствовать, доминировать (над) • масдар: господство",["تريد أمريكا أن تهيمن على العالم",15,20,"Америка хочет господствовать над миром."]],[10738,3,9,4,"دَوْلَة | دُوَل","государство, страна",["أصبحت الصين من الدول الكبرى",15,20,"Китай стал одной из великих держав."]],[10739,3,9,4,"أَدْعُوكَ","я приглашаю тебя, зову тебя",["أدعو أصدقائي للفطور في رمضان",0,0,"Я приглашаю друзей на ифтар в Рамадан."]],[10740,3,9,4,"تَجَوَّلَ - يَتَجَوَّلُ - تَجَوُّل","бродить, гулять, путешествовать • масдар: прогулка, путешествие",["لن أتجول في مزرعة قط",3,8,"Я никогда не буду гулять по ферме."]],[10741,3,9,4,"مَلَكَ - يَمْلِكُ - مُلْك","владеть, обладать • масдар: владение, власть",["الله يملك كل العالم",5,9,"Аллах владеет всем миром."]],[10742,3,9,4,"اِنْطَلَقَ - يَنْطَلِقُ - اِنْطِلَاق","устремиться, отправиться • масдар: старт, отправление",["انطلقت بسرعة في مسابقة الجري",0,6,"Я быстро стартовал в соревновании по бегу."]],[10743,3,9,4,"طَارَ - يَطِيرُ - طَيَرَان","летать • масдар: полёт",["البِطَريق طائر لا يطير",18,22,"Пингвин — птица, которая не летает."]],[10744,3,9,4,"أَجْمَل","красивейший, самый красивый",["أًمَنا حَوّاء كانت أجمل النساء",19,23,"Наша мать Хавва была самой красивой из женщин."]],[10745,3,9,4,"أَمْن","безопасность",["من فقد نعمة الأمن لن ينفعه ماله",12,17,"Кто потерял благо безопасности, тому не поможет его богатство."]],[10746,3,9,4,"رَخَاء","благополучие, достаток",["من يبحث عن الرخاء يعمل في مجال التجارة",11,17,"Кто ищет достатка, работает в торговле."]],[10747,3,9,4,"تَقَاتَلَ - يَتَقَاتَلُ - تَقَاتُل","сражаться друг с другом • масдар: взаимная борьба",["أتتقاتلون على الرزق وهو بيد الله",0,0,"Вы сражаетесь друг с другом за удел, а он — в руке Аллаха?"]],[10748,3,9,4,"الجَهْل","невежество",["الجهل نقمة ولو كنت غنيا",0,5,"Невежество — беда, даже если ты богат."]],[10749,3,9,4,"هَيَّا","давай! пойдём!",["هيا ننطلق إلى مكتبة القرية",0,3,"Давай отправимся в деревенскую библиотеку!"]],[10750,3,9,4,"مَا أَكْثَرَ ...!","как много…!",["ما أكثر الجهلاء في عصرنا الحديث!",0,7,"Как много невежд в наше время!"]],[10751,3,9,4,"ثِيَاب بَسِيطَة","простая одежда",["كانت ثياب الرسل بسيطة جدا",0,0,"Одежда посланников была очень простой."]],[10752,3,10,1,"النَّظَافَة","чистота",["ما أجمل الاهتمام بنظافة النفس!",17,23,"Как прекрасно заботиться о чистоте души!"]],[10753,3,10,1,"أَطْيَب","лучше, приятнее, лучший",["ما أطيب أن يصير القلب نظيفا!",3,7,"Как прекрасно, когда сердце становится чистым!"]],[10754,3,10,1,"العِطْر | عُطُور","духи, благовоние",["المؤمن المستخدم للعطر تصحبه الملائكة",16,21,"Верующего, пользующегося благовониями, сопровождают ангелы."]],[10755,3,10,1,"حَقًّا","действительно, поистине",["حقا إن لحياة لصعبةٌ في دول الشرق",0,3,"Действительно, жизнь в странах Востока трудна."]],[10756,3,10,1,"حَثَّ عَلَى - يَحُثُّ - حَثّ","побуждать, призывать (к) • масдар: побуждение, поощрение",["الإسلام يحث على الأمر بالمعروف و النهي عن المنكر",8,11,"Ислам побуждает повелевать одобряемое и запрещать порицаемое."]],[10757,3,10,1,"اِغْتَسَلَ - يَغْتَسِلُ - اِغْتِسَال","мыться (полностью), совершать гусль • масдар: омовение всего тела",["عليك أن تغتسل يوم الجمعة",8,13,"Тебе следует совершать полное омовение в пятницу."]],[10758,3,10,1,"طَهَارَة","чистота, ритуальная чистота",["طهارة النفس أفضل أنواع الطهارة",0,5,"Чистота души — лучший вид чистоты."]],[10759,3,10,1,"مَا أَطْيَبَ ...!","как прекрасно…!",["ما أطيب الفم الذاكر لله!",0,7,"Как прекрасны уста, поминающие Аллаха!"]],[10760,3,10,1,"نَظَافَة النَّفْس","чистота души",["نظافة النفس طريقك لحب الناس لك",0,11,"Чистота души — твой путь к любви людей."]],[10761,3,10,1,"مَاذَا تَقْصِدُ؟","Что ты имеешь в виду?",["ماذا تقصد بالغزو الفكري يا أستاذ؟",0,9,"Что вы имеете в виду под идеологическим вторжением, учитель?"]],[10762,3,10,1,"طَابَ - يَطِيبُ - طِيب","быть хорошим, приятным • масдар: благо, приятность",null],[10763,3,10,1,"تَوَضَّأَ - يَتَوَضَّأُ - تَوَضُّؤ","совершать омовение (вуду) • масдар: омовение",null],[10764,3,10,2,"تَوَّاب | تَوَّابُون","1) часто кающийся 2) Принимающий покаяние (имя Аллаха)",["يجب أن تكرر التوبة يوميا حتى تكون توابا",34,39,"Нужно каяться ежедневно, чтобы стать часто кающимся."]],[10765,3,10,2,"مُتَطَهِّر | مُتَطَهِّرُون","очищающийся, соблюдающий чистоту",["لا نكتفِ بأن تكون متطهر الجسم بل و القلب أيضا",18,23,"Не довольствуйся чистотой тела — пусть чистым будет и сердце."]],[10766,3,10,2,"شَطْر | أَشْطُر، شُطُور","половина",["حث الإسلام على الطهارة بأن جعلها شطر الإيمان",33,36,"Ислам побудил к чистоте, сделав её половиной веры."]],[10767,3,10,2,"جَسَد | أَجْسَاد","тело",["يجب أن تكون الأُمّةَ كالجسد الواحد ثانية",21,27,"Умма вновь должна стать как единое тело."]],[10768,3,10,2,"مَسْكَن | مَسَاكِن","жилище",["الجنة هي المسكن الدائم للمؤمنين",9,15,"Рай — вечное жилище верующих."]],[10769,3,10,2,"البِيئَة | بِيئَات","окружающая среда, среда",["علينا أن نربي أبناءنا في بيئة صالحة",25,29,"Мы должны воспитывать детей в праведной среде."]],[10770,3,10,2,"طَافَ - يَطُوفُ - طَوَاف","обходить (Каабу) • масдар: обход, таваф",["الطواف جانب أساسي في الحج و العمرة",0,6,"Таваф — основная часть хаджа и умры."]],[10771,3,10,2,"مِرْفَق | مَرَافِق","локоть",["سأجعل من مرفقي سيفا على المشركين",9,14,"Я сделаю свой локоть мечом против многобожников."]],[10772,3,10,2,"كَعْب | كُعُوب","пятка; лодыжка",["تكررت الإصابة في كعبي ثانية",17,21,"У меня снова повторилась травма пятки."]],[10773,3,10,2,"كَرَّرَ - يُكَرِّرُ - تَكْرَار","повторять • масдар: повторение",["كررت قراءة الآية حتي أحفظها جيدا",0,4,"Я повторял чтение аята, пока хорошо его не выучил."]],[10774,3,10,2,"أَزَالَ - يُزِيلُ - إِزَالَة","удалять, устранять • масдар: удаление",["أزلت أفكار الغرب من رأسي",0,0,"Я выбросил из головы западные идеи."]],[10775,3,10,2,"وَسَخ | أَوْسَاخ","грязь",["كُلمّا ازداد الوسخ ازداد المرضٍ",13,18,"Чем больше грязи, тем больше болезней."]],[10776,3,10,2,"اِكْتَفَى بِـ - يَكْتَفِي - اِكْتِفَاء","довольствоваться (чем-л.) • масдар: довольство, достаточность",["اكتفيت بزوجة واحدة و الحمد لله",0,6,"Я довольствовался одной женой, хвала Аллаху."]],[10777,3,10,2,"أَضَافَ - يُضِيفُ - إِضَافَة","добавлять • масдар: добавление",["يجب أن نضيف العلم إلى رؤوسنا يوميا",7,11,"Мы должны ежедневно добавлять знания в свои головы."]],[10778,3,10,2,"الجَنَابَة","состояние большой ритуальной нечистоты (джанаба)",["عند الجنابة لا نكتفى بالوضوء بل يجب الغسل",4,11,"При джанабе недостаточно малого омовения — нужно полное."]],[10779,3,10,2,"مُحْتَلِم","достигший половой зрелости",["تُكتب على الإنسان أعماله عندما يصبح مُحتلما",36,43,"Дела человека записываются, когда он достигает зрелости."]],[10780,3,10,2,"الحَيْض","менструация (хайд)",["يجب ألا تمسك المرأة المصحف عند الحيض",31,36,"Женщине не следует касаться Мусхафа во время менструации."]],[10781,3,10,2,"النِّفَاس","послеродовое кровотечение (нифас)",["لم تشعر المرأة بألم وقت النفاس لسعادتها بالمولود",24,30,"Женщина не чувствовала боли в период нифаса от радости за новорождённого."]],[10782,3,10,2,"لَا يَكْتَفِي ... بِـ ... بَلْ","не довольствуется …, а (ещё) …",["لا يكتفي المؤمن بطلب الجنة، بل يسأل الله الفردوس الأعلى",0,0,"Верующий не довольствуется просьбой о Рае, а просит у Аллаха высший Фирдаус."]],[10783,3,10,2,"طَهُرَ - يَطْهُرُ - طُهْر، طَهَارَة","быть чистым, очищаться • масдар: чистота",null],[10784,3,10,2,"تَكَرَّرَ - يَتَكَرَّرُ - تَكَرُّر","повторяться • масдар: повторение",null],[10785,3,10,3,"لَذِيذ","вкусный",["ليس شرطا في الطعام المتسخ ألا يكون لذيذا",35,40,"Грязная еда вполне может быть вкусной."]],[10786,3,10,3,"صِحِّيّ","здоровый, полезный для здоровья",["البيئة الصحية متوفرة في الأرياف",7,13,"Здоровая среда есть в сельской местности."]],[10787,3,10,3,"تَسَمَّمَ - يَتَسَمَّمُ - تَسَمُّم","отравляться • масдар: отравление",["إذا تسمم الطعام فقد يؤدي إلى الموت",4,8,"Если еда отравлена, это может привести к смерти."]],[10788,3,10,3,"لَاحَظَ - يُلَاحِظُ - مُلَاحَظَة","замечать, наблюдать • масдар: наблюдение, замечание",["لاحظت عدم اهتمام أخي بدراسته هذه الأيام",0,5,"Я заметил, что мой брат в эти дни не интересуется учёбой."]],[10789,3,10,3,"مُتَّسِخ","грязный, загрязнённый",["إذا كان الجو متسخا زادت الأمراض",13,18,"Если воздух грязный, болезней становится больше."]],[10790,3,10,3,"الأَكَلَات السَّرِيعَة","фастфуд",["الأكلات السريعة لها تأثير ضار على الصحة",0,15,"Фастфуд вредно влияет на здоровье."]],[10791,3,10,3,"فِكْرَة مُمْتَازَة","отличная идея",["قضاء المصيف في الإسكندرية فكرة ممتازة",26,37,"Провести лето в Александрии — отличная идея."]],[10792,3,10,3,"اِتَّسَخَ - يَتَّسِخُ - اِتِّسَاخ","пачкаться, загрязняться • масдар: загрязнение",null],[10793,3,10,4,"مَسْؤُولِيَّة","ответственность",["حوت المسؤولية كل المشاركين في العمل",4,13,"Ответственность легла на всех участников работы."]],[10794,3,10,4,"قَاسَ - يَقِيسُ - قِيَاس","измеряться (чем-л.) • масдар: измерение",["يقاس الإيمان بتقوى الله",0,0,"Вера измеряется богобоязненностью."]],[10795,3,10,4,"تَقَدُّم","продвижение, прогресс",["جدي قوىّ بالرغم من تقدّمُه في السن",19,26,"Мой дед крепок, несмотря на преклонный возраст."]],[10796,3,10,4,"مُتَحَضِّرَة","цивилизованная",["تقدم الأمم يقاس بالعقول المتحضرة",24,32,"Прогресс народов измеряется цивилизованными умами."]],[10797,3,10,4,"قَذَارَة","грязь, нечистоты",["انتشار القذارة دليل على التخلف",7,14,"Распространение грязи — признак отсталости."]],[10798,3,10,4,"أَنْفَقَ - يُنْفِقُ - إِنْفَاق","тратить, расходовать • масдар: расход, трата",["سأنفق كل ما أملك في سبيل الله",0,5,"Я потрачу всё, что имею, на пути Аллаха."]],[10799,3,10,4,"جَابَ - يَجُوبُ - جَوْب","бродить, странствовать • масдар: странствие",["جُبت المدينة بحثا عن العمل",0,0,"Я обошёл город в поисках работы."]],[10800,3,10,4,"حَاوِيَة | حَاوِيَات","контейнер (для мусора)",["المعدة حاوية الطعام وبيت الداء",7,12,"Желудок — вместилище пищи и обитель болезни."]],[10801,3,10,4,"حَرَقَ - يَحْرِقُ - حَرْق","жечь, сжигать • масдар: сжигание",["سيحرق الله المشركين يوم القيامة.",0,5,"Аллах сожжёт многобожников в Судный день."]],[10802,3,10,4,"نُفَايَة | نُفَايَات","мусор, отходы",["يجب أن نعيد صناعة النفايات مرة أخرى",18,26,"Мусор нужно перерабатывать."]],[10803,3,10,4,"أَمَاطَ - يُمِيطُ - إِمَاطَة","убирать, устранять • масдар: устранение",["أنصحك أن تميط الأفكار الخبيثة عن رأسك",9,13,"Советую тебе выбросить из головы дурные мысли."]],[10804,3,10,4,"الأَذَى","вред, обида",["إذا اشتد الأذى على المؤمن فهذا اختبار من الله",9,14,"Если вред, постигший верующего, усилился, это испытание от Аллаха."]],[10805,3,10,4,"صَدَقَة | صَدَقَات","милостыня, садака",["الصدقة للذنوب كالماء للنار",0,6,"Милостыня для грехов — как вода для огня."]],[10806,3,10,4,"يَقَعُ عَلَيْهِ","постигает его, падает на него",["أخاف أن يقع غضب الله علينا",0,0,"Я боюсь, что нас постигнет гнев Аллаха."]],[10807,3,10,4,"إِمَاطَة الأَذَى","устранение вреда (с дороги)",["سنة إماطة الأذى من أفضل السنن",4,15,"Сунна устранения вреда — одна из лучших сунн."]],[10808,3,10,4,"تَحَضَّرَ - يَتَحَضَّرُ - تَحَضُّر","становиться цивилизованным • масдар: цивилизованность",null],[10809,3,10,4,"تَخَلَّفَ - يَتَخَلَّفُ - تَخَلُّف","отставать • масдар: отсталость",null],[10810,3,10,4,"قَذِرَ - يَقْذَرُ - قَذَر","быть грязным • масдар: грязь",null],[10811,3,10,4,"حَوَى - يَحْوِي - حِوَايَة","содержать, вмещать • масдар: вмещение",null],[10812,3,11,1,"ضَايَقَ - يُضَايِقُ - مُضَايَقَة","беспокоить, досаждать • масдар: беспокойство, притеснение",["الذباب يضايقني كثيرا أثناء الدرس",7,14,"Мухи очень мешают мне во время урока."]],[10813,3,11,1,"رَحَّبَ بِـ - يُرَحِّبُ - تَرْحِيب","приветствовать (кого-л.) • масдар: приветствие, радушный приём",["رحّب الأستاذ بفكرتي جدا",0,4,"Преподаватель очень приветствовал мою идею."]],[10814,3,11,1,"أُمِّيّ | أُمِّيُّون","неграмотный",["يوجد كثير من الأميين في الدول المتخلفة",13,20,"В отсталых странах много неграмотных."]],[10815,3,11,1,"زَمَن | أَزْمِنَة، أَزْمَان","время, эпоха",["أضحى الزمن يمر بسرعة في الحاضر",5,10,"Сейчас время стало идти быстро."]],[10816,3,11,1,"أَثْبَتَ أَنَّ - يُثْبِتُ - إِثْبَات","доказывать, утверждать • масдар: доказательство, утверждение",["سأثبت لك كلامي بدليل من القرآن",0,5,"Я докажу тебе свои слова доводом из Корана."]],[10817,3,11,1,"دَلِيل | أَدِلَّة، دَلَائِل","доказательство, довод; указатель, путеводитель",["صعوبة لغة القرآن دليل على فصاحة العرب",17,21,"Трудность языка Корана — доказательство красноречия арабов."]],[10818,3,11,1,"عِرْق | أَعْرَاق","раса, корень, происхождение",["العرق الهندي موجود في أمريكا حتى الآن",0,5,"Индийцы (коренные) есть в Америке до сих пор."]],[10819,3,11,1,"المُعَادِي | مُعَادُون","враждебный, враг",["لا تصاحب المعادين للحق.",9,17,"Не дружи с врагами истины."]],[10820,3,11,1,"مُحَايِد | مُحَايِدُون","нейтральный, беспристрастный",["على القاضي أن يكون محايدا في الحُكم",19,25,"Судья должен быть беспристрастным в решении."]],[10821,3,11,1,"أَرَّخَ - يُؤَرِّخُ - تَأْرِيخ","писать историю, датировать • масдар: историография, датировка",["من أرّخ أحداث الماضي يعرف أحداث المستقبل",3,7,"Кто записал события прошлого, знает события будущего."]],[10822,3,11,1,"مُؤَرِّخ | مُؤَرِّخُون","историк",["على المؤرخ أن يلاحظ ما يكتبه جيدا",4,10,"Историк должен внимательно следить за тем, что пишет."]],[10823,3,11,1,"حَقَائِق عِلْمِيَّة","научные факты",["يبحث العلماء عن الحقائق العلمية يوما بعد يوم",16,31,"Учёные изо дня в день ищут научные факты."]],[10824,3,11,1,"فِي كُلِّ زَمَانٍ وَمَكَانٍ","во все времена и во всех местах",["للعلماء قيمتهم في كل زمان و مكان",0,0,"Учёные ценны во все времена и во всех местах."]],[10825,3,11,1,"كَاتِب مُحَايِد","беспристрастный писатель",["الكاتب المحايد له تأثيره في العلم",0,14,"Беспристрастный писатель влияет на науку."]],[10826,3,11,1,"الشَّيْء الكَثِير","многое, очень много",["قرأت عن السيرة الشئ الكثير",0,0,"Я многое прочитал о сире."]],[10827,3,11,1,"إِذَنْ","значит, следовательно",["اقرأ الكُتّاب محايدين، إذن تأخذ علما سليما",23,26,"Читай беспристрастных авторов — тогда получишь верное знание."]],[10828,3,11,1,"أَسْعَدَ - يُسْعِدُ - إِسْعَاد","делать счастливым, радовать • масдар: осчастливливание",null],[10829,3,11,1,"عَادَى - يُعَادِي - مُعَادَاة","враждовать • масдар: вражда",null],[10830,3,11,1,"حَايَدَ - يُحَايِدُ - مُحَايَدَة","сохранять нейтралитет • масдар: нейтралитет",null],[10831,3,11,2,"التَّوْحِيد","единобожие (таухид); единение",["اللهم لك الحمد على نعمة التوحيد",24,31,"О Аллах, хвала Тебе за благо единобожия."]],[10832,3,11,2,"البَاقِي","вечный, остающийся",["العمل الصالح هو الباقي للإنسان في قبره",16,22,"Праведные дела — то, что остаётся человеку в могиле."]],[10833,3,11,2,"نَسَخَ - يَنْسَخُ - نَسْخ","отменять; копировать, переписывать • масдар: отмена; копирование",["جاءت بعض الآيات تنسخ أحكام آيات أخرى / نسخت الورقة نسختين في المكتبة",39,43,"Некоторые аяты отменяют постановления других аятов. / Я сделал две копии листа в библиотеке."]],[10834,3,11,2,"اِبْتَغَى - يَبْتَغِي - اِبْتِغَاء","желать, стремиться • масдар: стремление",["و من يبتغ غير الإسلام ديناًفلن يقبل منه",0,0,"Кто ищет иной религии, кроме ислама, у того она не будет принята."]],[10835,3,11,2,"تَكَفَّلَ بِـ - يَتَكَفَّلُ - تَكَفُّل","брать на себя (ответственность), гарантировать • масдар: поручительство, обеспечение",["تكفلت بعلاج هذا الطفل المريض / تكفل الله بحفظ دينه إلى يوم القيامة",0,5,"Я взял на себя лечение этого больного ребёнка. / Аллах взял на Себя сохранение Своей религии до Судного дня."]],[10836,3,11,2,"سَبَقَ - يَسْبِقُ - سَبْق","опережать, предшествовать • масдар: опережение, первенство",["جاء القرآن بقصص من سبقنا من الشعوب",19,24,"Коран принёс истории народов, бывших до нас."]],[10837,3,11,2,"سِبْط | أَسْبَاط","внук; колено (племя израильтян)",["ذكر لنا القرآن تاريخ الأسباط و غيرهم",21,28,"Коран рассказал нам историю колен (Израилевых) и других."]],[10838,3,11,2,"فَرَّقَ - يُفَرِّقُ - تَفْرِيق","разделять, различать • масдар: разделение, различение",["اللهم لا تفرق بين قلوب المسلمين",9,13,"О Аллах, не разъединяй сердца мусульман."]],[10839,3,11,2,"الظُّلْم","несправедливость, угнетение",["لا تظن أن الظلم لن ينتهي",10,15,"Не думай, что несправедливость не закончится."]],[10840,3,11,2,"اِنْقَادَ - يَنْقَادُ - اِنْقِيَاد","подчиняться, покоряться • масдар: подчинение, покорность",["سننقاد إلى الخالق لحسابنا يوم القيامة",0,6,"Мы будем приведены к Творцу на расчёт в Судный день."]],[10841,3,11,2,"رَغْبَة","желание, стремление",["الرغبة في الشئ ليست شرطا للحصول عليه",0,6,"Желание чего-то — не условие его получения."]],[10842,3,11,2,"المُسَاوَاة","равенство",["كن عادلاً تتحقق بك المساواة",19,27,"Будь справедлив — и через тебя осуществится равенство."]],[10843,3,11,2,"أَعْجَمِيّ | أَعَاجِم","неараб, иноземец",["سيبوية كان أعجميا ورغم ذلك أصبح عالما في النحو",11,17,"Сибавейх был неарабом, но всё же стал учёным в грамматике."]],[10844,3,11,2,"التَّقْوَى","богобоязненность (таква)",["تقوى الله هي مقياس دخول الجنة",0,4,"Богобоязненность — мерило входа в Рай."]],[10845,3,11,2,"لِكُلِّ زَمَانٍ وَمَكَانٍ","для всех времён и мест",["مر بالمعروف في كل زمان و مكان",0,0,"Повелевай одобряемое во все времена и во всех местах."]],[10846,3,11,2,"دِين عَامّ","общая (всеобщая) религия",["كانت المسيحية هي الدين العام قبل الإسلام",17,28,"До ислама христианство было общей религией."]],[10847,3,11,2,"رَفْع الظُّلْم","устранение несправедливости",["رفع الرئيس ظلمه عن الناس بعد الثورة",0,0,"После революции президент снял с людей гнёт."]],[10848,3,11,2,"رَغْبَةً لَا رَهْبَةً","по желанию, а не из страха",["تركت السرقة رغبة في الحلال لا رهبة من الظابط",0,0,"Я бросил воровать из стремления к дозволенному, а не из страха перед офицером."]],[10849,3,11,2,"كُلُّكُمْ لِـ","все вы принадлежите…",["أنت و أموالك كلكم لأبيك",13,17,"Ты и твоё имущество принадлежите твоему отцу."]],[10850,3,11,2,"لَا فَضْلَ","нет превосходства",["لا فضل لأحد عليّ بعد الله إلا لأبي",0,6,"Ни у кого нет передо мной заслуги после Аллаха, кроме моего отца."]],[10851,3,11,2,"رَهِبَ - يَرْهَبُ - رَهْبَة","бояться, страшиться • масдар: страх, трепет",null],[10852,3,11,2,"سَاوَى - يُسَاوِي - مُسَاوَاة","приравнивать; стоить • масдар: равенство",null],[10853,3,11,3,"أَسْلَمَ - يُسْلِمُ - إِسْلَام","принять ислам • масдар: ислам, принятие ислама",["من أسلم فقد فاز بالدارين",3,7,"Кто принял ислам, тот преуспел в обоих мирах."]],[10854,3,11,3,"بِانْتِظَام","регулярно, систематически",["آتيت العمال حقوقهم بانتظام",19,26,"Я регулярно выплачивал рабочим их права."]],[10855,3,11,3,"قَادِم | قَادِمُون","приходящий, следующий, будущий",["أخاف على شبابنا من العصر القادم",25,31,"Я боюсь за нашу молодёжь в грядущую эпоху."]],[10856,3,11,3,"وَصَفَ - يَصِفُ - وَصْف، صِفَة","описывать • масдар: описание; качество",["الأنهار الجارية من أحد أوصاف الجنة",0,0,"Текущие реки — одно из описаний Рая."]],[10857,3,11,3,"جَنِين | أَجِنَّة","зародыш, плод",["كُنّا أجنة في بطون أمهاتنا",6,10,"Мы были зародышами в утробах наших матерей."]],[10858,3,11,3,"الصِّدْق","правдивость",["الصدق نعمة من اتبعها فقد فاز",0,5,"Правдивость — благо: кто следует ей, тот преуспел."]],[10859,3,11,3,"الأَمَانَة | أَمَانَات","честность, верность; вверенное на хранение",["رد الأمانة إلى أصحابها حتى لا تكون منافقا",3,10,"Возвращай доверенное владельцам, чтобы не быть лицемером."]],[10860,3,11,3,"العَدْل","справедливость",["العدل أساس المُلك",0,5,"Справедливость — основа власти."]],[10861,3,11,3,"عَمِيقَة","глубокая",["لديّ إصابة عميقة في قدمي",11,16,"У меня глубокая рана на ноге."]],[10862,3,11,3,"أَعَارَ - يُعِيرُ - إِعَارَة","одалживать (вещь) • масдар: одалживание",["أعارنا الله السمع و البصر لطاعته بهما",0,6,"Аллах дал нам на время слух и зрение, чтобы мы покорялись Ему ими."]],[10863,3,11,3,"سُرُور","радость, удовольствие",["السرور الحقيقي في تحقيق الأهداف",0,6,"Настоящая радость — в достижении целей."]],[10864,3,11,3,"قِرَاءَات عَدِيدَة","многочисленные чтения (кираат)",["أدرس القرآن بالقراءات العديدة",12,29,"Я изучаю Коран в разных чтениях."]],[10865,3,11,3,"دِرَاسَات عَمِيقَة","глубокие исследования",["حتى تكون أستاذا في الجامعة لابد من البحث في دراسات عميقة",44,56,"Чтобы стать преподавателем университета, нужны глубокие исследования."]],[10866,3,11,3,"بِكُلِّ سُرُورٍ","с большим удовольствием",["انقدت لكلام الأستاذ بكل سرور",20,28,"Я с радостью подчинился словам преподавателя."]],[10867,3,11,4,"رُكْن | أَرْكَان","столп, основа; угол",["السعي ركن أساسي في العمرة و الحج",6,9,"Сай — основной столп умры и хаджа."]],[10868,3,11,4,"تَعْرِيف | تَعْرِيفَات، تَعَارِيف","определение",["اذكر تعريفا لكلمة العولمة",5,11,"Дай определение слова «глобализация»."]],[10869,3,11,4,"عَمُود | أَعْمِدَة، عُمُد","столб, колонна, опора",["الزوجة الصالحة أحد أعمدة المنزل",19,24,"Праведная жена — одна из опор дома."]],[10870,3,11,4,"ذُرْوَة | ذُرًا، ذُرُوَات","вершина, пик",["لا تركب السيارة في ساعة الذروة.",24,30,"Не езди на машине в час пик."]],[10871,3,11,4,"سَنَام | أَسْنِمَة","горб (верблюда)",["لا أحد يركب فوق سنام العلم",16,20,"Никто не взберётся на самый горб знания."]],[10872,3,11,4,"حَاسَبَ - يُحَاسِبُ - مُحَاسَبَة","требовать отчёта, рассчитываться • масдар: расчёт, отчёт",["لا شك أننا سنحاسب على أعمالنا",11,17,"Несомненно, с нас будет спрошено за наши дела."]],[10873,3,11,4,"صَلَحَ - يَصْلُحُ - صَلَاح","быть праведным, годным • масдар: праведность",["إن صلح القلب صلح كل الجسم",3,6,"Если сердце праведно, праведно и всё тело."]],[10874,3,11,4,"سَائِر","остальной, все прочие",["فضّل الله الإنسان على سائر المخلوقات",22,26,"Аллах возвысил человека над всеми прочими творениями."]],[10875,3,11,4,"مُعَيَّنَة","определённая",["توجد أوقات معينة لقُبول الدعاء",11,16,"Есть определённые времена для принятия мольбы."]],[10876,3,11,4,"مَوْقُوت","приуроченный к определённому времени",["الحصص الدراسية موقوته بوقت معين",15,21,"Учебные занятия приурочены к определённому времени."]],[10877,3,11,4,"زَكَّى - يُزَكِّي - تَزْكِيَة","очищать; выплачивать закят • масдар: очищение",["زكيت نفسي عن الأخطاء ونفس و ما زكاها",0,4,"Я очистил свою душу от ошибок. «И душою, и тем, кто её очистил»."]],[10878,3,11,4,"شَهْوَة | شَهَوَات","страсть, вожделение",["الشهوة هي طريق الشيطان لنفس الإنسان لا تتبع شهوتك يا ابن آدم",0,6,"Страсть — путь шайтана к душе человека. Не следуй своей страсти, сын Адама."]],[10879,3,11,4,"فَرْج | فُرُوج","срамная часть, половой орган",["اللهم اجعلنى من عبادك الحافظين لفروجهم",31,38,"О Аллах, сделай меня из Твоих рабов, оберегающих свою целомудренность."]],[10880,3,11,4,"اِحْتِسَاب","надежда на награду от Аллаха",["اتبع الحق واحتسب الأجر عند الله",0,0,"Следуй истине и надейся на награду у Аллаха."]],[10881,3,11,4,"ذَنْب | ذُنُوب","грех",["رب اغفر لي ذنوبي ما ظهر منها وما خَفَي",11,16,"Господи, прости мне мои грехи, явные и скрытые."]],[10882,3,11,4,"مَنْسَك | مَنَاسِك","обряд (хаджа), ритуал",["دراسة الفقه تُعلمُنَا كيف نؤدي المناسك",31,38,"Изучение фикха учит нас, как совершать обряды."]],[10883,3,11,4,"رَأْس الأَمْر","главное в деле",["في الحاضر، رأس الأمر العلم",11,20,"Сейчас главное — знания."]],[10884,3,11,4,"ذُرْوَة سَنَامِهِ","вершина его горба (наивысшая степень)",["ذروة سنام العبادة هي الإحسان",0,0,"Наивысшая степень поклонения — ихсан."]],[10885,3,11,4,"كِتَاب مَوْقُوت","предписание, приуроченное к сроку",["مواعيد عملنا كتاب موقوت.",13,23,"Наше рабочее время — строго определено."]],[10886,3,11,4,"إِيمَانًا وَاحْتِسَابًا","с верой и надеждой на награду",["صبرت على ظلم أخي إيمانا و احتسابا",0,0,"Я терпел несправедливость брата с верой и надеждой на награду."]],[10887,3,11,4,"كُتِبَ عَلَيْهِ","предписано ему",["كُتِبَ على آبائنا التعب صغارا و كبارا",0,0,"Нашим отцам было предписано трудиться и в детстве, и в старости."]],[10888,3,11,4,"حَجَّ - يَحُجُّ - حَجّ","совершать хадж • масдар: хадж",null],[10889,3,11,4,"فَسَدَ - يَفْسُدُ - فَسَاد","портиться • масдар: порча, коррупция",null],[10890,3,11,4,"اِحْتَسَبَ - يَحْتَسِبُ - اِحْتِسَاب","надеяться на награду от Аллаха • масдар: надежда на награду",null],[10891,3,12,1,"مُرَاهِق | مُرَاهِقُون","подросток",["معاملة المراهقين لها مقاييس مختلفة",7,16,"Обращение с подростками имеет иные мерки."]],[10892,3,12,1,"شَاءَ - يَشَاءُ - مَشِيئَة","желать, хотеть (о воле Аллаха) • масдар: воля, желание",["ما شاء الله كان وما لم يشأ لم يكن",3,6,"Что пожелал Аллах — то было, чего не пожелал — того не было."]],[10893,3,12,1,"طَبِيعِيّ","естественный, нормальный",["من الطبيعي أن يتغير أسلوب معاملة المراهق",3,10,"Естественно, что манера обращения с подростком меняется."]],[10894,3,12,1,"نَسِيَ - يَنْسَى - نِسْيَان","забывать • масдар: забвение, забывчивость",["اللهم ذكرني بما نسيت يارب العالمين",16,20,"О Аллах, напомни мне то, что я забыл, Господь миров!"]],[10895,3,12,1,"أَتَمَّ - يُتِمُّ - إِتْمَام","завершать, доводить до конца • масдар: завершение",["أتم الله عليّ نعمه بالزوجة الصالحة",0,3,"Аллах завершил Свои милости мне праведной женой."]],[10896,3,12,1,"عَامَلَ - يُعَامِلُ - مُعَامَلَة","обращаться (с кем-л.) • масдар: обращение, отношение; сделка",["عامل أباك معاملة حسنة",0,4,"Обращайся со своим отцом хорошо."]],[10897,3,12,1,"حِكْمَة | حِكَم","мудрость",["من أوتي الحكمة فقد ظفر",8,14,"Кому дарована мудрость, тот преуспел."]],[10898,3,12,1,"نَفَعَ - يَنْفَعُ - نَفْع","приносить пользу • масдар: польза",["اللهم أنفع بنا الإسلام و المسلمين",6,10,"О Аллах, принеси через нас пользу исламу и мусульманам."]],[10899,3,12,1,"سَلِيم","здоровый, верный, невредимый",["العقل السليم في الجسم السليم",6,12,"В здоровом теле — здоровый дух."]],[10900,3,12,1,"حَاوَرَ - يُحَاوِرُ - مُحَاوَرَة","вести диалог, беседовать • масдар: диалог, беседа",["إذا حاورت الجاهل ستصاب بالضرر",4,9,"Если будешь спорить с невеждой, тебе будет вред."]],[10901,3,12,1,"مَرْحَلَة المُرَاهَقَة","подростковый возраст",["مرحلة المراهقة من أخطر المراحل في حياة الإنسان",0,14,"Подростковый возраст — один из опаснейших этапов жизни человека."]],[10902,3,12,1,"مَتَى شَاءَ","когда пожелает",["المسلم لا يفعل ما شاء متى شاء، بل يفعل ما شاء الله",22,29,"Мусульманин не делает что хочет и когда хочет, а делает то, что пожелал Аллах."]],[10903,3,12,1,"شُعُور طَبِيعِيّ","естественное чувство",["الحزن على حال الأمة شعور طبيعي",20,30,"Печаль о положении уммы — естественное чувство."]],[10904,3,12,1,"فِي الحَقِيقَة","на самом деле",["في الحقيقة أنا مشغول اليوم",0,10,"На самом деле, я сегодня занят."]],[10905,3,12,1,"أَخْبَرَ - يُخْبِرُ - إِخْبَار","сообщать • масдар: сообщение, информирование",null],[10906,3,12,1,"خَافَ مِنْ - يَخَافُ - خَوْف","бояться (кого-л./чего-л.) • масдар: страх",null],[10907,3,12,1,"اِحْتَرَمَ - يَحْتَرِمُ - اِحْتِرَام","уважать • масдар: уважение",["احترمت رأي أخي رغم أنه صغير",0,6,"Я уважал мнение брата, хотя он младше."]],[10908,3,12,2,"أَغْلَى","самый дорогой, дороже",["ذكر الله أغلى من كل الثروات",9,13,"Поминание Аллаха дороже всех богатств."]],[10909,3,12,2,"ثَرْوَة | ثَرَوَات","богатство, состояние",["الشباب ثروة لمن يعرف قيمتهم",7,11,"Молодёжь — богатство для того, кто знает её ценность."]],[10910,3,12,2,"العَطَاء","дар, отдача, щедрость",["أَطع الله قبل أن تسأله العطاء",23,29,"Покорись Аллаху, прежде чем просить у Него даров."]],[10911,3,12,2,"قَلَّمَا","редко",["قَلَمَا ينافس المسلمون في الصناعات الحديثة",0,7,"Мусульмане редко конкурируют в современных отраслях."]],[10912,3,12,2,"بَقِيَّة","остаток, оставшаяся часть",["ربما لا يوجد في العمر بَقِيّة لفعل الخير",22,29,"Возможно, в жизни не останется времени на добрые дела."]],[10913,3,12,2,"وَلَّى - يُوَلِّي - تَوْلِيَة","назначать, поручать (управление) • масдар: назначение",["وليت عقلي مسئولية التفكير السليم",0,4,"Я поручил своему разуму ответственность за здравое мышление."]],[10914,3,12,2,"قِيَادَة","руководство, лидерство; вождение",["قيادة الطائرة أمر ليس سهلاً / من لم يكن قائدا لنفسه،فلن يكون قائدا لأمته",0,5,"Управлять самолётом нелегко. / Кто не руководит собой, тот не станет вождём своего народа."]],[10915,3,12,2,"قَائِد | قَادَة، قُوَّاد","командир, лидер, вождь",["سأتدرب في مركز إعداد القادة",21,27,"Я буду тренироваться в центре подготовки лидеров."]],[10916,3,12,2,"الجَيْش | جُيُوش","армия",["تغزو الشياطين بني آدم بجيوشها",22,29,"Шайтаны нападают на сынов Адама со своими армиями."]],[10917,3,12,2,"غَزْوَة | غَزَوَات","военный поход, битва",["أرجو نيل الشهادة في غزوة على الكفار",20,24,"Надеюсь удостоиться мученичества в походе против неверных."]],[10918,3,12,2,"القَاضِي | قُضَاة","судья",["اللهم عليك بالقاضي الظالم",11,18,"О Аллах, накажи несправедливого судью."]],[10919,3,12,2,"الجَادّ","серьёзный, усердный",["العمل الجاد يؤدي إلى مجتمع ناجح",6,11,"Усердный труд ведёт к успешному обществу."]],[10920,3,12,2,"أَخْطَأَ - يُخْطِئُ - خَطَأ","ошибаться • масдар: ошибка",["قد تخطئ كثيرا، وهذا لا يمنعك عن إصلاح نفسك",3,7,"Ты можешь часто ошибаться, но это не мешает тебе исправлять себя."]],[10921,3,12,2,"كَبِير | كِبَار","большой; старший, пожилой",["الخطأ الكبير يحتاج إلى استغفار كثير",6,12,"Большая ошибка требует многократной просьбы о прощении."]],[10922,3,12,2,"أَغْلَى ثَرْوَة","самое ценное богатство",["الزوجة الصالحة هي أغلى ثروة في الحياة",18,27,"Праведная жена — самое ценное богатство в жизни."]],[10923,3,12,2,"مَرْحَلَة العَطَاء","этап отдачи (работы)",["الدنيا هي مرحلة العطاء قبل الآخرة",10,22,"Этот мир — этап деяний перед вечной жизнью."]],[10924,3,12,2,"بَقِيَّة عُمْرِهِ","остаток его жизни",["سأقضي بقية عمري في الدعوة",0,0,"Я проведу остаток жизни в призыве."]],[10925,3,12,2,"قِيَادَة الجَيْش","командование армией",["اللهم ولَّني قيادة جيش المسلمين",13,22,"О Аллах, поручи мне командование армией мусульман."]],[10926,3,12,2,"عَلَاقَة طَيِّبَة","хорошие отношения",["يارب أدم العلاقة الطيبة بيني وبين صديقي",9,23,"Господи, сохрани добрые отношения между мной и моим другом."]],[10927,3,12,2,"قَادَ - يَقُودُ - قِيَادَة","вести, руководить; водить (машину) • масдар: руководство; вождение",null],[10928,3,12,2,"غَزَا - يَغْزُو - غَزْو","совершать набег, завоёвывать • масдар: набег, завоевание",null],[10929,3,12,2,"جَدَّ - يَجِدُّ - جِدّ","усердствовать, быть серьёзным • масдар: серьёзность, усердие",null],[10930,3,12,3,"مَوْضُوع | مَوْضُوعَات","тема, предмет",["تناقشنا في واحد من أهم موضوعات الكتاب",23,30,"Мы обсудили одну из важнейших тем книги."]],[10931,3,12,3,"دَوْر | أَدْوَار","роль; этаж; очередь",["على الإنسان دور في عمارة العالم",12,15,"У человека есть роль в обустройстве мира."]],[10932,3,12,3,"تَجْرِبَة | تَجَارِب","опыт, эксперимент",["قرأت عن تجربة الزراعة على القمر",8,13,"Я читал об эксперименте по выращиванию растений на Луне."]],[10933,3,12,3,"اِسْتَمَعَ إِلَى - يَسْتَمِعُ - اِسْتِمَاع","слушать (кого-л.) • масдар: слушание",["استمع كل ذي قلب سليم",0,5,"Слушает каждый, у кого здравое сердце."]],[10934,3,12,3,"مَوْضُوع مُهِمّ","важная тема",["دار نقاش ساخن بيننا في موضوع مهم",23,32,"Между нами разгорелась горячая дискуссия по важной теме."]],[10935,3,12,3,"دَوْرُهُ اِنْتَهَى","его роль окончена",["ما انتهى دورك عند قراءة الموضوع، بل عليك تلخصيه",0,0,"Твоя роль не заканчивается на чтении темы — тебе нужно её резюмировать."]],[10936,3,12,3,"بَلْ وَحَتَّى","и даже",["لم أشترك في المسابقة، بل وحتى أخرجت منها صديقي",22,29,"Я не участвовал в конкурсе и даже вывел из него своего друга."]],[10937,3,12,3,"أَتَّبِعُ نَصَائِحَهُ","следую его советам",["المدير ذو الخبرة و عليك أن تتبع نصائحه",0,0,"Директор опытен, и тебе следует следовать его советам."]],[10938,3,12,3,"جَرَّبَ - يُجَرِّبُ - تَجْرِبَة","пробовать, испытывать • масдар: проба, эксперимент",["جَرَّبت الثلاجة فوجدتها فاسدة لا تعمل",0,7,"Я проверил холодильник и обнаружил, что он сломан."]],[10939,3,12,4,"الغَزْو","вторжение, нашествие",["أضرار الغزو الفكري أشد تأثيرا من غيره",6,11,"Вред идеологического вторжения сильнее прочих."]],[10940,3,12,4,"مَزَّقَ - يُمَزِّقُ - تَمْزِيق","рвать, разрывать • масдар: разрыв, раздробление",["مزقت كل أسباب للفشل",0,4,"Я разорвал все причины неудачи."]],[10941,3,12,4,"فَصَلَ عَنْ - يَفْصِلُ - فَصْل","отделять, отключать; увольнять • масдар: отделение; увольнение",["فصلت الشبكة الدولية عن منزلي",0,4,"Я отключил Интернет в доме."]],[10942,3,12,4,"تُرَاث","наследие",["تراث أمتنا لا مثيل له في الازدهار",0,4,"Наследию нашей уммы нет равных в процветании."]],[10943,3,12,4,"قَلَّدَ - يُقَلِّدُ - تَقْلِيد","подражать, имитировать • масдар: подражание",["الببغاء يقلد كلام الناس",8,12,"Попугай подражает речи людей."]],[10944,3,12,4,"سُلُوك | سُلُوكِيَّات","поведение",["أضحى سلوك ذوي العلم مختلفا عن أقوالهم",5,9,"Поведение образованных стало расходиться с их словами."]],[10945,3,12,4,"التَّنَاقُض","противоречие",["أشعر بتناقض شديد في حياتك",5,11,"Я чувствую сильное противоречие в твоей жизни."]],[10946,3,12,4,"بَثَّ - يَبُثُّ - بَثّ","транслировать, распространять • масдар: трансляция",["انقطع بث التلفاز عند المطر",6,8,"Во время дождя телетрансляция прервалась."]],[10947,3,12,4,"خَالَفَ - يُخَالِفُ - مُخَالَفَة","противоречить, нарушать • масдар: нарушение, противоречие",["خالفت رأي الأئمة في أمور الفقه.",0,5,"Ты расходишься с мнением имамов в вопросах фикха."]],[10948,3,12,4,"التَّأْثِير","влияние, воздействие",["العولمة لها التأثير الأقوى في فساد الأمة",12,19,"Глобализация оказывает сильнейшее влияние на порчу уммы."]],[10949,3,12,4,"كَلَّفَ - يُكَلِّفُ - تَكْلِيف","стоить (кому-л.); поручать • масдар: поручение, обязанность; затраты",["كلفني هذا العمل كثيرا من الوقت",0,5,"Эта работа отняла у меня много времени."]],[10950,3,12,4,"شَكّ | شُكُوك","сомнение",["لا شكّ أنّ الحق ظاهر للجميع.",3,6,"Нет сомнения, что истина очевидна для всех."]],[10951,3,12,4,"البِنَاء","строительство, созидание",["من يسعى للهدم لن يستغرق وقتا كالبناء",29,36,"Тому, кто стремится к разрушению, не нужно столько времени, сколько для созидания."]],[10952,3,12,4,"وَمِنْ ذٰلِكَ","и в том числе…, и из этого",["كلفتني سيارتي نقودا كثيرة، ومع ذلك لم أبعها",0,0,"Машина стоила мне много денег, и тем не менее я её не продал."]],[10953,3,12,4,"فِي صُوَرٍ كَثِيرَة","во многих формах",["واجهت العناء في صور كثيرة",13,25,"Я сталкивался с трудностями во многих формах."]],[10954,3,12,4,"فَرْض لُغَاتٍ مَحَلَّهَا","навязывание других языков вместо него",["لغتي هي أم اللغات، ولن تُفْرَضَ لغات محلها",0,0,"Мой язык — мать языков, и другие языки не будут навязаны вместо него."]],[10955,3,12,4,"تَمْزِيق الأُمَّة","раскол уммы",["يعمل الغرب بكل السبل على تمزيق الأمة",25,36,"Запад всеми путями работает над расколом уммы."]],[10956,3,12,4,"الفَصْل عَنِ التُّرَاث","отрыв от наследия",["مهما زاد الغززو الثقافي،فلن أتأثر بالفصل عن تراثي",34,49,"Как бы ни усиливалось культурное вторжение, я не оторвусь от своего наследия."]],[10957,3,12,4,"لَا شَكَّ","несомненно",["لا شك أن نهايتنا الموت",0,5,"Несомненно, наш конец — смерть."]],[10958,3,12,4,"هُوَ عَلَى حَقّ","он прав",["إن اتبعت الصالحين فأنت على حق",0,0,"Если ты следуешь праведным, ты прав."]],[10959,3,12,4,"عَمَلِيَّة البِنَاء","процесс строительства (развития)",["لن تتحق عملية بناء المجتمعات إلا ببناء العقول",8,18,"Строительство обществ не осуществится без воспитания умов."]],[10960,3,12,4,"تَنَاقَضَ - يَتَنَاقَضُ - تَنَاقُض","противоречить друг другу • масдар: противоречие",null],[10961,3,13,1,"حَلَّ - يَحُلُّ - حَلّ","решать (задачу); развязывать • масдар: решение",["حلَّ فريق سؤالا و حل الآخر جميع الأسئلة",0,4,"Одна команда решила один вопрос, а другая — все вопросы."]],[10962,3,13,1,"مِسَاحَة | مِسَاحَات","площадь",["مساحة شقتي 100متر مربع",0,5,"Площадь моей квартиры — 100 квадратных метров."]],[10963,3,13,1,"اِحْتَلَّ - يَحْتَلُّ - اِحْتِلَال","оккупировать, занимать • масдар: оккупация",["يحتل اليهود فلسطين",0,4,"Иудеи оккупируют Палестину."]],[10964,3,13,1,"أَنْقَذَ مِنْ - يُنْقِذُ - إِنْقَاذ","спасать (от) • масдар: спасение",["أنقذ الطالب الأستاذ من الغرق في البحر",0,4,"Студент спас преподавателя, тонувшего в море."]],[10965,3,13,1,"أَكْثَر + مُضَاف إِلَيْهِ + مَصْدَر","самый (+ род. п. + масдар)",["من أكثر الطلاب علما",0,0,"Один из самых знающих студентов."]],[10966,3,13,2,"مِيزَة | مِيزَات","достоинство, преимущество",["لمركز كلمة ميزات كثيرة",11,16,"У центра «Калима» много преимуществ."]],[10967,3,13,2,"مِنْطَقَة | مَنَاطِق","район, область, зона",["في أي منطقة تسكنْ؟",6,11,"В каком районе ты живёшь?"]],[10968,3,13,2,"مُحِيط | مُحِيطَات","океан",["يضم العالم ثلاثة محيطات",17,23,"В мире три океана."]],[10969,3,13,2,"طَائِعَة","послушная, добровольная",["يصلي طفلي طائعا و أحيانا كارها",0,0,"Мой ребёнок молится то охотно, то нехотя."]],[10970,3,13,2,"وَحَّدَ بَيْنَ - يُوَحِّدُ - تَوْحِيد","объединять • масдар: объединение; единобожие",["اللهم وحد بين صفوف المسلمين",6,13,"О Аллах, объедини ряды мусульман."]],[10971,3,13,2,"قِبْلَة | قِبْلَات","кибла (направление молитвы)",["الكعبة قبلة المسلمين",7,11,"Кааба — кибла мусульман."]],[10972,3,13,2,"مَزِيَّة | مَزَايَا","преимущество, достоинство",["لمصر مزايا كثيرة و عيوب قليلة",5,10,"У Египта много достоинств и мало недостатков."]],[10973,3,13,2,"مَمَرّ | مَمَرَّات","проход, коридор, пролив",["هذا الممر سيؤدي بك للمسجد",4,9,"Этот проход приведёт тебя к мечети."]],[10974,3,13,2,"خَلِيج | خُلْجَان","залив",["ذهبت في رحلة مع المركز إلى خليج السويس",27,31,"Я ездил с центром в поездку к Суэцкому заливу."]],[10975,3,13,2,"مَعْدِن | مَعَادِن","металл; минерал",["تحت أراضي العرب معادن كثيرة",16,21,"Под землями арабов много полезных ископаемых."]],[10976,3,13,2,"عَدِيدَة","многочисленные",["في الحي العاشر مراكز عديدة",21,26,"В Десятом районе многочисленные центры."]],[10977,3,13,2,"الكُرَة الأَرْضِيَّة","земной шар",["ما أضيق تلك الكرة الأرضية!",12,25,"Как тесен этот земной шар!"]],[10978,3,13,2,"مِنْ ... إِلَى","от … до …",["مشيت من الحي العاشر إلى رمسيس",0,0,"Я прошёл пешком от Десятого района до Рамсиса."]],[10979,3,13,2,"كَالقَلْبِ","как сердце",["مصر كالقلب لدول العرب",4,10,"Египет — как сердце для арабских стран."]],[10980,3,13,2,"مَازَ - يَمِيزُ - مَيْز","отличать, выделять • масдар: различение; отличие",null],[10981,3,13,2,"شَمِلَ - يَشْمَلُ - شُمُول","охватывать, включать • масдар: охват",null],[10982,3,13,3,"ضَعْف","слабость",["من أسباب ضعف لغة الطالب قلة استماعه",9,12,"Одна из причин слабого языка студента — то, что он мало слушает."]],[10983,3,13,3,"هَمّ | هُمُوم","забота, тревога, печаль",["اللهم أزل عنَّا همومنا",16,22,"О Аллах, избавь нас от наших забот."]],[10984,3,13,3,"مَهْمُوم | مَهْمُومُون","озабоченный, опечаленный",["لم أنت مهموم يا أخي؟",7,12,"Почему ты опечален, брат мой?"]],[10985,3,13,3,"فِيمَ","о чём? в чём? (في + ما)",["فيم تفكر يا أخي؟",0,3,"О чём ты думаешь, брат мой?"]],[10986,3,13,3,"اِبْتِعَاد","отдаление, удаление",["ابتعاد الطالب عن الترجمة سبب في فهم اللغة",0,6,"Отказ студента от перевода — причина понимания языка."]],[10987,3,13,3,"مُنَازَعَة | مُنَازَعَات","спор, тяжба, распря",["تزيد كل يوم المنزعات بين الإخوة، والسبب الجهل",0,0,"Каждый день распри между братьями растут, а причина — невежество."]],[10988,3,13,3,"اِشْتَغَلَ بِـ - يَشْتَغِلُ - اِشْتِغَال","заниматься, быть занятым (чем-л.) • масдар: занятие, работа",["إشتغل الطالب بالخلافات عن الدراسة",0,5,"Студент занялся спорами вместо учёбы."]],[10989,3,13,3,"أَفَادَ - يُفِيدُ - إِفَادَة","приносить пользу; сообщать • масдар: польза; сообщение",["لن تفيدك الترجمة أيها الطالب. بل ستفسدك",3,8,"Перевод тебе не поможет, студент, а испортит тебя."]],[10990,3,13,3,"اِسْتِشْرَاق","востоковедение, ориентализм",["انتشر الاستشراق بين الأمم الغربية",6,15,"Востоковедение распространилось среди западных народов."]],[10991,3,13,3,"مُسْتَشْرِق | مُسْتَشْرِقُون","востоковед, ориенталист",["هذا العالم الفرنسي مستشرق",19,25,"Этот французский учёный — востоковед."]],[10992,3,13,3,"عَهْد | عُهُود","эпоха, время; договор, обещание",["نسأل الله أن تعود الأمة الإسلامية إلى عهود القوة",38,42,"Просим Аллаха вернуть исламскую умму во времена силы."]],[10993,3,13,3,"اِتَّحَدَ - يَتَّحِدُ - اِتِّحَاد","объединяться • масдар: объединение, союз",["اتحدت دول الكفار ضد الإسلام",0,5,"Страны неверных объединились против ислама."]],[10994,3,13,3,"اِسْتَعَانَ بِـ - يَسْتَعِينُ - اِسْتِعَانَة","прибегать к помощи, обращаться за помощью • масдар: обращение за помощью",["\"إذا استعنت فاستعن بالله\"",0,0,"«Если просишь помощи, проси её у Аллаха»."]],[10995,3,13,3,"عَلَى رَأْسِهَا","во главе которых, главная из них",["هناك أسباب كثيرة لضعف المسلمين على رأسها التفرق",31,40,"Причин слабости мусульман много, главная из них — разобщённость."]],[10996,3,13,3,"عَهْد القُوَّة","эпоха силы",["اللهم أرجعنا إلى عهد القوة",17,26,"О Аллах, верни нас в эпоху силы."]],[10997,3,13,3,"بَدَأَتْ عَلَامَاتُهُ","начали появляться его признаки",["بدأت علامات الساعة في الظهور منذ ظهور النبي",0,0,"Признаки Часа начали появляться с появлением Пророка."]],[10998,3,13,3,"اِسْتَعْمَرَ - يَسْتَعْمِرُ - اِسْتِعْمَار","колонизировать • масдар: колонизация",null],[10999,3,13,3,"اِسْتَشْرَقَ - يَسْتَشْرِقُ - اِسْتِشْرَاق","заниматься востоковедением • масдар: востоковедение",null],[11000,3,13,4,"اِخْتِصَار","краткость, сокращение",["تكلم يا إسماعيل باختصار عن خطبة أمس",16,23,"Расскажи кратко, Исмаил, о вчерашней проповеди."]],[11001,3,13,4,"مُقَدَّس","святой, священный",["المسجد الأقصى بيت الله المقدس",23,29,"Мечеть аль-Акса — священный дом Аллаха."]],[11002,3,13,4,"مَبْنًى | مَبَانٍ","здание",["يحتاج مركز كلمة إلى مبنى منفصل يضم طلابه",20,24,"Центру «Калима» нужно отдельное здание для студентов."]],[11003,3,13,4,"عُمْلَة | عُمُلَات","валюта",["عملة مصر الجنيه",0,4,"Валюта Египта — фунт."]],[11004,3,13,4,"النِّفْط","нефть",["يكثر النفط في دول العرب",5,10,"В арабских странах много нефти."]],[11005,3,13,4,"نَصْرَانِيّ | نَصَارَى","христианин",["تكثر النصارى في حيّ التبّة",5,12,"В районе ат-Табба много христиан."]],[11006,3,13,4,"أَنْتَجَ - يُنْتِجُ - إِنْتَاج","производить • масдар: производство",["كانت مصر تنتج الغاز والآن تستورده من الخارج.",9,13,"Египет производил газ, а теперь импортирует его."]],[11007,3,13,4,"أَمِنَ عَلَى - يَأْمَنُ - أَمْن","быть в безопасности, доверять • масдар: безопасность",["لا أشعر بالأمن هذه الأيام.",8,14,"Я не чувствую безопасности в эти дни."]],[11008,3,13,4,"سَرَقَ - يَسْرِقُ - سَرِقَة","красть • масдар: кража",["سرق السارق الهاتف من جيبي و أنا في الحافلة",0,3,"Вор украл телефон у меня из кармана, когда я был в автобусе."]],[11009,3,13,4,"سَارِق | سَارِقُون، سُرَّاق","вор",["كثر السارقون هذه الأيام",4,12,"В эти дни стало много воров."]],[11010,3,13,4,"أَخَافَ - يُخِيفُ - إِخَافَة","пугать • масдар: запугивание",["أخافني ما حدث في رابعة من قتل و إصابات",0,6,"Меня напугало то, что случилось на Рабаа: убийства и ранения."]],[11011,3,13,4,"اِطْمَأَنَّ عَلَى - يَطْمَئِنُّ - اِطْمِئْنَان","успокоиться, быть уверенным (в) • масдар: спокойствие",["اطمئنَّ يا بنيّ و لا تخف",0,7,"Успокойся, сынок, и не бойся."]],[11012,3,13,4,"قَبَضَ عَلَى - يَقْبِضُ - قَبْض","арестовывать, хватать (кого-л.) • масдар: арест; получение",["قبضت الشرطة على السُرَّاق",0,4,"Полиция арестовала воров."]],[11013,3,13,4,"جَنَى - يَجْنِي - جِنَايَة، جَنْي","совершать преступление; собирать (плоды) • масдар: преступление; сбор урожая",["ماذا جنى محمد مرسي ليُسْجنَ؟!",5,8,"Что совершил Мухаммад Мурси, чтобы его посадили?!"]],[11014,3,13,4,"الجَانِي | جُنَاة","преступник, виновный",["قبضت الشرطة على الجناة سريعا",16,22,"Полиция быстро схватила преступников."]],[11015,3,13,4,"قَارَنَ بَيْنَ - يُقَارِنُ - مُقَارَنَة","сравнивать • масдар: сравнение",["أَجْرِ مقارنة بين مصر و روسيا من حيث الاقتصاد",7,13,"Проведи сравнение между Египтом и Россией с точки зрения экономики."]],[11016,3,13,4,"العَدْوَى","инфекция, заражение",["افتح النافذة كي لا تنتقل عدوى الزكام بين الطلاب",25,29,"Открой окно, чтобы насморк не передавался между студентами."]],[11017,3,13,4,"اِغْتَصَبَ - يَغْتَصِبُ - اِغْتِصَاب","захватывать силой, отнимать; насиловать • масдар: захват; изнасилование",["اغتصب اللص الأرض من صاحبها.",0,5,"Вор силой захватил землю у её хозяина."]],[11018,3,13,4,"أَدَامَ - يُدِيمُ - إِدَامَة","продлевать, сохранять • масдар: продление",["أدام الله علينا نعمة الإسلام",0,4,"Да сохранит Аллах нам благо ислама."]],[11019,3,13,4,"مَكَان مُقَدَّس","святое место",["المسجد الأقصى مكان مقدّس",14,24,"Мечеть аль-Акса — святое место."]],[11020,3,13,4,"مُقَارَنَةً بِـ","по сравнению с",["مصر فقيرة مقارنة بالسعودية و غنية مقارنة بالصومال",10,16,"Египет беден по сравнению с Саудовской Аравией и богат по сравнению с Сомали."]],[11021,3,13,4,"لَا يُسَاوِي شَيْئًا","ничего не стоит",["المال لا يساوي شيئا دون صحة",6,19,"Деньги ничего не стоят без здоровья."]],[11022,3,13,4,"اِخْتَصَرَ - يَخْتَصِرُ - اِخْتِصَار","сокращать, резюмировать • масдар: сокращение, краткость",null],[11023,3,14,1,"الحَرْب | حُرُوب","война",["العالم الإسلامي مليء بالحروب الأهليَّة",21,28,"Исламский мир полон гражданских войн."]],[11024,3,14,1,"إِعْلَام","СМИ, информирование",["وسائل الإعلام تشجع على الجريمة",6,13,"СМИ поощряют преступность."]],[11025,3,14,1,"أَضْعَفَ - يُضْعِفُ - إِضْعَاف","ослаблять • масдар: ослабление",["التفرُّق يضعف المسلمين",9,13,"Разобщённость ослабляет мусульман."]],[11026,3,14,1,"ذَاقَ - يَذُوقُ - ذَوْق","пробовать на вкус; испытывать • масдар: вкус",["ذقت الفول فوجدته لذيذا",0,0,"Я попробовал фуль и нашёл его вкусным."]],[11027,3,14,1,"تَمَتَّعَ بِـ - يَتَمَتَّعُ - تَمَتُّع","наслаждаться, пользоваться (чем-л.) • масдар: наслаждение",["أتمتع بالقراءة خاصة قبل النوم",0,5,"Я наслаждаюсь чтением, особенно перед сном."]],[11028,3,14,1,"مُحَاوَلَة | مُحَاوَلَات","попытка",["هناك محاولات للصلح بين الدولة و الجبهة",5,12,"Есть попытки примирения между государством и фронтом."]],[11029,3,14,1,"عُصْبَة | عُصَب","группа, банда",["هناك عصبة من المجرمين يقومون بالسرقة في حينا",5,9,"В нашем районе банда преступников, которые воруют."]],[11030,3,14,1,"تَبِعَ - يَتْبَعُ - تَبَع","следовать (за) • масдар: следование",["من تبع النبي صلى الله عليه وسلم دخل الجنة",3,6,"Кто последовал за Пророком ﷺ, войдёт в Рай."]],[11031,3,14,1,"مُنَظَّمَة | مُنَظَّمَات","организация",["هناك منظمات كثيرة لحرب الإسلام",5,11,"Есть много организаций, борющихся с исламом."]],[11032,3,14,1,"عُقُوبَة | عُقُوبَات","наказание",["عقوبة السارق قطع يده",0,5,"Наказание вора — отсечение руки."]],[11033,3,14,1,"مُعْتَدِيَة","агрессивная, посягающая",["إعتدى الغرب على حقوق المسلمين",0,0,"Запад посягнул на права мусульман."]],[11034,3,14,1,"أَوْقَفَ - يُوقِفُ - إِيقَاف","останавливать, прекращать • масдар: остановка",["أوقف المركز الدراسة أسبوعا",0,4,"Центр приостановил занятия на неделю."]],[11035,3,14,1,"اِتَّهَمَ - يَتَّهِمُ - اِتِّهَام","обвинять • масдар: обвинение",["اتهم الطالب صديقه بسرقة هاتفه",0,4,"Студент обвинил друга в краже своего телефона."]],[11036,3,14,1,"قَرَار | قَرَارَات","решение, постановление",["أصدر المدير قرار بزيادة مستوى",12,16,"Директор издал решение о повышении уровня."]],[11037,3,14,1,"نَفَّذَ - يُنَفِّذُ - تَنْفِيذ","исполнять, осуществлять • масдар: исполнение",["ينفذ المسلمون أوامر الله",0,4,"Мусульмане исполняют повеления Аллаха."]],[11038,3,14,1,"خَصَّ - يَخُصُّ - خُصُوص","касаться, относиться (к); выделять • масдар: особенность",["هذا الأمر لا يخصّنى",13,19,"Это дело меня не касается."]],[11039,3,14,1,"حَلَّ مَحَلَّهُ","занял его место",["الزوجة الثانية حلت محل الأولى",0,0,"Вторая жена заняла место первой."]],[11040,3,14,1,"اِعْتَدَى عَلَى - يَعْتَدِي - اِعْتِدَاء","нападать, посягать (на) • масдар: нападение, агрессия",null],[11041,3,14,2,"شَغَلَ - يَشْغَلُ - شُغْل","занимать, отвлекать • масдар: занятие, работа",["شغلني ولدي المريض عن العمل أمس",0,5,"Вчера больной сын отвлёк меня от работы."]],[11042,3,14,2,"بَال","мысль, ум, душа",["أرى بالك مشغولا",4,8,"Я вижу, ты чем-то озабочен."]],[11043,3,14,2,"قَانُون | قَوَانِين","закон",["أصدرت الحكومة قانونا يمنع المظاهرات",14,20,"Правительство издало закон, запрещающий демонстрации."]],[11044,3,14,2,"رَادِع","сдерживающий, устрашающий",["قوانين البشر ليست رادعة",18,23,"Человеческие законы не сдерживают."]],[11045,3,14,2,"اِرْتَكَبَ - يَرْتَكِبُ - اِرْتِكَاب","совершать (проступок, преступление) • масдар: совершение",["ماذا ارتكبت حتى تعاقبني أيها المدير؟!",5,11,"Что я совершил, чтобы вы меня наказывали, господин директор?!"]],[11046,3,14,2,"حَدّ | حُدُود","предел, граница; шариатское наказание (хадд)",["من حدود الله قطع يد السارق",3,7,"Из установленных Аллахом наказаний — отсечение руки вора."]],[11047,3,14,2,"حِمَايَة","защита, охрана",["وظيفة الجيش حماية مواطنيه وليس قتلهم.",12,17,"Задача армии — защищать граждан, а не убивать их."]],[11048,3,14,2,"القِصَاص","возмездие (кисас)",["من قتل مؤمنا متعمدا فعليه القصاص",26,32,"Кто убил верующего умышленно, тому возмездие."]],[11049,3,14,2,"أُولُو","обладатели (ед. ذو)",["أولو الأموال عليهم حق للفقراء",0,4,"У обладателей богатства есть обязанность перед бедными."]],[11050,3,14,2,"لُبّ | أَلْبَاب","разум, суть",["اتقوا الله يا أولي الألباب",19,26,"Бойтесь Аллаха, обладатели разума!"]],[11051,3,14,2,"أَيَّدَ - يُؤَيِّدُ - تَأْيِيد","поддерживать, подтверждать • масдар: поддержка",["أيّد كلامك دائما بالدليل",0,4,"Всегда подкрепляй свои слова доказательством."]],[11052,3,14,2,"كُلَّمَا","всякий раз, когда",["كلما دخلت المركز وجدت الطلاب يلعبون",0,4,"Всякий раз, входя в центр, я видел, что студенты играют."]],[11053,3,14,2,"العِقَاب","наказание",["سيعاقب الله الكفار يوم القيامة أشد العقاب",35,41,"Аллах накажет неверных в Судный день жесточайшим наказанием."]],[11054,3,14,2,"الجُوع","голод",["أشعر بالجوع. هيا بنا إلى المطعم",5,11,"Я голоден. Пойдём в ресторан."]],[11055,3,14,2,"أَطْعَمَ - يُطْعِمُ - إِطْعَام","кормить • масдар: кормление",["اللهم أطعم من أطعمنا",6,10,"О Аллах, накорми того, кто накормил нас."]],[11056,3,14,2,"تَعَاوَنَ مَعَ ... عَلَى - يَتَعَاوَنُ - تَعَاوُن","сотрудничать (с … в …) • масдар: сотрудничество",["وتعاونوا على البر و التقوى",0,8,"«Помогайте друг другу в благочестии и богобоязненности»."]],[11057,3,14,2,"يَشْغَلُ بَالِي","занимает мои мысли",["هناك بعض الأسئلة تشغل بالي يا أستاذ",17,26,"Учитель, некоторые вопросы не дают мне покоя."]],[11058,3,14,2,"لَعَلَّكُمْ تَتَّقُونَ","быть может, вы станете богобоязненными",["كُتب عليكم الصيام كما كُتب على الذين من قبلكم لعلكم تتقون.",46,57,"«Предписан вам пост, как он был предписан тем, кто был до вас, — быть может, вы станете богобоязненными»."]],[11059,3,14,2,"رَدَعَ - يَرْدَعُ - رَدْع","сдерживать, удерживать • масдар: сдерживание",null],[11060,3,14,2,"حَمَى - يَحْمِي - حِمَايَة","защищать, охранять • масдар: защита",null],[11061,3,14,2,"أَجَاعَ - يُجِيعُ - إِجَاعَة","морить голодом • масдар: голод",null],[11062,3,14,3,"لَبَسَ - يَلْبِسُ - لَبْس","смешивать, путать • масдар: смешение, путаница",["يلبس الشيطان الحق بالباطل للإنسان",0,4,"Шайтан смешивает для человека истину с ложью."]],[11063,3,14,3,"مُهْتَدُونَ","следующие прямым путём (ед. مهتدٍ)",["اللهم اجعلنا هداة مهتدين",0,0,"О Аллах, сделай нас ведущими и ведомыми прямым путём."]],[11064,3,14,3,"تَوَفَّرَ - يَتَوَفَّرُ - تَوَفُّر","иметься в наличии, быть доступным • масдар: наличие",["المركز يوفر لنا أحسن الأساتذة",0,0,"Центр обеспечивает нас лучшими преподавателями."]],[11065,3,14,3,"حَرَمَ مِنْ - يَحْرِمُ - حِرْمَان","лишать (чего-л.) • масдар: лишение",["حرَم الأب ابنه من المصروف اليومي",0,0,"Отец лишил сына ежедневных карманных денег."]],[11066,3,14,3,"شَقِيَ - يَشْقَى - شَقَاء","быть несчастным • масдар: несчастье",["اللهم اجعلني سعيداً لا شقيا",23,27,"О Аллах, сделай меня счастливым, а не несчастным."]],[11067,3,14,3,"سِرْب | أَسْرَاب","стая; душа (перен.); путь",["يضيق سرب الكافر عند سماعه القرآن",5,8,"Неверному становится тесно на душе, когда он слышит Коран."]],[11068,3,14,3,"مُعَافًى","здоровый, исцелённый",["من كان معافىً في جسده فليحمد الله",7,13,"Кто здоров телом, пусть восхвалит Аллаха."]],[11069,3,14,3,"قُوت | أَقْوَات","пропитание, пища",["المسكين هو الذي لا يجد ما يكفي لقوت يومه",31,35,"Бедняк — тот, у кого нет достаточного пропитания на день."]],[11070,3,14,3,"كَأَنَّمَا","словно, как будто",["الامتحان كأنما هو الموت",9,14,"Экзамен — словно смерть."]],[11071,3,14,3,"حَازَ - يَحُوزُ - حِيَازَة","приобретать, овладевать • масдар: владение, обладание",["حاز صديقي جائزة من المركز",0,3,"Мой друг получил приз от центра."]],[11072,3,14,3,"حُذْفُور، حِذْفَار | حَذَافِير","край, сторона (мн. حذافير — «целиком»)",["للغرفة أربعة حذافير",13,19,"У комнаты четыре стороны."]],[11073,3,14,3,"الاِسْتِقْرَار","стабильность",["اللهم أرزق بلاد المسلمين الاستقرار",25,34,"О Аллах, даруй странам мусульман стабильность."]],[11074,3,14,3,"عَمَلِيَّة | عَمَلِيَّات","операция; процесс",["أجرى الطبيب عملية جراحية ناجحة.",12,17,"Врач провёл успешную операцию."]],[11075,3,14,3,"تَوَقَّفَ - يَتَوَقَّفُ - تَوَقُّف","останавливаться, прекращаться • масдар: остановка",["توقف قطار التنمية المصري بعد سقوط مرسي",0,4,"Поезд египетского развития остановился после падения Мурси."]],[11076,3,14,3,"مَشْرُوع | مَشَارِيع، مَشْرُوعَات","проект",["هل فكرت في هذا المشروع قبل البداية فيه؟",15,22,"Ты обдумал этот проект, прежде чем начать?"]],[11077,3,14,3,"طَاقَة | طَاقَات","энергия; сила, возможность",["لا طاقة لي بهذا العمل",3,7,"Мне не под силу эта работа."]],[11078,3,14,3,"خَرِيطَة | خَرَائِط","карта",["رسم الأستاذ خريطة العالم على السبورة",12,17,"Преподаватель нарисовал на доске карту мира."]],[11079,3,14,3,"السِّلَاح | أَسْلِحَة","оружие",["الجيش يحمي الوطن بالسلاح.",17,24,"Армия защищает родину оружием."]],[11080,3,14,3,"أَثَارَ - يُثِيرُ - إِثَارَة","возбуждать, вызывать, поднимать • масдар: возбуждение",["أمريكا تثير الخلافات بين الدول الإسلامية",7,11,"Америка разжигает разногласия между исламскими странами."]],[11081,3,14,3,"آمِن فِي سِرْبِهِ","в безопасности в своём доме (среди своих)",["يتمنى كل إنسان أن يعيش آمنا في سربه",23,35,"Каждый человек мечтает жить в безопасности среди своих."]],[11082,3,14,3,"مُعَافًى فِي جَسَدِهِ","здоров телом",["خرج المجاهد من الحرب معافي في جسده",21,34,"Воин вышел из войны здоровым телом."]],[11083,3,14,3,"حِيزَتْ لَهُ الدُّنْيَا بِحَذَافِيرِهَا","ему будто достался весь мир целиком",["حيزت للصدِّيق الدنيا بحذافيرها",0,0,"Ас-Сыддику будто достался весь мир целиком."]],[11084,3,14,3,"تَنْشَطُ التَّنْمِيَة","развитие активизируется",["متى سينشط قطار التنمية المصري",0,0,"Когда поезд египетского развития снова поедет?"]],[11085,3,14,3,"مَا ... إِلَّا","только, не … кроме",["ما قابلت الأستاذ إلا مبتسما",0,0,"Я всегда встречал преподавателя только улыбающимся."]],[11086,3,14,3,"اِهْتَدَى - يَهْتَدِي - اِهْتِدَاء","следовать прямым путём • масдар: следование истинному пути",null],[11087,3,14,3,"اِسْتَقَرَّ - يَسْتَقِرُّ - اِسْتِقْرَار","устанавливаться, поселяться • масдар: стабильность",null],[11088,3,15,1,"دَفَنَ - يَدْفِنُ - دَفْن","хоронить, закапывать • масдар: погребение, захоронение",["من السنة السرعة في دفن الموتى",19,22,"Сунна — быстро хоронить умерших."]],[11089,3,15,1,"مُصَاب","поражённый (болезнью), раненый",["عمّي مصاب بالسرطان. وهو الآن في المستشفى",5,9,"Мой дядя болен раком. Он сейчас в больнице."]],[11090,3,15,1,"السَّرَطَان","рак (болезнь)",["السرطان مرض خطير. لا علاج له إلى الآن",0,7,"Рак — опасная болезнь. От неё до сих пор нет лекарства."]],[11091,3,15,1,"حَيَّرَ - يُحَيِّرُ - تَحْيِير","ставить в тупик, озадачивать • масдар: замешательство",["هذه المسألة حيَّرت العلماء",12,18,"Этот вопрос озадачил учёных."]],[11092,3,15,1,"ذَكَرَ أَنَّ - يَذْكُرُ - ذِكْر","упоминать, сообщать; поминать • масдар: упоминание; поминание",["ذكرت الصحف أنَّ ابن لادن قُتِل",0,4,"Газеты сообщили, что бен Ладен убит."]],[11093,3,15,1,"سَمَحَ بِـ - يَسْمَحُ - سَمَاح","разрешать, позволять • масдар: разрешение",["سمح الأستاذ للطالب بالخروج",0,3,"Преподаватель разрешил студенту выйти."]],[11094,3,15,2,"التُّرْبَة | تُرَب","почва, земля",["سيناء تربة صالحة للزراعة",6,10,"Синай — почва, пригодная для земледелия."]],[11095,3,15,2,"رَائِحَة | رَوَائِح","запах",["أشم رائئحة غير طيبة",0,0,"Я чувствую неприятный запах."]],[11096,3,15,2,"أَحْرَقَ - يُحْرِقُ - إِحْرَاق","сжигать • масдар: сжигание",["سيحرق الله الكافرين بالنار",0,5,"Аллах сожжёт неверных в Огне."]],[11097,3,15,2,"اِلْتَهَبَ - يَلْتَهِبُ - اِلْتِهَاب","воспаляться; воспламеняться • масдар: воспаление",["التهبت صدور المدخنين بسبب التدخين",0,6,"Лёгкие курильщиков воспалились из-за курения."]],[11098,3,15,2,"رِئَة | رِئَات","лёгкое",["للإنسان رئتان",8,13,"У человека два лёгких."]],[11099,3,15,2,"عَذْب","пресный, сладкий (о воде)",["هذا الماء عذب.",10,13,"Эта вода пресная."]],[11100,3,15,2,"مَادَّة | مَوَادّ","вещество, материал; предмет (учебный)",["الأكسجين مادة ضرورية للنَّفَسِ",9,13,"Кислород — вещество, необходимое для дыхания."]],[11101,3,15,2,"بِئْر | آبَار","колодец",["حَفْرَ بئر يكلف أربعين ألف جنيه",7,10,"Вырыть колодец стоит сорок тысяч фунтов."]],[11102,3,15,2,"أَتْلَفَ - يُتْلِفُ - إِتْلَاف","портить, повреждать • масдар: повреждение, порча",["أتلفت ابنتي حاسوبي",0,5,"Моя дочь испортила мой компьютер."]],[11103,3,15,2,"سَبَّبَ - يُسَبِّبُ - تَسْبِيب","вызывать, быть причиной • масдар: причинение",["التدخين يسبب الموت",8,12,"Курение вызывает смерть."]],[11104,3,15,2,"جِهَاز | أَجْهِزَة","аппарат, прибор, устройство",["جهاز الحاسوب فسدو السبب ابنتي",0,4,"Компьютер сломался, и причина — моя дочь."]],[11105,3,15,2,"المَوَادّ الكِيمْيَائِيَّة","химические вещества",["في الفواكه كثير من المواد الكيمائية",0,0,"Во фруктах много химических веществ."]],[11106,3,15,2,"مِيَاه الصَّرْف الصِّحِّيّ","сточные воды, канализация",["مياه الصرف الصحي فوق الأرض في الحي العاشر",0,16,"В Десятом районе сточные воды текут по земле."]],[11107,3,15,2,"ضَعْف السَّمْع","ослабление слуха",["أشعر بضعف في السمع",0,0,"Я чувствую ослабление слуха."]],[11108,3,15,2,"قَلَّلَ - يُقَلِّلُ - تَقْلِيل","уменьшать, сокращать • масдар: уменьшение",null],[11109,3,15,3,"جَوْلَة | جَوْلَات","экскурсия, тур, раунд",["قام الطلاب بجولة في مدينة نصر",11,16,"Студенты совершили экскурсию по Мадинат Наср."]],[11110,3,15,3,"أَلْقَى - يُلْقِي - إِلْقَاء","бросать; произносить (речь) • масдар: бросание; произнесение",["يلقى المصريون النفايات خارج الحاويات",0,4,"Египтяне бросают мусор мимо контейнеров."]],[11111,3,15,3,"التَّصَحُّر","опустынивание",["بدأ التصحر يأكل التربة المصرية",4,10,"Опустынивание начало «поедать» египетскую почву."]],[11112,3,15,3,"نَادِرَة","редкая",["الزلازل نادرة الحدوث في مصر",8,13,"Землетрясения в Египте случаются редко."]],[11113,3,15,3,"اِنْقَرَضَ - يَنْقَرِضُ - اِنْقِرَاض","вымирать • масдар: вымирание",["انقرض هذا النوع من الحيوانات",0,5,"Этот вид животных вымер."]],[11114,3,15,3,"خَالِيَة","свободная (от), пустая",["نريد بيئة خالية من الكذب و الخيانة",10,15,"Мы хотим среду, свободную от лжи и предательства."]],[11115,3,15,3,"عَوْن","помощь",["والله في عون العبد ما كان العبد في عون أخيه",9,12,"Аллах помогает рабу, пока раб помогает своему брату."]],[11116,3,15,3,"إِيقَاف التَّصَحُّر","остановка опустынивания",["اللهم أوقف التصحر في التربة المصرية",0,0,"О Аллах, останови опустынивание египетской почвы."]],[11117,3,15,3,"الحَيَوَانَات النَّادِرَة","редкие животные",["الدب الصيني (الباندا) من الحيوانات النادرة الآن.",25,42,"Китайский медведь (панда) сейчас — редкое животное."]],[11118,3,15,3,"رِسَالَتِي","моя миссия",["رسالة المركز هو الوصول باللغة العربية إلى جميع أنحاء العالم",0,0,"Миссия центра — донести арабский язык до всех уголков мира."]],[11119,3,15,3,"عَوْن اللهِ","помощь Аллаха",["والله في عون العبد ما كان العبد في عون أخيه",0,0,"Аллах помогает рабу, пока раб помогает своему брату."]],[11120,3,15,3,"جَالَ - يَجُولُ - جَوْلَة، جَوَلَان","обходить, кружить • масдар: обход, тур",null],[11121,3,15,3,"تَصَحَّرَ - يَتَصَحَّرُ - تَصَحُّر","опустыниваться • масдар: опустынивание",null],[11122,3,15,3,"نَدَرَ - يَنْدُرُ - نُدْرَة","быть редким • масдар: редкость",null],[11123,3,15,3,"خَلَا مِنْ - يَخْلُو - خُلُوّ","быть свободным, пустым (от) • масдар: пустота, свобода (от)",null],[11124,3,15,4,"المُحَافَظَة عَلَى","сохранение, охрана",["نرجو المحافظة على نظافة الفصل",5,17,"Просим соблюдать чистоту в классе."]],[11125,3,15,4,"أَعْظَم","величайший",["أعظم آية في القرآن آية الكرسي",0,4,"Величайший аят в Коране — аят аль-Курси."]],[11126,3,15,4,"بَانَ - يَبِينُ - بَيَان","становиться ясным, проявляться • масдар: разъяснение, заявление",["قام الأستاذ ببيان أسباب ضعف المسلمين",12,17,"Преподаватель разъяснил причины слабости мусульман."]],[11127,3,15,4,"خَطَر | أَخْطَار","опасность",["التفرّق خطر عظيم",8,11,"Разобщённость — огромная опасность."]],[11128,3,15,4,"رَاقَبَ - يُرَاقِبُ - مُرَاقَبَة","наблюдать, следить, контролировать • масдар: наблюдение, контроль",["يراقب الله العبد في جميع حركاته و سكناته",0,5,"Аллах наблюдает за рабом во всех его движениях и покое."]],[11129,3,15,4,"غَرَسَ - يَغْرِسُ - غَرْس","сажать (растения) • масдар: посадка",["قام الأستاذ بغرس بعض الأشجار حول المركز",12,16,"Преподаватель посадил несколько деревьев вокруг центра."]],[11130,3,15,4,"فَسِيلَة | فَسَائِل","отросток (пальмы), саженец",["اعتنى الفلاح بفسائله حتى صارت نخلا",13,20,"Крестьянин ухаживал за саженцами, пока они не стали пальмами."]],[11131,3,15,4,"عَدَم","отсутствие, «не-» (عدم + масдар)",["أرجو عدم اللعب في الدرس",5,8,"Прошу не играть на уроке."]],[11132,3,15,4,"اِسْتَهْلَكَ - يَسْتَهْلِكُ - اِسْتِهْلَاك","потреблять, расходовать • масдар: потребление",["تستهلك سيارتي 30 لتراً وقوداً أسبوعيا",0,6,"Моя машина расходует 30 литров топлива в неделю."]],[11133,3,15,4,"بِخَاصَّةٍ","особенно",["أحب الناس وبخاصة الفقراء",10,16,"Я люблю людей, особенно бедных."]],[11134,3,15,4,"أَزْمَة | أَزَمَات","кризис",["تعيش مصر هذه الأيام أزمة اقتصادية",20,24,"Египет сейчас переживает экономический кризис."]],[11135,3,15,4,"قِلَّة","недостаток, малое количество",["تشكو الصومال من قلة المطر",16,19,"Сомали страдает от нехватки дождей."]],[11136,3,15,4,"عَلَيْكَ أَنْ","тебе следует, ты должен",["عليك أن تدرس جيداً لتنجح",0,7,"Тебе следует хорошо учиться, чтобы сдать."]],[11137,3,15,4,"غَرْس الأَشْجَار","посадка деревьев",["من السنة غرس الأشجار",9,20,"Сажать деревья — это сунна."]],[11138,3,15,4,"مِنَ الخَطَأِ","ошибочно, неправильно",["من الخطأ الإسراف في استهلاك الماء",0,8,"Неправильно расточительно расходовать воду."]],[11139,3,15,4,"يَجْعَلُهَا خَضْرَاءَ","делает её зелёной",["يجعل الفلاح التربة خضراء بزراعتها",0,0,"Крестьянин делает почву зелёной, засевая её."]],[11140,3,15,4,"مِنْ أَفْضَلِ الطُّرُقِ لِـ","один из лучших способов для…",["الحجامة من أفضل الطرق للعلاج",8,21,"Хиджама — один из лучших способов лечения."]],[11141,3,15,4,"عَدَم + مَصْدَر","«не-», отказ от … (عدم + масдар)",["عدم التبكير في النوم يؤدي إلى ضياع الفجر",0,0,"Непривычка рано ложиться спать ведёт к пропуску фаджра."]],[11142,3,15,4,"بَلَد مَا","некая страна, одна страна",["في بلد ما سافرت إليه وجدت الناس يأكلون النمل.",3,9,"В одной стране, куда я ездил, люди ели муравьёв."]],[11143,3,16,1,"فَاتُورَة | فَوَاتِير","счёт, квитанция",["هل دفعت فاتورة الكهرباء؟",8,14,"Ты оплатил счёт за электричество?"]],[11144,3,16,1,"تَضَاعَفَ - يَتَضَاعَفُ - تَضَاعُف","удваиваться, умножаться • масдар: удвоение",["تتضاعف أعداد الطلاب في مركز كلمة يوما بعد يوم",0,6,"Число студентов в центре «Калима» растёт с каждым днём."]],[11145,3,16,1,"أَضَاءَ - يُضِيءُ - إِضَاءَة","освещать, светить • масдар: освещение",["يضيء المصباح الغرفة",0,4,"Лампа освещает комнату."]],[11146,3,16,1,"مِذْيَاع","радио, радиоприёмник",["قديما قبل التلفاز كنا نعرف الأخبار بالمذياع",35,43,"В старину, до телевизора, мы узнавали новости по радио."]],[11147,3,16,1,"خَلَّاط","блендер",["أعد عصير البرتقال عن طريق الخلاط",26,32,"Я делаю апельсиновый сок блендером."]],[11148,3,16,1,"مِكْنَسَة","пылесос; метла",["أكنس شقتي عن طريق المكنسة",18,25,"Я убираю квартиру пылесосом."]],[11149,3,16,1,"بَذَّرَ - يُبَذِّرُ - تَبْذِير","расточать, транжирить • масдар: расточительство",["إن المبذرين كانوا إخوان الشياطين",0,0,"Поистине, расточители — братья шайтанов."]],[11150,3,16,1,"مِيزَانِيَّة","бюджет",["أفسد الأطفال ميزانية البيت بسبب تبذيرهم",13,20,"Дети испортили семейный бюджет своей расточительностью."]],[11151,3,16,1,"مُسْتَجِيب","откликающийся, послушный",["لا مستجيب لما يقول الخطيب",3,9,"Никто не откликается на слова проповедника."]],[11152,3,16,1,"لَا عَجَبَ","неудивительно",["لا عجب في حب جميع المسلمين للغة العربية، فهي لغة القرآن",0,6,"Неудивительно, что все мусульмане любят арабский язык — это язык Корана."]],[11153,3,16,1,"مِيزَانِيَّة البَيْت","семейный бюджет",["أفسد الأولاد ميزانية البيت بسبب تبذيرهم",13,26,"Дети испортили семейный бюджет своей расточительностью."]],[11154,3,16,1,"لَا مُسْتَجِيبَ","никто не откликается",["لا مستجيب لما يقول الأبوان",0,9,"Никто не откликается на слова родителей."]],[11155,3,16,2,"عَدَّ - يَعُدُّ - عَدّ","считается • масдар: счёт, подсчёт",["يعد الفول الوجبة الشعبية المصرية",0,3,"Фуль считается народным египетским блюдом."]],[11156,3,16,2,"شِرْيَان | شَرَايِين","1) артерия 2) основа, жизненная артерия",["يجري الدم في الشرايين",13,21,"Кровь течёт по артериям."]],[11157,3,16,2,"شَاحِنَة | شَاحِنَات","грузовик",["تنقل الفواكه إلى المدن عن طريق شاحنات",31,37,"Фрукты доставляют в города грузовиками."]],[11158,3,16,2,"وَقُود","топливо",["تستهلك سيارتي وقوداً كثيرًا",14,20,"Моя машина потребляет много топлива."]],[11159,3,16,2,"مَنْسُوج | مَنْسُوجَات","ткань, текстиль",["جميع المنسوجات تحتاج إلى النفط في التصنيع",5,14,"Для производства всех тканей нужна нефть."]],[11160,3,16,2,"تَجْمِيل","украшение, косметика; приукрашивание",["تجميل وجوه الرجال تكون باللحى",0,5,"Мужские лица украшают бороды."]],[11161,3,16,2,"مُنَظِّف | مُنَظِّفَات","моющее средство",["تعتمد المنظفات في تصنيعها على المواد الكيميائية",6,14,"Моющие средства производятся на основе химических веществ."]],[11162,3,16,2,"سَمَاد | أَسْمِدَة","удобрение",["الأسمدة الطبيعية تقوي الأرض",0,7,"Природные удобрения укрепляют землю."]],[11163,3,16,2,"مُنْتَج | مُنْتَجَات","продукт, изделие",["الزبادي من منتجات الألبان",11,17,"Йогурт — один из молочных продуктов."]],[11164,3,16,2,"بَدِيل | بَدَائِل","замена, альтернатива",["لا أجد بديلاً عن مركز كلمة",7,13,"Я не нахожу замены центру «Калима»."]],[11165,3,16,2,"بَدَا - يَبْدُو - بُدُوّ","казаться, показываться • масдар: появление",["بدت الحافلة من بعيد",0,0,"Вдали показался автобус."]],[11166,3,16,2,"اِسْتَغْرَقَ - يَسْتَغْرِقُ - اِسْتِغْرَاق","занимать (время), продолжаться • масдар: продолжительность",["استغرق هذا المعجم أشهرًا",0,6,"Этот словарь занял несколько месяцев."]],[11167,3,16,2,"اِحْتِيَاط","запас, резерв",["عند انقطاع المياه لم أجد ماء احتياطيًا",0,0,"Когда отключили воду, я не нашёл запасной воды."]],[11168,3,16,2,"بِرْمِيل | بَرَامِيل","бочка, баррель",["كم لتراً يحمل البرميل من النفط",14,21,"Сколько литров нефти в баррели?"]],[11169,3,16,2,"مَحْدُود","ограниченный",["عليك بسرعة شراء المعجم لأن عدده محدود في المركز.",32,37,"Поспеши купить словарь — их количество в центре ограничено."]],[11170,3,16,2,"ثَرْوَة طَبِيعِيَّة","природное богатство",["النفط ثروة طبيعية يملكها المسلمون لكن لا يعرفون قيمتها",6,17,"Нефть — природное богатство, которым владеют мусульмане, но не знают его цену."]],[11171,3,16,2,"الذَّهَب الأَسْوَد","чёрное золото",["النفط هو الذهب الأسود لدخوله في معظم الصناعات",9,21,"Нефть — чёрное золото, так как используется в большинстве отраслей."]],[11172,3,16,2,"شِرْيَان الحَيَاة","артерия жизни",["الأمانة هي شريان حياة المجتمع. فإذا فقدت فسد المجتمع",11,21,"Честность — жизненная артерия общества: если её утратить, общество испортится."]],[11173,3,16,2,"مُسْتَحْضَرَات التَّجْمِيل","косметические средства",["كل مستحضرات التجميل تنتج من النفط",3,19,"Вся косметика производится из нефти."]],[11174,3,16,2,"اِحْتِيَاط النِّفْط","нефтяной резерв",["تعمل دول الغرب على غصب النفط من المسلمين ليكون احتياطا لهم",0,0,"Западные страны стремятся отнять нефть у мусульман, чтобы сделать её своим резервом."]],[11175,3,16,2,"النِّفْطُ مَحْدُود","нефть ограничена (её запасы)",["النفط محدود لذا يجب علينا أن نبحث عن بديل",0,11,"Нефть ограничена, поэтому нам нужно искать замену."]],[11176,3,16,2,"نَسَجَ - يَنْسِجُ - نَسْج","ткать • масдар: ткачество",null],[11177,3,16,2,"جَمُلَ - يَجْمُلُ - جَمَال","быть красивым • масдар: красота",null],[11178,3,16,2,"حَدَّ - يَحُدُّ - حَدّ","ограничивать • масдар: ограничение",null],[11179,3,16,3,"تَجَدَّدَ - يَتَجَدَّدُ - تَجَدُّد","обновляться, возобновляться • масдар: обновление",["تجدد انقطاع التيار الكهربائي",0,4,"Отключения электричества возобновились."]],[11180,3,16,3,"قَفَزَ - يَقْفِزُ - قَفْز","прыгать; резко подскочить (о ценах) • масдар: прыжок",["تقفز أسعار المركز سنويًا",0,4,"Цены в центре каждый год подскакивают."]],[11181,3,16,3,"المَعْرُوض","предложение (товар на рынке)",["قلة المعروض من السَّلعة يزيد سعرها",4,11,"Малое предложение товара повышает его цену."]],[11182,3,16,3,"مَحَطَّة | مَحَطَّات","станция; заправка; остановка",["أرى ازدحاما يوميا على محطة الوقود",22,26,"Я каждый день вижу очередь на заправке."]],[11183,3,16,3,"مُنْتِجَة","производящая, производитель",["كن منتجا و لا تكن مستهلكا",0,0,"Будь производителем, а не потребителем."]],[11184,3,16,3,"اِدَّعَى أَنَّ - يَدَّعِي - اِدِّعَاء","утверждать, заявлять (без доказательств) • масдар: претензия, иск",["ادَّعى محمد أن زميله سرق هاتفه",0,6,"Мухаммад заявил, что коллега украл его телефон."]],[11185,3,16,3,"ضَرِيبَة | ضَرَائِب","налог",["الضرائب في الدول الغربية باهظة",0,7,"Налоги в западных странах очень высокие."]],[11186,3,16,3,"صَدَّرَ - يُصَدِّرُ - تَصْدِير","экспортировать • масдар: экспорт",["كانت مصر تصدر القمح للعالم كله",9,13,"Египет экспортировал пшеницу во весь мир."]],[11187,3,16,3,"اِسْتَوْرَدَ - يَسْتَوْرِدُ - اِسْتِيرَاد","импортировать • масдар: импорт",["تستورد مصر كل السلع الآن",0,6,"Сейчас Египет импортирует все товары."]],[11188,3,16,3,"تَجَدُّد الشَّيْء","возобновление чего-л.",["تجددت الخلافات بين المجاهدين",0,0,"Разногласия между воинами возобновились."]],[11189,3,16,3,"قَفَزَ السِّعْرُ","цена подскочила",["قفزت أسعار مركز كلمة من جديد",0,0,"Цены в центре «Калима» снова подскочили."]],[11190,3,16,3,"مِنْ جَدِيدٍ","заново, снова",["عاد الأستاذ محمد أحمد يدرِّس لنا من جديد",33,40,"Учитель Мухаммад Ахмад снова преподаёт у нас."]],[11191,3,16,3,"أَعَانَ - يُعِينُ - إِعَانَة","помогать • масдар: помощь",null],[11192,3,16,3,"عَرَّضَ لِـ - يُعَرِّضُ - تَعْرِيض","подвергать (чему-л.) • масдар: подвержение",["لا تعرِّض حياتك للخطر",3,9,"Не подвергай свою жизнь опасности."]],[11193,3,16,4,"النَّجْم | نُجُوم","звезда",["الصحابة كالنجوم يهتدى بهم المسلمون",8,15,"Сподвижники — как звёзды, по которым мусульмане находят путь."]],[11194,3,16,4,"المَصْدَر | مَصَادِر","источник; масдар (в грамматике)",["الشريعة مصدرها القرآن والسنة",8,14,"Источник шариата — Коран и Сунна."]],[11195,3,16,4,"أَسَاسِيّ","основной",["عملي الأساسي مدِّرس، و الثانوي سائق",5,12,"Моя основная работа — учитель, а дополнительная — водитель."]],[11196,3,16,4,"شُعَاع | أَشِعَّة","луч",["ترسل الشمس أشعتها إضاءة للأرض",11,17,"Солнце посылает свои лучи, освещая землю."]],[11197,3,16,4,"الحَرَارَة","тепло, жара; температура",["أشعر بارتفاع في درجة الحرارة",21,28,"Я чувствую повышение температуры."]],[11198,3,16,4,"اِسْتَفَادَ - يَسْتَفِيدُ - اِسْتِفَادَة","извлекать пользу • масдар: извлечение пользы",["استفاد الطالب من المعلم استفادة",0,6,"Студент получил большую пользу от учителя."]],[11199,3,16,4,"سَخَّنَ - يُسَخِّنُ - تَسْخِين","нагревать • масдар: нагревание",["دور السخان هو تسخين الماء",14,19,"Задача водонагревателя — нагревать воду."]],[11200,3,16,4,"تَدْفِئَة","отопление, обогрев",["قم بتدفئة البيت كي لا يصاب الأطفال بالزكام",3,9,"Обогрей дом, чтобы дети не простудились."]],[11201,3,16,4,"وَلَّدَ - يُوَلِّدُ - تَوْلِيد","производить, генерировать (энергию) • масдар: генерация, выработка",["يعمل أخي في محطة توليد الكهرباء",17,22,"Мой брат работает на электростанции."]],[11202,3,16,4,"خَلِيَّة | خَلَايَا","1) улей 2) клетка (живая) 3) элемент (фотоэлемент)",["النحلة تعيش في الخلية.",15,21,"Пчела живёт в улье."]],[11203,3,16,4,"حَارَّة","жаркая",["الصحراء الغربية تعدُّ من المناطق الحارَة",33,40,"Западная пустыня считается жарким районом."]],[11204,3,16,4,"لَوْح | أَلْوَاح","доска, панель",["يتكون السرير من ألواح خشبية",16,21,"Кровать состоит из деревянных досок."]],[11205,3,16,4,"جَمَّعَ - يُجَمِّعُ - تَجْمِيع","собирать • масдар: сбор",["جمَّع ابن القيم أقوال أهل العلم في تارك الصلاة",0,5,"Ибн аль-Кайим собрал высказывания учёных об оставляющем молитву."]],[11206,3,16,4,"مُشْمِسَة","солнечная",["هذه الشقة مشمسة",10,15,"Эта квартира солнечная."]],[11207,3,16,4,"اِحْتَجَبَ - يَحْتَجِبُ - اِحْتِجَاب","скрываться, прятаться • масдар: сокрытие",["عند كسوف الشمس و احتجابها نصلي صلاة الكسوف",17,25,"Когда солнце затмевается и скрывается, мы совершаем молитву затмения."]],[11208,3,16,4,"اِسْتَمَدَّ - يَسْتَمِدُّ - اِسْتِمْدَاد","черпать, получать (из) • масдар: получение",["نستمد الحرارة من المدفئة",0,5,"Мы получаем тепло от обогревателя."]],[11209,3,16,4,"الفَحْم","уголь",["في مصر نشوي الدجاج على الفحم",23,28,"В Египте мы жарим курицу на углях."]],[11210,3,16,4,"اِسْتِغْلَال","использование, эксплуатация",["قم باستغلال وقتك، ولا تجعله يمًّر سُدَّى",3,11,"Используй своё время и не дай ему пройти впустую."]],[11211,3,16,4,"نَفِدَ - يَنْفَدُ - نَفَاد","заканчиваться, иссякать • масдар: истощение",["نفد صبر الأستاذ فقام بضرب الطالب.",0,3,"Терпение учителя иссякло, и он ударил студента."]],[11212,3,16,4,"بَاقِيَة","вечная, остающаяся",["دولة الإسلام باقية إلى يوم الدين",13,18,"Государство ислама сохранится до Судного дня."]],[11213,3,16,4,"الطَّاقَة الشَّمْسِيَّة","солнечная энергия",["علينا أن نستغل الطاقة الشمسية أحسن استغلال",15,29,"Мы должны наилучшим образом использовать солнечную энергию."]],[11214,3,16,4,"مَصْدَر أَسَاسِيّ","основной источник",["العمل في المركز هو المصدر الأساسي لرزقي",19,33,"Работа в центре — основной источник моего заработка."]],[11215,3,16,4,"مَنَاطِق مُشْمِسَة","солнечные районы",["هناك مناطق مشمسة و أخرى مظلمة",5,16,"Есть солнечные районы и тёмные."]],[11216,3,16,4,"فِي يَوْمٍ مَا","однажды, в один день",["في يوم ما، رأيت صديقي يًدَخِّن و أنا أمرُّ بالمسجد",0,9,"Однажды, проходя мимо мечети, я увидел, как мой друг курит."]],[11217,3,16,4,"اِسْتَغَلَّ - يَسْتَغِلُّ - اِسْتِغْلَال","использовать, эксплуатировать • масдар: использование",null],[11218,3,17,1,"ذُرِّيَّة | ذُرِّيَّات، ذَرَارِيّ","потомство",["محمد صلى الله عليه من ذرية إسماعيل",22,26,"Мухаммад ﷺ — из потомства Исмаила."]],[11219,3,17,1,"أَغْنَى عَنْ - يُغْنِي - إِغْنَاء","избавлять от нужды, заменять; обогащать • масдар: обогащение",["العلم لا يغنى عن العمل أغناني الله بعد الفقر",9,13,"Знание не заменяет действия. / Аллах обогатил меня после бедности."]],[11220,3,17,1,"اِسْتَغْنَى عَنْ - يَسْتَغْنِي - اِسْتِغْنَاء","не нуждаться (в), обходиться (без) • масдар: ненуждаемость",["استغنيت بالزوجة الثانية عن الأولى",0,7,"Со второй женой я обошёлся без первой."]],[11221,3,17,1,"سَمَا - يَسْمُو - سُمُوّ","возвышаться • масдар: возвышенность, высота",["سمت درجة الطالب في قلبي/ سما الله بالإنسان",25,28,"Студент возвысился в моих глазах. / Аллах возвысил человека."]],[11222,3,17,1,"الحَيَوَانِيَّة","животное начало, животность",["ارتكاب الزنا من الحيوانية",16,25,"Совершение прелюбодеяния — проявление животного начала."]],[11223,3,17,1,"كَرَامَة | كَرَامَات","достоинство, честь",["حافظ على كرامتك",9,15,"Береги своё достоинство."]],[11224,3,17,1,"مَخْلُوق | مَخْلُوقَات","творение, создание",["الإنسان مخلوق من مخلوقات الله",8,13,"Человек — одно из творений Аллаха."]],[11225,3,17,1,"مَقْصُودَة","намеренная, целенаправленная",["كل أفعال الله مقصودة لا عبث",14,20,"Все действия Аллаха имеют цель, а не пусты."]],[11226,3,17,1,"آيَة | آيَات","1) аят (стих Корана) 2) знамение",["أعظم آية في كتاب الله أية الكرسي عصا موسى آية من آيات الله",5,8,"Величайший аят в Книге Аллаха — аят аль-Курси. / Посох Мусы — одно из знамений Аллаха."]],[11227,3,17,1,"مَوَدَّة | مَوَدَّات","любовь, привязанность",["حافظ على المودة بينك و بين زوجتك",9,15,"Береги любовь между тобой и женой."]],[11228,3,17,1,"رَابِطَة | رَوَابِط","связь, узы",["الصلاة أعظم رابطة بين العبد و ربه",12,17,"Молитва — величайшая связь между рабом и его Господом."]],[11229,3,17,1,"وَثِيقَة","прочная, тесная",["الزواج رابطة وثيقة بين الزوجين",13,18,"Брак — прочная связь между супругами."]],[11230,3,17,1,"عَثَرَ عَلَى - يَعْثُرُ - عُثُور","находить (случайно) • масдар: находка",["عثرت على بعض النقود",0,8,"Я нашёл немного денег."]],[11231,3,17,1,"عُثُور","нахождение, обнаружение",["العثور على صديق حقا صعب هذه الأيام",0,6,"Найти настоящего друга в наши дни трудно."]],[11232,3,17,1,"شَرِيك | شُرَكَاء","сотоварищ, партнёр",["الله لا شريك له",8,12,"У Аллаха нет сотоварища."]],[11233,3,17,1,"جُهْد | جُهُود","усилие, старание",["الدراسة تحتاج إلى جهد",18,21,"Учёба требует усилий."]],[11234,3,17,1,"رَبَّة | رَبَّات","хозяйка",["أمي لا تعمل، هي ربة بيت",16,19,"Моя мама не работает, она домохозяйка."]],[11235,3,17,1,"خُطْوَة | خُطُوَات، خُطًى","шаг, этап",["النظر إلى النساء أولى خطوات الزنا",22,27,"Взгляд на женщин — первый шаг к прелюбодеянию."]],[11236,3,17,1,"قَانِتَة | قَانِتَات","покорная (Аллаху), послушная",["الزوجة القانتة تسعد زوجها",7,14,"Покорная жена делает мужа счастливым."]],[11237,3,17,1,"الغَيْب | غُيُوب","сокровенное, неведомое",["لا يعلم الغيب إلا الله",8,13,"Сокровенное не знает никто, кроме Аллаха."]],[11238,3,17,1,"حَسَب | أَحْسَاب","знатное происхождение",["زوجتي ذات حسب. فأبوها ضابط",10,13,"Моя жена знатного рода: её отец — офицер."]],[11239,3,17,1,"عَرِيض","широкий, обширный",["نعيش الآن بين فساد عريض",19,23,"Мы живём среди повсеместной порчи."]],[11240,3,17,1,"الوَلِيّ | أَوْلِيَاء","опекун, покровитель (вали)",["ولي الزوجة أبوها",0,3,"Опекун жены — её отец."]],[11241,3,17,1,"بِكْر | أَبْكَار","девственница",["زواج البكر أفضل من زواج الثيب",5,10,"Брак с девственницей лучше, чем с ранее замужней."]],[11242,3,17,1,"ثَيِّب | ثَيِّبَات","ранее бывшая замужем (не девственница)",["خديجة كانت ثيبا",11,15,"Хадиджа ранее была замужем."]],[11243,3,17,1,"اِسْتَأْمَرَ - يَسْتَأْمِرُ - اِسْتِئْمَار","спрашивать совета, разрешения • масдар: испрашивание согласия",["استأمر الأب بنته في زواجها بعُمَر",0,6,"Отец спросил согласия дочери на брак с Умаром."]],[11244,3,17,1,"الوَدُود | وَدُودُون","любящий",["وهو الغفور الودود",11,17,"«И Он — Прощающий, Любящий»."]],[11245,3,17,1,"جَنَّبَ - يُجَنِّبُ - تَجْنِيب","оберегать (от), уберегать • масдар: ограждение",["الزوجة العاقلة تجنب زوجها المشكلات",15,19,"Разумная жена оберегает мужа от проблем."]],[11246,3,17,1,"طَرَف | أَطْرَاف","край; сторона",["لا تضع الكوب على طرف الطاولة كي لا يسقط",17,20,"Не ставь стакан на край стола, чтобы он не упал."]],[11247,3,17,1,"أَبَاحَ - يُبِيحُ - إِبَاحَة","разрешать, дозволять • масдар: дозволение",["أباح الله البيع و حرم الربا",0,4,"Аллах дозволил торговлю и запретил ростовщичество."]],[11248,3,17,1,"الخَاطِب | خَاطِبُون","жених, сватающийся",["على الخاطب أن ينظر إلى مخطوبته مرة أو مرتين",4,10,"Жених должен посмотреть на невесту раз или два."]],[11249,3,17,1,"مُنْذُ أَنْ","с тех пор как",["منذ أن جئت المركز و أنا أستفيد",0,6,"С тех пор как я пришёл в центр, я получаю пользу."]],[11250,3,17,1,"رَابِطَة وَثِيقَة","прочная связь",["الزواج رابطة وثيقة بين الزوجين",7,18,"Брак — прочная связь между супругами."]],[11251,3,17,1,"المَعَانِي الإِنْسَانِيَّة","человеческие качества (чувства)",["الحب و المودة و الرحمة من المعاني الإنسانسة في الزواج",0,0,"Любовь, привязанность и милосердие — человеческие ценности в браке."]],[11252,3,17,1,"فَعَلَى سَبِيلِ المِثَالِ","например",["أركان الإسلام خمسة فعلى سبيل المثال الصلاة",19,35,"Столпов ислама пять, например, молитва."]],[11253,3,17,1,"ذَات دِين","религиозная (обладающая религиозностью)",["أحتاج زوجة ذات دين",11,18,"Мне нужна религиозная жена."]],[11254,3,17,1,"طَلَبُ مَا لَيْسَ لَهَا","искать то, что ей не положено",["نهى الإسلام عن الانشغال بطلب ما ليس لك",0,0,"Ислам запретил заниматься поиском того, что тебе не положено."]],[11255,3,17,1,"خَطَبَ المَرْأَةَ","посвататься к женщине",["سعيد خطب امرأة ذات دين",0,0,"Саид посватался к религиозной женщине."]],[11256,3,17,1,"نَكَحَ - يَنْكِحُ - نِكَاح","жениться, вступать в брак • масдар: брак (никах)",null],[11257,3,17,1,"اِسْتَأْذَنَ - يَسْتَأْذِنُ - اِسْتِئْذَان","просить разрешения • масдар: испрашивание разрешения",null],[11258,3,17,2,"مَفْهُوم | مَفَاهِيم","понятие, концепция",["على كل مسلم معرفة مفهوم القدر",18,23,"Каждый мусульманин должен знать понятие предопределения."]],[11259,3,17,2,"مَنَّ عَلَى ... بِـ - يَمُنُّ - مَنّ","оказывать милость, даровать (кому-л. что-л.) • масдар: милость; попрёк",["الحمد لله الذي منَّ علينا بالإسلام",15,25,"Хвала Аллаху, который даровал нам ислам."]],[11260,3,17,2,"اِسْتَخْلَفَ - يَسْتَخْلِفُ - اِسْتِخْلَاف","назначать преемником, наместником • масдар: назначение преемника",["استخلف أبو بكر عمرَ على المسلمين.",0,6,"Абу Бакр назначил Умара своим преемником над мусульманами."]],[11261,3,17,2,"مَكَّنَ لِـ - يُمَكِّنُ - تَمْكِين","укреплять, давать власть • масдар: укрепление, утверждение",["اللهم مكّن لدينك في الأرض",6,10,"О Аллах, утверди Свою религию на земле."]],[11262,3,17,2,"بَدَّلَ - يُبَدِّلُ - تَبْدِيل","заменять, изменять • масдар: замена, искажение",["بدّل النصارى في كتابهم",0,4,"Христиане изменили (текст) в своей книге."]],[11263,3,17,2,"وَعَدَ - يَعِدُ - وَعْد","обещать • масдар: обещание",["وعدني الأستاذ بهدية بعد المستوى",0,5,"Преподаватель пообещал мне подарок после уровня."]],[11264,3,17,2,"رَغَد","благоденствие, изобилие; привольный",["أعيش في رغد لكنّ إخواني في سوريا يعيشون في شدة",8,11,"Я живу в достатке, а мои братья в Сирии — в тяготах."]],[11265,3,17,2,"أَذَاقَ - يُذِيقُ - إِذَاقَة","давать вкусить, заставить испытать • масдар: вкушение",["أذاق الاستاذ الطلاب الفول",0,4,"Преподаватель угостил студентов фулем."]],[11266,3,17,2,"آذَى - يُؤْذِي - إِيذَاء","причинять вред, обижать • масдар: вред, обида",["آذت قريش الرسول صلى الله عليه وسلم",0,0,"Курайш причиняли зло Посланнику ﷺ."]],[11267,3,17,2,"تَكْرِيم","почитание, чествование",["منحت الطالب المثالي هدية تكريما له",25,31,"Я подарил образцовому студенту подарок в знак почёта."]],[11268,3,17,2,"صِيَانَة","сохранение, защита; обслуживание (ремонт)",["أضع النقود في المصرف صيانة لها",21,26,"Я кладу деньги в банк ради их сохранности."]],[11269,3,17,2,"التَّهْلُكَة","погибель",["التدخين هو التهلكة",11,18,"Курение — это погибель."]],[11270,3,17,2,"دَافِع | دَوَافِع","мотив, побуждение",["حب الله و الخوف منه من دوافع الجهاد في سبيل الله",23,28,"Любовь к Аллаху и страх перед Ним — мотивы джихада на пути Аллаха."]],[11271,3,17,2,"مَالَ إِلَى - يَمِيلُ - مَيْل","склоняться (к), наклоняться; уклоняться (от) • масдар: склонность, наклон",["الزوج يميل إلى الزوجة الثانية",6,10,"Муж склоняется ко второй жене."]],[11272,3,17,2,"طَمَحَ إِلَى - يَطْمَحُ - طُمُوح","стремиться (к) • масдар: стремление, амбиции",["أطمح إلى الجنة",0,4,"Я стремлюсь в Рай."]],[11273,3,17,2,"تَطَلَّعَ إِلَى - يَتَطَلَّعُ - تَطَلُّع","стремиться, устремлять взор (к) • масдар: стремление",["تطلع السيسي إلى رئاسة مصر",0,4,"Сиси стремился к посту президента Египта."]],[11274,3,17,2,"نَزْعَة","склонность, влечение",["للإنسان نزعتان نزعة للخير و أخرى للشر",8,14,"У человека две склонности: к добру и ко злу."]],[11275,3,17,2,"سَوَّى - يُسَوِّي - تَسْوِيَة","соразмерно создавать, выравнивать • масдар: выравнивание",["سَوَّى الله الإنسان",0,6,"Аллах соразмерно сотворил человека."]],[11276,3,17,2,"أَلْهَمَ - يُلْهِمُ - إِلْهَام","внушать, вдохновлять • масдар: вдохновение, внушение",["ألهمني الله الجواب في الإمتحان",0,6,"Аллах внушил мне ответ на экзамене."]],[11277,3,17,2,"مَصْلَحَة | مَصَالِح","интерес, польза, благо",["مصلحة الدين فوق كل مصلحة شخصية",0,5,"Благо религии выше любой личной выгоды."]],[11278,3,17,2,"النَّسْل | أَنْسَال","потомство",["يحافظ الإسلام على مصلحة النسل",24,29,"Ислам охраняет интересы потомства."]],[11279,3,17,2,"العِرْض | أَعْرَاض","честь (личная, семейная)",["حافظ على عرضك",9,13,"Береги свою честь."]],[11280,3,17,2,"عَكَّرَ - يُعَكِّرُ - تَعْكِير","мутить, омрачать • масдар: замутнение",["التراب عكّر الماء النقي",7,11,"Пыль замутила чистую воду."]],[11281,3,17,2,"عَبِثَ بِـ - يَعْبَثُ - عَبَث","играть, баловаться (чем-л.) • масдар: баловство, бессмыслица",["تعبث بنتى بكتبي",0,4,"Моя дочь балуется моими книгами."]],[11282,3,17,2,"مُنْحَرِف | مُنْحَرِفُون","отклонившийся, извращённый",["انحرف المنحرف عن الطريق الصحيح",6,13,"Отклонившийся свернул с правильного пути."]],[11283,3,17,2,"مُخِلّ","нарушающий, портящий",["الأكل مخل للصلاة",6,9,"Еда нарушает молитву."]],[11284,3,17,2,"اِمْتَثَلَ لِـ - يَمْتَثِلُ - اِمْتِثَال","подчиняться, выполнять (приказ) • масдар: подчинение",["امتثل الطالب لأمر الأستاذ",0,5,"Студент выполнил приказ преподавателя."]],[11285,3,17,2,"النَّهْي | نَوَاهٍ","запрет",["انتهى المسلم بنهي الله",13,17,"Мусульманин воздерживается от того, что запретил Аллах."]],[11286,3,17,2,"حَرَصَ عَلَى - يَحْرِصُ - حِرْص","стремиться, заботиться (о) • масдар: старание, забота",["يحرص المسلم على نظافة مسكنه",0,4,"Мусульманин заботится о чистоте жилища."]],[11287,3,17,2,"اِنْتَمَى إِلَى - يَنْتَمِي - اِنْتِمَاء","принадлежать, относиться (к) • масдар: принадлежность",["أنا أنتمى إلى أمة محمد صلى الله عليه وسلم",4,13,"Я принадлежу к общине Мухаммада ﷺ."]],[11288,3,17,2,"المُتَعَمِّد | مُتَعَمِّدُون","умышленный, намеренный",["القاتل المتعمد يقتل",7,14,"Умышленный убийца подлежит казни."]],[11289,3,17,2,"هُدَاة مُهْتَدُونَ","ведущие и ведомые прямым путём",["نسأل الله أن تكون هداة مهتدين",0,0,"Просим Аллаха сделать нас ведущими и ведомыми прямым путём."]],[11290,3,17,2,"مَكَّنَ لَهُمْ دِينَهُمْ","утвердил для них их религию",["اللهم مكن لنا ديننا",0,0,"О Аллах, утверди для нас нашу религию."]],[11291,3,17,2,"لَا يُقَدَّرُ بِثَمَنٍ","бесценно, не измеряется ценой",["نعمة التوحيد لا تقدر بثمن",13,25,"Благо единобожия бесценно."]],[11292,3,17,2,"ضَرَبَ مَثَلًا","привёл пример (притчу)",["ضرب الله كثيراً من الأمثال في القرآن",0,0,"Аллах привёл в Коране много притч."]],[11293,3,17,2,"لِبَاس الجُوع","одеяние голода (сильный голод)",["لبس المسلمون لباس الجوع بما كانوا يصنعون",13,23,"Мусульмане облачились в одеяние голода за то, что они творили."]],[11294,3,17,2,"بِمَا كَانُوا يَصْنَعُونَ","за то, что они творили",["أذاقهم الله لباس الجوع والخوف بما كانوا يصنعون.",30,46,"Аллах дал им вкусить одеяние голода и страха за то, что они творили."]],[11295,3,17,2,"«وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ»","«не ввергайте себя своими руками в погибель»",["لا تلقوا بأيديكم إلى التهلكة أيها المسلمون فلا تدخنوا",0,0,"Не ввергайте себя в погибель, мусульмане, — не курите."]],[11296,3,17,2,"بِحُكْمِ طَبِيعَتِهَا","в силу её природы",["الزوجة بحكم طبيعتها لا تحب الزوجة الثانية",7,19,"Жена по своей природе не любит вторую жену."]],[11297,3,17,2,"لَمْ يَتْرُكْ صَغِيرَةً وَلَا كَبِيرَةً","не упустил ни малого, ни большого",["لم يترك الأستاذ صغيرة و لا كبيرة في الدرس",0,0,"Преподаватель не упустил на уроке ни одной мелочи."]],[11298,3,17,2,"سَوَاءٌ أَكَانَ ... أَمْ ...","будь то … или …",["أحب المسلم سواء أكان عربيا أم أعجميا",0,0,"Я люблю мусульманина, будь он арабом или неарабом."]],[11299,3,17,2,"الأَمْن الذَّاتِيّ","личная безопасность",["يحافظ الإسلام على الأمن الذاتي فحرم الاعتداء على النفس",18,30,"Ислам оберегает личную безопасность, поэтому запретил посягательство на жизнь."]],[11300,3,17,2,"الأَمْن الشَّامِل","всеобъемлющая безопасность",["يحرص الإسلام على الأمن الشامل فحرم القتل",17,29,"Ислам заботится о всеобщей безопасности, поэтому запретил убийство."]],[11301,3,17,2,"عَمَل مُخِلّ","нарушающее действие",["الأكل خلال الصلاة عمل مخلٌ",18,26,"Есть во время молитвы — нарушающее действие."]],[11302,3,17,2,"هَدَى - يَهْدِي - هِدَايَة، هُدًى","вести прямым путём, наставлять • масдар: руководство, прямой путь",null],[11303,3,17,2,"اِرْتَضَى لِـ - يَرْتَضِي - اِرْتِضَاء","избирать, одобрять (для) • масдар: одобрение",null],[11304,3,17,2,"قَدَّرَ - يُقَدِّرُ - تَقْدِير","ценить; оценивать; предопределять • масдар: оценка; уважение",null],[11305,3,17,2,"صَانَ - يَصُونُ - صَوْن، صِيَانَة","оберегать, сохранять • масдар: охрана; техобслуживание",null],[11306,3,17,2,"قَرَّرَ - يُقَرِّرُ - تَقْرِير","решать, постановлять • масдар: решение; доклад",null],[11307,3,17,2,"اِنْحَرَفَ عَنْ - يَنْحَرِفُ - اِنْحِرَاف","отклоняться (от) • масдар: отклонение",null],[11308,3,17,2,"أَخَلَّ بِـ - يُخِلُّ - إِخْلَال","нарушать (что-л.) • масдар: нарушение",null],[11309,3,17,3,"المَجُوسِيَّة","зороастризм, маздеизм",["كان دين إيران المجوسية",14,22,"Религией Ирана был зороастризм."]],[11310,3,17,3,"مَجُوسِيّ | مَجُوس","зороастриец, огнепоклонник; жрец огня",["لا يجوز زواج المسلم بالمجوسية",20,29,"Мусульманину нельзя жениться на зороастрийке."]],[11311,3,17,3,"قَاطِن | قَاطِنُون","проживающий, житель",["أنا قاطن في الحي العاشر",4,8,"Я проживаю в Десятом районе."]],[11312,3,17,3,"أَوْقَدَ - يُوقِدُ - إِيقَاد","зажигать, разжигать • масдар: разжигание",["أوقدت الزوجة الموقد",0,5,"Жена разожгла печь."]],[11313,3,17,3,"الأُسْقُف | أَسَاقِفَة","епископ",["في مصر كثير من الأساقفة",15,23,"В Египте много епископов."]],[11314,3,17,3,"الكَنِيسَة | كَنَائِس","церковь",["يعبد النصارى ربهم في الكنيسة",21,28,"Христиане поклоняются своему Господу в церкви."]],[11315,3,17,3,"الوَفَاة | وَفَيَات","кончина, смерть",["لما دخلت البيت حضرت أبي الوفاة",24,30,"Когда я вошёл в дом, к моему отцу пришла кончина."]],[11316,3,17,3,"أَوْصَى بِـ - يُوصِي - إِيصَاء، وَصِيَّة","завещать, наказывать (кому-л.) • масдар: завещание, наставление",["أوصى النبي أصحابه بعدم الاختلاف",0,4,"Пророк завещал своим сподвижникам не расходиться."]],[11317,3,17,3,"أَيْ بُنَيَّ","о сынок мой",["أي بنيّ، أوصانا نبينا بعدم الاختلاف",0,7,"Сынок, наш Пророк завещал нам не расходиться."]],[11318,3,17,3,"دَلَّ عَلَى - يَدُلُّ - دَلَالَة","указывать (на), показывать путь • масдар: указание; значение",["دلني رجل المرور على الطريق",0,0,"Регулировщик показал мне дорогу."]],[11319,3,17,3,"حَنِيف | حُنَفَاء","ханиф (исконный единобожник)",["اتبع ملة إبراهيم حنيفا",17,22,"Следуй религии Ибрахима, ханифа."]],[11320,3,17,3,"حَرَّة | حَرَّات","харра (поле чёрного вулканического камня)",["تقع المدينة بين حرتين",16,21,"Медина расположена между двумя харрами."]],[11321,3,17,3,"كَتِف | أَكْتَاف","плечо (лопатка)",["لكل إنسان كتفان",10,15,"У каждого человека два плеча."]],[11322,3,17,3,"خَاتَم | خَوَاتِم","1) печать 2) последний; кольцо, перстень",["هل رأيت صورة خاتم النبوة يا أستاذ؟",13,17,"Учитель, вы видели изображение печати пророчества?"]],[11323,3,17,3,"رَكْب | أَرْكُب، رُكُوب","караван, группа путников",["سافرت مع ركب من بلدي إلى مصر",9,12,"Я поехал в Египет с группой из моей страны."]],[11324,3,17,3,"وَادٍ | أَوْدِيَة، وِدْيَان","долина",["ظلم سلمان في وادي القرى",13,17,"Салмана обидели в Вади аль-Кура."]],[11325,3,17,3,"أَيْقَنَ أَنَّ - يُوقِنُ - إِيقَان","быть уверенным, убедиться • масдар: уверенность",["أيقنت أنَّ الحرب على الإسلام لا على المسلمين",0,10,"Я убедился, что война ведётся против ислама, а не против мусульман."]],[11326,3,17,3,"نَزَلَ بِـ/فِي - يَنْزِلُ - نُزُول","останавливаться (в); спускаться • масдар: остановка; спуск",["عندما اعتمرت، نزلت بفندق",0,0,"Когда я совершал умру, я остановился в гостинице."]],[11327,3,17,3,"أَقْبَلَ عَلَى - يُقْبِلُ - إِقْبَال","подходить, приближаться; приниматься (за) • масдар: спрос, приход",["أقبل المجاهد على الأعداء",0,4,"Воин двинулся на врагов."]],[11328,3,17,3,"تَقَاصَفَ عَلَى - يَتَقَاصَفُ - تَقَاصُف","толпиться (вокруг) • масдар: давка",["يتقاصف طلاب العلم على العلماء",0,6,"Ищущие знаний толпятся вокруг учёных."]],[11329,3,17,3,"زَعَمَ أَنَّ - يَزْعُمُ - زَعْم","утверждать (ложно), заявлять • масдар: утверждение (голословное)",["زعم مسيلمة الكذاب أنه نبيّ",0,3,"Мусайлима-лжец утверждал, что он пророк."]],[11330,3,17,3,"رَعْشَة","дрожь, озноб",["أخذتني رعشة عندما سمعت خبر وفاة سامح",7,11,"Меня охватила дрожь, когда я услышал о смерти Самеха."]],[11331,3,17,3,"رَجَفَ - يَرْجُفُ - رَجْف","дрожать, трястись • масдар: дрожь",["رجفت خوفا من الله عند سماع آيات العذاب",0,4,"Я задрожал от страха перед Аллахом, услышав аяты о наказании."]],[11332,3,17,3,"كَادَ - يَكَادُ - كَوْد","чуть не, едва не • масдар: приближение",["كاد سلمان يسقط، لكنه لم يسقط",0,3,"Салман чуть не упал, но не упал."]],[11333,3,17,3,"نَذَرَ - يَنْذُرُ - نَذْر","давать обет • масдар: обет",["نذر محمد أن يصوم يوما إذا نجح",0,3,"Мухаммад дал обет поститься один день, если сдаст."]],[11334,3,17,3,"أَمْسَكَ عَنْ","воздерживаться (от действия)",["يمسك الصائم عن الطعام و الشراب و الجماع",0,0,"Постящийся воздерживается от еды, питья и близости."]],[11335,3,17,3,"بَسَطَ - يَبْسُطُ - بَسْط","протягивать, расстилать • масдар: расстилание",["بسط أخي يده ليأخذ القلم",0,3,"Брат протянул руку, чтобы взять ручку."]],[11336,3,17,3,"الغَدَاة | غَدَوَات","раннее утро (между фаджром и восходом)",["أذكر الله في الغداة",13,19,"Я поминаю Аллаха ранним утром."]],[11337,3,17,3,"مَكَثَ - يَمْكُثُ - مُكُوث","оставаться, пребывать • масдар: пребывание",["كم سنة ستمكث في مصر",7,12,"Сколько лет ты пробудешь в Египте?"]],[11338,3,17,3,"جَنَازَة | جَنَائِز","похороны; покойник",["ما صلينا الجنازة على سامح، لأنه شهيد بإذن الله",9,16,"Мы не совершали заупокойную молитву над Самехом, потому что он шахид, с позволения Аллаха."]],[11339,3,17,3,"عَدَلَ عَنْ - يَعْدِلُ - عُدُول","отказываться (от), отступать • масдар: отказ",["عدل الأستاذ عن رأيه",0,0,"Преподаватель отказался от своего мнения."]],[11340,3,17,3,"رِدَاء | أَرْدِيَة","накидка, верхняя одежда",["على المسلم أن يهتم بنظافة ردائه",0,0,"Мусульманин должен заботиться о чистоте своей накидки."]],[11341,3,17,3,"كَاهِل | كَوَاهِل","загривок, плечи (место между лопатками)",["احتجمت في كاهلي",10,15,"Мне сделали хиджаму на загривке."]],[11342,3,17,3,"أَكَبَّ عَلَى - يُكِبُّ - إِكْبَاب","склониться (над); погрузиться (в) • масдар: погружение",["أكبت أمي عليَّ عندما رجعت إليها",0,4,"Мама склонилась надо мной (обняла), когда я вернулся к ней."]],[11343,3,17,3,"أَوْقَدَ النَّارَ","разжёг огонь",["أوقد أخي النار ليعد الطعام",0,0,"Брат разжёг огонь, чтобы приготовить еду."]],[11344,3,17,3,"أَعْجَبَنِي أَمْرُهُمْ","мне понравилось их дело",["حال المسلمين اليوم لا يعجبني أمرهم",0,0,"Положение мусульман сегодня мне не нравится."]],[11345,3,17,3,"رَجُل سَوْء","дурной человек",["لا تصاحب رجل سوء.",9,16,"Не дружи с дурным человеком."]],[11346,3,17,3,"حَضَرَتْهُ الوَفَاةُ","к нему пришла смерть",["حضرت الوفاة النبي في العام الحادي عشر من الهجرة",0,0,"Смерть пришла к Пророку в одиннадцатом году хиджры."]],[11347,3,17,3,"لَهُ آيَاتٌ لَا تَخْفَى","у него явные признаки",["مركز كلمة له آيات لا تخفى",10,25,"У центра «Калима» явные достоинства."]],[11348,3,17,3,"لَفِي رَأْسِ نَخْلَة","на верхушке пальмы",["الفلاح في رأس النخلة يحصد البلح",0,0,"Крестьянин на верхушке пальмы собирает финики."]],[11349,3,17,3,"قَاتَلَهُ اللهُ","да покарает его Аллах (проклятие)",["قاتل الله الكذب، كم أفسد بين الناس!",0,0,"Да покарает Аллах ложь — сколько она рассорила людей!"]],[11350,3,17,3,"مَا لَكَ وَلِهٰذَا؟","какое тебе до этого дело?",["يا طالب مالك و لهذا؟، هذا ليس عملك و إنما عمل الأستاذ",0,0,"Студент, какое тебе до этого дело? Это не твоя работа, а преподавателя."]],[11351,3,17,3,"أَهْل حَاجَةٍ وَغُرْبَةٍ","нуждающиеся и чужестранцы",["أنتم – يأيها الطلاب – أهل حاجة و غربة",0,0,"Вы, студенты, — нуждающиеся и чужестранцы."]],[11352,3,17,3,"تَبِعَ جَنَازَةً","сопровождать похоронную процессию",["اتباع الجنازة أجره عظيم",0,0,"Награда за следование за похоронами велика."]],[11353,3,17,3,"قَطَنَ - يَقْطُنُ - قُطُون","проживать, обитать • масдар: проживание",null],[11354,3,17,4,"ضَرُورِيَّة | ضَرُورِيَّات","необходимая",["النظافة ضرورية",8,14,"Чистота необходима."]],[11355,3,17,4,"أَوَى إِلَى - يَأْوِي - أُوِيّ","укрываться, находить приют (в); отправляться (в постель) • масдар: приют, убежище",["إذا أويت إلى فراشك فاقرأ آية الكرسي",4,12,"Когда ляжешь в постель, прочитай аят аль-Курси."]],[11356,3,17,4,"اِرْتَدَى - يَرْتَدِي - اِرْتِدَاء","надевать, носить • масдар: ношение",["ارتديت ثوب الإحرام",0,6,"Я надел одежду ихрама."]],[11357,3,17,4,"تَمَّ - يَتِمُّ - تَمَام","завершаться, совершаться • масдар: завершение, полнота",["تم الدين بموت محمد صلى الله عليه وسلم",0,2,"Религия была завершена со смертью Мухаммада ﷺ."]],[11358,3,17,4,"مَسَّ - يَمَسُّ - مَسّ","касаться, трогать • масдар: прикосновение",["لا تمس المصحف و أنت غير متوضئ",3,6,"Не касайся Мусхафа, не имея омовения."]],[11359,3,17,4,"مَكْنُون","хранимый, сокрытый",["المصحف مكنون في المكتبة",7,12,"Мусхаф хранится в библиотеке."]],[11360,3,17,4,"السِّوَاك | أَسْوِكَة، سُوك","сивяк (палочка для чистки зубов)",["استعمل السواك على قدر استطاعتك",7,13,"Пользуйся сивяком, насколько можешь."]],[11361,3,17,4,"مَطْهَرَة","средство очищения",["السواك مطهرة للفم",7,12,"Сивяк очищает рот."]],[11362,3,17,4,"مَرْضَاة","то, что вызывает довольство",["السواك مرضاة للرب",7,12,"Сивяк — то, чем доволен Господь."]],[11363,3,17,4,"شَقَّ عَلَى - يَشُقُّ - مَشَقَّة","быть тяжёлым, трудным (для кого-л.) • масдар: тяжесть, трудность",["الواجب يشق عليّ",7,10,"Домашнее задание мне тяжело."]],[11364,3,17,4,"سَوَاء | أَسْوَاء","одинаковый, равный",["الخمر و المخدرات سواء في الحرام",17,21,"Вино и наркотики одинаково запретны."]],[11365,3,17,4,"مَعْجُون | مَعَاجِين","паста (зубная)",["السواك أفضل من المعجون الطبيّ",15,22,"Сивяк лучше лечебной пасты."]],[11366,3,17,4,"أَشْعَث | شُعْث","растрёпанный, лохматый",["رأيت رجلا شعثا في المسجد لكنه ذو دين",10,14,"Я видел в мечети лохматого человека, но он религиозен."]],[11367,3,17,4,"سُنَّة | سُنَن","сунна (путь, обычай Пророка)",["أحب الله و الإسلام و القرآن و السنة",30,35,"Я люблю Аллаха, ислам, Коран и Сунну."]],[11368,3,17,4,"الفِطْرَة","фитра (врождённая природа)",["الختان من سنن الفطرة",14,20,"Обрезание — из сунн фитры."]],[11369,3,17,4,"الاِسْتِحْدَاد","удаление волос на лобке",["من سنن يوم الجمعة الاستحداد",18,27,"Из сунн пятницы — удаление волос на лобке."]],[11370,3,17,4,"الخِتَان","обрезание",["يُسَنُّ الختان في اليوم السابع من الولادة",8,14,"Обрезание желательно на седьмой день после рождения."]],[11371,3,17,4,"نَتَفَ - يَنْتِفُ - نَتْف","выщипывать • масдар: выщипывание",["أشعر بألم عند نتف الإبط",14,17,"Мне больно выщипывать волосы под мышками."]],[11372,3,17,4,"قَلَّمَ - يُقَلِّمُ - تَقْلِيم","стричь (ногти), подрезать • масдар: стрижка, подрезание",["قلِّم أظافرك ياولد",0,5,"Подстриги ногти, мальчик!"]],[11373,3,17,4,"تَخَلَّصَ مِنْ - يَتَخَلَّصُ - تَخَلُّص","избавляться (от) • масдар: избавление",["لابد أن أتخلص من هذه الزوجة العنيدة",8,13,"Мне нужно избавиться от этой упрямой жены."]],[11374,3,17,4,"وِقَايَة مِنْ","защита (от), профилактика",["الزواج وقاية من الزنا",7,15,"Брак — защита от прелюбодеяния."]],[11375,3,17,4,"مُسَبِّب | مُسَبِّبَات","причина, фактор",["المنازعات بين المسلمين من مسببات التخلف",26,32,"Распри между мусульманами — одна из причин отсталости."]],[11376,3,17,4,"الذَّوْق | أَذْوَاق","вкус; такт, хорошие манеры",["ليس من الذوق قضاء الحاجة في الطريق",7,12,"Справлять нужду на дороге — неприлично."]],[11377,3,17,4,"القُمَامَة | قُمَامَات","мусор",["أين سلة القمامة؟",8,15,"Где мусорная корзина?"]],[11378,3,17,4,"بِضْع","несколько (от 3 до 9)",["الباقي على نهاية الدرس بضع دقائق",23,26,"До конца урока осталось несколько минут."]],[11379,3,17,4,"فَضْلَة | فَضَلَات","остаток, отходы",["لا تلق فضلات الطعام في سلة النفايات",7,12,"Не выбрасывай остатки еды в мусорную корзину."]],[11380,3,17,4,"شُعْبَة | شُعَب، شِعَاب","ветвь, часть; отделение",["الإيمان بضع و سبعون شعبة",20,24,"Вера — семьдесят с лишним ветвей."]],[11381,3,17,4,"أَدْنَى","ближайший; самый низкий",["أدنى مراحل التعليم الحضانة",0,4,"Начальная ступень образования — детский сад."]],[11382,3,17,4,"الحَيَاء","стыдливость, скромность",["أريد زوجة ذات حياء",14,18,"Я хочу стыдливую жену."]],[11383,3,17,4,"الظِّلّ | ظِلَال","тень",["سبعة يظلهم الله في ظله يوم لا ظل إلا ظله",0,0,"Семерых Аллах укроет в Своей тени в день, когда не будет тени, кроме Его."]],[11384,3,17,4,"مَطْهَرَة لِلْفَمِ","очищение для рта",["السواك مطهرة للفم",7,17,"Сивяк очищает рот."]],[11385,3,17,4,"مَا يَقُومُ مَقَامَهُ","то, что заменяет его",["الفول لا يقوم مقام اللحم",0,0,"Фуль не заменяет мясо."]],[11386,3,17,4,"يُسَكِّنُ شَعْرَهُ","приглаживает (расчёсывает) волосы",["لماذا لا تسكن شعرك",0,0,"Почему ты не причешешь волосы?"]],[11387,3,17,4,"نَتْف الإِبْط","выщипывание волос под мышками",["أجد صعوبة عند نتف الإبط",14,23,"Мне трудно выщипывать волосы под мышками."]],[11388,3,17,4,"لَيْسَ مِنَ الصِّحَّةِ","неправильно",["ليس من الصحة رفع الصوت أمام الأستاذ",0,12,"Неправильно повышать голос перед преподавателем."]],[11389,3,17,4,"يَقْضِي حَاجَتَهُ","1) исполняет его нужду 2) справляет нужду",["لا تقضِ حاجتك في الشارع.",0,0,"Не справляй нужду на улице."]],[11390,3,17,4,"وَقَى مِنْ - يَقِي - وِقَايَة","оберегать (от) • масдар: защита, профилактика",null],[11391,3,17,5,"ضَرَر | أَضْرَار","вред, ущерб",["من أضرار التدخين التهاب الرئة",3,8,"Один из вредов курения — воспаление лёгких."]],[11392,3,17,5,"أَنْذَرَ بِـ - يُنْذِرُ - إِنْذَار","предупреждать, предостерегать • масдар: предупреждение",["أنذر الله الكفار من الشرك بالنار",0,4,"Аллах предостерёг неверных Огнём от многобожия."]],[11393,3,17,5,"أَظْهَرَ أَنَّ - يُظْهِرُ - إِظْهَار","показывать, обнаруживать • масдар: проявление",["أظهرت الدراسات أنَّ التدخين انتحار بطيء",0,5,"Исследования показали, что курение — медленное самоубийство."]],[11394,3,17,5,"الشَّيْخُوخَة","старость",["أبي في مرحلة الشيخوخة",13,21,"Мой отец в преклонном возрасте."]],[11395,3,17,5,"اِنْتِحَار","самоубийство",["الانتحار حرام",0,8,"Самоубийство запрещено."]],[11396,3,17,5,"إِجْمَاع","единогласие, консенсус (иджма)",["انعقد الإجماع على تحريم التدخين",6,13,"Был достигнут консенсус о запрете курения."]],[11397,3,17,5,"عَاقِل | عُقَلَاء","разумный",["من يشتري المرض بنقود فهو غير عاقل",29,33,"Кто покупает болезнь за деньги, тот неразумен."]],[11398,3,17,5,"ضِرَار","причинение вреда (другим)",["لا ضرر و لا ضرار",12,16,"Нельзя ни вредить, ни причинять вред в ответ."]],[11399,3,17,5,"طِبْقًا لِـ ... فَإِنَّ ...","согласно…, то…",["طبقا لقانون المركز فإنك راسب",0,0,"Согласно правилам центра, ты не сдал."]],[11400,3,17,5,"وَبَاء | أَوْبِئَة","эпидемия",["مرض الخنزير وباء خطير",12,16,"Свиной грипп — опасная эпидемия."]],[11401,3,17,5,"الجِنْس | أَجْنَاس","род, вид, пол",["الذهب حرام على جنس الرجال",15,18,"Золото запрещено мужскому полу."]],[11402,3,17,5,"النَّاتِجَة","возникающая, являющаяся результатом",["تلوث الهواء ناتج عن وسائل النقل",0,0,"Загрязнение воздуха — результат работы транспорта."]],[11403,3,17,5,"التَّبْغ","табак",["تحرم زراعة التبغ",11,16,"Выращивание табака запрещено."]],[11404,3,17,5,"دِعَايَة | دِعَايَات","реклама, пропаганда",["تنفق شركات التبغ كثيراً على دعاياتها",28,36,"Табачные компании тратят много на рекламу."]],[11405,3,17,5,"أَقْدَمَ عَلَى - يُقْدِمُ - إِقْدَام","решиться (на), приступить (к) • масдар: решимость",["أيها المراهق لا تقدم على التدخين",16,20,"Подросток, не начинай курить."]],[11406,3,17,5,"تَعَدَّى إِلَى - يَتَعَدَّى - تَعَدٍّ","переходить, распространяться (на); переступать • масдар: переход; посягательство",["دخان المدخن يتعدى إلى من بجانبه",12,17,"Дым курильщика переходит на тех, кто рядом."]],[11407,3,17,5,"المُتَصَاعِد","поднимающийся",["ماهذا الدخان المتصاعد! أظن أن هناك حريقا",13,21,"Что это за поднимающийся дым! Кажется, пожар."]],[11408,3,17,5,"اِسْتَنْشَقَ - يَسْتَنْشِقُ - اِسْتِنْشَاق","вдыхать • масдар: вдыхание",["من سنن الوضوء الاستنشاق",14,23,"Вдыхание воды носом — из сунн омовения."]],[11409,3,17,5,"تَعَارَضَ مَعَ - يَتَعَارَضُ - تَعَارُض","противоречить (чему-л.) • масдар: противоречие",["اختلاط الرجال بالنساء يتعارض مع ثقافتنا",22,28,"Смешение мужчин с женщинами противоречит нашей культуре."]],[11410,3,17,5,"حَرِيق | حَرَائِق","пожар",["كم من حريق شب بسبب سجارة",6,10,"Сколько пожаров вспыхнуло из-за сигареты!"]],[11411,3,17,5,"شَبَّ - يَشِبُّ - شُبُوب","вспыхнуть; вырасти (стать юношей) • масдар: вспышка; юность",["شب حريق في البيت الأبيض",0,2,"В Белом доме вспыхнул пожар."]],[11412,3,17,5,"جَسِيم | جِسَام","огромный, серьёзный",["كان حريق البيت الأبيض جسيما",22,27,"Пожар в Белом доме был крупным."]],[11413,3,17,5,"المُصِيبَة | مَصَائِب","беда, несчастье",["كل مصيبة بعيدة عن الدين فهي سهلة",3,8,"Любая беда, не касающаяся религии, — легка."]],[11414,3,17,5,"إِضَاعَة","растрата, потеря",["نهى الإسلام عن إضاعة المال",15,20,"Ислам запретил транжирить деньги."]],[11415,3,17,5,"قَضَاء اللهِ","предопределение Аллаха",["قضاء الله كله خير",0,9,"Всё предопределение Аллаха — благо."]],[11416,3,17,5,"اِنْتِحَار بَطِيء","медленное самоубийство",["التدخين انتحار بطيء",8,19,"Курение — медленное самоубийство."]],[11417,3,17,5,"طِبْقًا لَهُ","согласно ему",["طبقا لقانون المركز عليك أن تدفع 25 جنيها زيادة",0,0,"Согласно правилам центра, ты должен доплатить 25 фунтов."]],[11418,3,17,5,"أَخْطَر وَبَاء","опаснейшая эпидемия",["التدخين أخطر وباء عرفه التاريخ",8,17,"Курение — опаснейшая эпидемия в истории."]],[11419,3,17,5,"الجِنْس البَشَرِيّ","человеческий род",["التوحيد واجب على جميع أفراد الجنس البشري",28,40,"Единобожие обязательно для всех представителей рода человеческого."]],[11420,3,17,5,"بِصِفَةٍ خَاصَّةٍ","в особенности",["أحب الطلاب وبصفة خاصة طارق",11,21,"Я люблю студентов, особенно Тарика."]],[11421,3,17,5,"مَارَسُوا التَّدْخِينَ","курили (занимались курением)",["لا تمارسوا التدخين، فإنه انتحار بطيء",0,0,"Не курите — это медленное самоубийство."]],[11422,3,17,5,"يَقْتُلُ نَفْسَهُ بِنَفْسِهِ","убивает себя сам",["أيها المدخن لا تقتل نفسك بنفسك",0,0,"Курильщик, не убивай себя сам."]],[11423,3,17,5,"التَّدْخِينُ ضَرَرٌ مُتَعَدٍّ","курение — вред, распространяющийся на других",["التدخين ضرر متعد لا لازم",0,16,"Курение — вред, затрагивающий и других, а не только курящего."]],[11424,3,17,5,"دُونَ اخْتِيَارٍ مِنْهُمْ","без их выбора (против их воли)",["يستنشق الأطفال الدخان المتصاعد من المدخنين دون اختيار منهم",43,58,"Дети против своей воли вдыхают дым курильщиков."]],[11425,3,17,5,"الحُرِّيَّة الشَّخْصِيَّة","личная свобода",["التدخين ليس حرية شخصية",12,22,"Курение — не личная свобода."]],[11426,3,17,5,"أَضْرَارُهُ جَسِيمَة","его вред огромен",["التدخين أضراره جسيمة",8,20,"Вред курения огромен."]],[11427,3,17,5,"لَا يَأْخُذُ مُقَابِلَ ذٰلِكَ إِلَّا...","не получает взамен ничего, кроме…",["المدخن لا يأخذ مقابل ذلك إلا المرض في الدنيا و النار في الآخرة",7,28,"Курильщик не получает взамен ничего, кроме болезни в этом мире и Огня в вечном."]],[11428,3,17,5,"شَاخَ - يَشِيخُ - شَيْخُوخَة","стареть • масдар: старость",null],[11429,3,17,5,"اِنْتَحَرَ - يَنْتَحِرُ - اِنْتِحَار","покончить с собой • масдар: самоубийство",null],[11430,3,17,5,"أَضَاعَ - يُضِيعُ - إِضَاعَة","терять, тратить впустую • масдар: потеря, растрата",null],[11431,3,17,5,"أَحَلَّ لِـ - يُحِلُّ - إِحْلَال","разрешать, дозволять • масдар: дозволение",null],[11432,3,17,6,"طَبَقَة | طَبَقَات","слой, класс; уровень, ступень",["أتطلع إلى أعلى طبقة في الجنة",15,19,"Я стремлюсь к высшей ступени в Раю."]],[11433,3,17,6,"صِنْف | أَصْنَاف، صُنُوف","вид, сорт, категория",["من أي صنف الليمون؟",6,9,"К какому виду относится лимон?"]],[11434,3,17,6,"عَلَى التَّحْقِيقِ","на самом деле, воистину",["عمر صديقي على التحقيق",10,21,"Умар — мой настоящий друг."]],[11435,3,17,6,"رَفِيق | رِفَاق، رُفَقَاء","спутник, товарищ",["أين رفيقك يا عمر؟",4,9,"Где твой товарищ, Умар?"]],[11436,3,17,6,"حَيَّا - يُحَيِّي - تَحِيَّة","приветствовать • масдар: приветствие",["حيّاك الله.",0,5,"Да приветствует тебя Аллах!"]],[11437,3,17,6,"خَلَّة | خِلَال","качество, черта характера",["فيك خلة من خلال الصحابة",4,7,"В тебе есть черта из черт сподвижников."]],[11438,3,17,6,"مُؤْنِس | مُؤْنِسُون","приятный (собеседник), развеивающий грусть",["عمر صديق مؤنس لا مزعج",9,13,"Умар — приятный друг, а не надоедливый."]],[11439,3,17,6,"مُزْعِج | مُزْعِجُون","надоедливый, беспокоящий",["الأطفال الصغار مزعجون",15,21,"Маленькие дети надоедливы."]],[11440,3,17,6,"سَمْت","облик, манера (поведения)",["مرسي عليه سمت الصالحين",10,13,"У Мурси облик праведников."]],[11441,3,17,6,"زِيّ | أَزْيَاء","одежда, костюм",["لا تتزين بزي الكفار",9,12,"Не наряжайся в одежду неверных."]],[11442,3,17,6,"عَاهَدَ عَلَى - يُعَاهِدُ - مُعَاهَدَة","давать обещание, обязательство (кому-л.) • масдар: договор, обязательство",["عاهدت الله على أن لا أرجع إلى تلك المعصية",0,0,"Я пообещал Аллаху не возвращаться к тому греху."]],[11443,3,17,6,"خَانَ - يَخُونُ - خِيَانَة","нарушить обещание (договор) • масдар: измена, предательство",["لا تخن العهد الذي عاهدت الله عليه",0,0,"Не нарушай обещание, которое ты дал Аллаху."]],[11444,3,17,6,"غِشّ","обман, мошенничество; списывание",["الغش في الامتحان حرام و ليس حلال",0,4,"Списывание на экзамене запрещено, а не дозволено."]],[11445,3,17,6,"إِثَارَة","возбуждение, разжигание",["تشجع وسائل الإعلام على إثارة الشهوة",23,28,"СМИ поощряют разжигание страстей."]],[11446,3,17,6,"الخَامِد","потухший, утихший",["هذه نار خامدة فلا توقدوها",8,13,"Это потухший огонь — не разжигайте его."]],[11447,3,17,6,"سَرَّ - يَسُرُّ - سُرُور","радовать • масдар: радость",["يسرني لقاؤك",0,5,"Рад встрече с тобой."]],[11448,3,17,6,"بَالَى - يُبَالِي - مُبَالَاة","обращать внимание, беспокоиться (о) • масдар: внимание",["لا يبالي الكسلان بدروسه",3,8,"Лентяй не обращает внимания на свои уроки."]],[11449,3,17,6,"مَسَرَّة | مَسَرَّات","радость, удовольствие",["صديقك من تراه وقت الأحزان قبل المسرات",30,37,"Твой друг — тот, кого видишь во время горя прежде радостей."]],[11450,3,17,6,"مُعِين | مُعِينُون","помощник",["تحتاج صديقا معينا على طاعة الله",12,17,"Тебе нужен друг, помогающий в покорности Аллаху."]],[11451,3,17,6,"طَرِيقَة | طُرُق، طَرَائِق","способ, метод",["المدرس الجديد يجهل طرائق التدريس",19,24,"Новый преподаватель не знает методов преподавания."]],[11452,3,17,6,"المُعَاشَرَة","общение, совместная жизнь",["لا تعلم صديقك إلا عن طريق المعاشرة",26,34,"Своего друга узнаёшь только через общение."]],[11453,3,17,6,"أَحْمَق | حُمْق، حَمْقَى","глупый, глупец",["لا تجادل الأحمق.",9,15,"Не спорь с глупцом."]],[11454,3,17,6,"صَادَقَ - يُصَادِقُ - مُصَادَقَة، صَدَاقَة","дружить (с кем-л.) • масдар: дружба",["لا تصادق إلا مؤمنا",3,8,"Дружи только с верующим."]],[11455,3,17,6,"مَنْصِب | مَنَاصِب","должность, пост",["يسعى الناس وراء المناصب",16,23,"Люди гонятся за должностями."]],[11456,3,17,6,"زِينَة | زِينَات","украшение, красота",["الزوجة الصالحة زينة البيت",15,19,"Праведная жена — украшение дома."]],[11457,3,17,6,"حِلْيَة | حِلًى، حِلْيَات","украшение, драгоценность",["القرآن ليس حلية للجدار و إنما حلية للقلوب",11,15,"Коран — украшение не для стены, а для сердец."]],[11458,3,17,6,"تَجَمَّلَ - يَتَجَمَّلُ - تَجَمُّل","украшаться, прихорашиваться • масдар: украшение",["على الزوجة أن تجَمّل نفسها لزوجها فقط",14,20,"Жена должна прихорашиваться только для мужа."]],[11459,3,17,6,"الخُلَاصَة | خُلَاصَات","итог, вывод, суть",["خلاصة الدرس : ابحث عن الصديق الصالح",0,5,"Итог урока: ищи праведного друга."]],[11460,3,17,6,"الغِذَاء | أَغْذِيَة","пища, питание",["قلة الغذاء تؤدي إلى مجاعة",4,10,"Недостаток пищи приводит к голоду."]],[11461,3,17,6,"سَاءَ - يَسُوءُ - سُوء","ухудшаться, быть плохим; огорчать • масдар: зло, порча",["ساءت أحوال المجاهدين بسبب الإختلاف",0,4,"Положение воинов ухудшилось из-за разногласий."]],[11462,3,17,6,"طَعْم","вкус",["طعم الفول لذيذ",0,3,"Вкус фуля приятный."]],[11463,3,17,6,"هَضَمَ - يَهْضِمُ - هَضْم","переваривать • масдар: пищеварение",["الفول صعب الهضم",10,15,"Фуль трудно переваривается."]],[11464,3,17,6,"لَذَّ - يَلَذُّ - لَذَّة","быть вкусным, приятным • масдар: наслаждение",["لذّ الفول بعد ما أضفت إليه طماطم",0,3,"Фуль стал вкусным после того, как я добавил помидоры."]],[11465,3,17,6,"أَوْدَى بِـ - يُودِي - إِيدَاء","губить, приводить (к гибели) • масдар: гибель",["أودى التدخين بالمدخن إلى الموت",0,4,"Курение довело курильщика до смерти."]],[11466,3,17,6,"البَلَاء","испытание, беда",["أعظم البلاء البلاء في الدين",5,11,"Величайшая беда — беда в религии."]],[11467,3,17,6,"غِلْظَة","грубость, жёсткость",["أشكو من غلظة الأستاذ",8,12,"Я жалуюсь на грубость преподавателя."]],[11468,3,17,6,"جَفَا - يَجْفُو - جَفَاء","быть грубым, черстветь • масдар: грубость, отчуждение",["جفا الزوج",0,3,"Муж стал грубым."]],[11469,3,17,6,"الطَّبْع | طِبَاع","нрав, характер",["أحب زوجة ذات طباع حسنة",13,17,"Я хочу жену с хорошим нравом."]],[11470,3,17,6,"اُضْطُرَّ إِلَى - يُضْطَرُّ - اِضْطِرَار","быть вынужденным (к) • масдар: вынужденность",["اضطر محمد إلى الرجوع لبلده لنفاد النقود",0,4,"Мухаммад был вынужден вернуться на родину, так как кончились деньги."]],[11471,3,17,6,"سَلَّى - يُسَلِّي - تَسْلِيَة","утешать, развлекать • масдар: утешение; развлечение",["الزوجة الصالحة تسلِّي زوجها عند المصائب",15,21,"Праведная жена утешает мужа в бедах."]],[11472,3,17,6,"أَهْلَكَ - يُهْلِكُ - إِهْلَاك","губить, уничтожать • масдар: уничтожение",["اللهم أهلك الظالمين.",6,10,"О Аллах, погуби угнетателей."]],[11473,3,17,6,"مَتَّعَ - يُمَتِّعُ - تَمْتِيع","доставлять удовольствие • масдар: доставление наслаждения",["متعني الإمام بصوته العذب",0,5,"Имам порадовал меня своим приятным голосом."]],[11474,3,17,6,"اِسْتَمْسِكْ بِهِ","держись за него крепко",["استمسك بالقرآن و السنة",0,0,"Держись Корана и Сунны."]],[11475,3,17,6,"تَجَاوَزَ - يَتَجَاوَزُ - تَجَاوُز","переходить границу, преступать • масдар: превышение",["من تجاوز حدود الله، عذبه الله يوم القيامة",3,8,"Кто преступит границы Аллаха, того Аллах накажет в Судный день."]],[11476,3,17,6,"ظَرِيف | ظُرَفَاء","остроумный, милый",["أخي ظريف، فمزاحه يسرني",4,8,"Мой брат остроумен, его шутки меня радуют."]],[11477,3,17,6,"اِقْتَصَرَ عَلَى - يَقْتَصِرُ - اِقْتِصَار","ограничиваться (чем-л.) • масдар: ограничение",["سأقتصر على زوجة واحدة كي لا أقتل",0,10,"Я ограничусь одной женой, чтобы меня не убили."]],[11478,3,17,6,"العَبَث","бесполезное занятие, баловство",["الأطفال يحبون العبث بالكتب",14,19,"Дети любят баловаться с книгами."]],[11479,3,17,6,"خِلَال الخَيْر","добрые качества",["صديقي يتمتع بخلال الخير",12,23,"У моего друга добрые качества."]],[11480,3,17,6,"سَمْت المُتَّقِين","облик богобоязненных",["إمام المسجد له سمت المتقين",15,26,"У имама мечети облик богобоязненных."]],[11481,3,17,6,"زِيّ الصَّالِحِين","одежда праведников",["أحب أن أتزين بزي الصالحين",13,25,"Я люблю одеваться в одежду праведников."]],[11482,3,17,6,"سُلَّم لِلدُّنْيَا","лестница к мирскому (средство мирской выгоды)",["لا تجعل دراستك سلما للدنيا",15,26,"Не делай свою учёбу лестницей к мирскому."]],[11483,3,17,6,"شَبَكَة لِلْمَالِ","сеть для денег (средство наживы)",["بعض الناس دراستهم شبكة للمال",18,28,"Для некоторых людей учёба — средство наживы."]],[11484,3,17,6,"إِثَارَة الخَامِد","разжигание утихшего",["لا تكن سببا في إثارة الخامد من الغضب بين صديقيك",15,27,"Не будь причиной разжигания утихшего гнева между твоими друзьями."]],[11485,3,17,6,"طَرَائِق المُعَاشَرَة","способы общения (совместной жизни)",["عليك بقراءة كتاب عن طرائق معاشرة الزوجة.",20,32,"Тебе следует прочитать книгу о том, как жить с женой."]],[11486,3,17,6,"عُدَّة لِغَدِهِ","запас на его завтра (подготовка к будущему)",["طلب العلم عدة لغدنا",0,0,"Поиск знаний — подготовка к нашему завтра."]],[11487,3,17,6,"حِلْيَة تُجَمِّلُ الجِدَارَ","украшение для стены",["لا تجعل مكتبتك حلية تجمل الجدار، بل اقرأ فيها كي تتعلَّم",15,31,"Не делай свою библиотеку украшением стены, а читай, чтобы учиться."]],[11488,3,17,6,"صَعْبٌ هَضْمُهُ","трудно переварить",["هذا الدرس صعب هضمه",10,18,"Этот урок трудно «переварить»."]],[11489,3,17,6,"مُرّ كَرِيه","горький и противный",["الإغتراب مرٌّ كريه",9,18,"Жизнь на чужбине горька и противна."]],[11490,3,17,6,"أَزْعَجَ - يُزْعِجُ - إِزْعَاج","беспокоить, мешать • масдар: беспокойство",null],[11491,3,17,6,"أَسَرَّ - يُسِرُّ - إِسْرَار","скрывать, сообщать тайно • масдар: утаивание",null],[11492,3,17,6,"عَاشَرَ - يُعَاشِرُ - مُعَاشَرَة","общаться, жить вместе • масдар: совместная жизнь",null]];
